using System.Collections.Generic;
using System.Linq;
 
namespace CSharp
{
    /// <summary>
    /// A class for an "Integer with a history".
    /// <para>
    /// Note that it is not possible to create an empty Variable (so there is no "null") with this type. This is a design
    /// choice, because if "empty" variables were allowed, reading of empty variables must return a value. Null is a
    /// bad idea, and Java 8's Optional<T> (which is somewhat like the the official fix for the null-bad-idea) would
    /// make things more complicated than an example should be.
    /// </para>
    /// </summary>
    public class IntegerWithHistory
    {
        /// <summary>
        /// The "storage Backend" is a list of all values that have been ever assigned to this variable. The List is
        /// populated front to back, so a new value is inserted at the start (position 0), and older values move toward the end.
        /// </summary>
        private readonly List<int> history;
 
        /// <summary>
        /// Creates this variable and assigns the initial value
        /// </summary>
        /// <param name="value">initial value</param>
        public IntegerWithHistory(int value)
        {
            history = new List<int>();
            history.Add(value);
        }
 
        /// <summary>
        /// Sets a new value, pushing the older ones back in the history
        /// </summary>
        /// <param name="value">the new value to be assigned</param>
        public void Set(int value)
        {
            //History is populated from the front to the back, so the freshest value is stored a position 0
            history.Insert(0, value);
        }
 
        /// <summary>
        /// Gets the current value. Since history is populuated front to back, the current value is the first element
        /// of the history.
        /// </summary>
        /// <returns>the current value</returns>
        public int Get()
        {
            return history[0];
        }
 
        /// <summary>
        /// Gets the entire history all values that have been assigned to this variable.
        /// </summary>
        /// <returns>a List of all values, including the current one, ordered new to old</returns>
        public List<int> GetHistory()
        {
            return history.ToList();
        }
 
        /// <summary>
        /// Rolls back the history one step, so the current value is removed from the history and replaced by it's predecessor.
        /// This is a destructive operation! It is not possible to rollback() beyond the initial value!
        /// </summary>
        /// <returns>the value that had been the current value until history was rolled back.</returns>
        public int Rollback()
        {
            if (history.Count > 1)
            {
                return history.RemoveAt(0);
            }
            else
            {
                return history[0];
            }
        }
    }
}

public static double NthRoot(double m_nValue, double index, double guess, double pc)
 {
     double result = guess;
     double result_next;
     do
     {
         result_next = (1.0 / index) * ((index - 1.0) * result + (m_nValue) / (Math.Pow(result, (index - 1.0))));
         result = result_next;
         pc--;
     } while (pc > 1);
     return result;
 };

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            Matrix m = new Matrix(new double[,] { { 1, 2, -1, -4 }, { 2, 3, -1, -11 }, { -2, 0, -3, 22 } });
            Console.WriteLine(m.toReducedRowEchelonForm());
            Console.WriteLine();
            m = new Matrix(new double[,] { { 1, 2, 3, 7 }, { -4, 7, -2, 7 }, { 3, 3, 0, 7 } });
            Console.WriteLine(m.toReducedRowEchelonForm());
            Console.ReadLine();
        }
    }

    public class Matrix
    {
        private double[,] mtx;

        public Matrix(double[,] mtx)
        {
            this.mtx = mtx;
        }

        public int rows()
        {
            return mtx.GetLength(0);
        }

        public int columns()
        {
            return mtx.GetLength(1);
        }

        public Matrix toReducedRowEchelonForm()
        {
            int lead = 0;
            for (int r = 0; r < rows(); r++)
            {
                if (columns() <= lead)
                {
                    return this;
                }
                int i = r;
                while (mtx[i, lead] == 0)
                {
                    i++;
                    if (rows() == i)
                    {
                        i = r;
                        lead++;
                        if (columns() == lead)
                        {
                            return this;
                        }
                    }
                }

                double[] tmp = mtx[i, lead];
                mtx[i, lead] = mtx[r, lead];
                mtx[r, lead] = tmp;

                double val = mtx[r, lead];
                for (int j = 0; j < columns(); j++)
                {
                    mtx[r, j] /= val;
                }

                for (int i = 0; i < rows(); i++)
                {
                    if (i == r) continue;
                    val = mtx[i, lead];
                    for (int j = 0; j < columns(); j++)
                    {
                        mtx[i, j] -= val * mtx[r, j];
                    }
                }
                lead++;
            }
            return this;
        }

        public override string ToString()
        {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows(); i++)
            {
                for (int j = 0; j < columns(); j++)
                {
                    sb.Append(mtx[i, j] + " ");
                }
                sb.AppendLine();
            }
            return sb.ToString();
        }
    }
}

using System;
 
public class Program
{
	public static void Main()
	{
		var a = -460;
		var b = 6;
		bitwise(a, b);
	}
 
	public static void bitwise(int a, int b)
	{
		Console.WriteLine("a:   {0:X}", a);
		Console.WriteLine("b:   {0:X}", b);
 
		// Bitwise logical operations
		Console.WriteLine("and: {0:X}", a & b);
		Console.WriteLine("or:  {0:X}", a | b);
		Console.WriteLine("xor: {0:X}", a ^ b);
		Console.WriteLine("not: {0:X}", ~a);
 
		if (b < 0)
		{
			Console.WriteLine("Right operand is negative, but all shifts require an unsigned right operand (shift distance).");
			return;
		}
		var ua = (uint)a;
		var ub = (uint)b;
 
		// Logical shifts (unsigned left operand)
		Console.WriteLine("shl: {0:X}", ua << ub);
		Console.WriteLine("shr: {0:X}", ua >> ub);
 
		// Arithmetic shifts (signed left operand)
		Console.WriteLine("las: {0:X}", a << ub);
		Console.WriteLine("ras: {0:X}", a >> ub);
 
		// Rotations
		Console.WriteLine("rol: {0:X}", a << ub | (int)((uint)a >> (16 - ub)));
		Console.WriteLine("ror: {0:X}", (int)((uint)a >> ub) | a << (16 - ub));
	}
}

