using System;
using System.Linq;
using System.Numerics;
 
namespace ProjectEulerTasks
{
    internal static class Problem001
    {
        private static BigInteger Big2 = new BigInteger(2);
        private static BigInteger Big3 = new BigInteger(3);
        private static BigInteger Big5 = new BigInteger(5);
        private static BigInteger Big15 = Big3 * Big5;
 
        public static void Run()
        {
            Console.WriteLine($"The sum of multiples of 3 or 5 below 1000 is {Sum35(1000)}");
            var big100k = new BigInteger(100_000L);
            var e20 = big100k * big100k * big100k * big100k;
            Console.WriteLine($"The sum of multiples of 3 or 5 below 1e20 is {Sum35(e20)}");
        }
 
        private static int Sum35(int n)
        {
            return Enumerable.Range(3, n - 3).Where(x => x % 3 == 0 || x % 5 == 0).Sum();
        }
 
        private static BigInteger Sum35(BigInteger n)
        {
            var nn = n - BigInteger.One;
            var num3 = nn / Big3;
            var end3 = num3 * Big3;
            var sum3 = (Big3 + end3) * num3 / Big2;
            var num5 = nn / Big5;
            var end5 = num5 * Big5;
            var sum5 = (Big5 + end5) * num5 / Big2;
            var num15 = nn / Big15;
            var end15 = num15 * Big15;
            var sum15 = (Big15 + end15) * num15 / Big2;
            return sum3 + sum5 - sum15;
        }
    }
}

