namespace RomanNumerals
{
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                Console.WriteLine("MCMXC = " + Roman.ToInt("MCMXC"));
                Console.WriteLine("MMVIII = " + Roman.ToInt("MMVIII"));
                Console.WriteLine("MDCLXVI = " + Roman.ToInt("MDCLXVI"));
            }
            catch (Exception e)
            {
                Console.WriteLine(e.Message);
            }
        }
    }

    public class Roman
    {
        public static int ToInt(char c)
        {
            switch (c)
            {
                case 'I': return 1;
                case 'V': return 5;
                case 'X': return 10;
                case 'L': return 50;
                case 'C': return 100;
                case 'D': return 500;
                case 'M': return 1000;
            }
            throw new Exception("Invalid character");
        }

        public static int ToInt(string s)
        {
            int retval = 0, pvs = 0;
            for (int i = s.Length - 1; i >= 0; i--)
            {
                int inc = ToInt(s[i]);
                retval += inc < pvs? -inc : inc;
                pvs = inc;
            }
            return retval;
        }
    }
}

using System;

public class tiny_int
{
    public tiny_int(int i)
    {
        value = i;
        if (value < 1)
            throw new ArgumentOutOfRangeException("tiny_int: value smaller than 1");
        if (value > 10)
            throw new ArgumentOutOfRangeException("tiny_int: value larger than 10");
    }

    public static implicit operator int(tiny_int t)
    {
        return t.value;
    }

    public static tiny_int operator +(tiny_int t, int i)
    {
        return new tiny_int(t.value + i);
    }

    public static tiny_int operator -(tiny_int t, int i)
    {
        return new tiny_int(t.value - i);
    }

    public static tiny_int operator *(tiny_int t, int i)
    {
        return new tiny_int(t.value * i);
    }

    public static tiny_int operator /(tiny_int t, int i)
    {
        return new tiny_int(t.value / i);
    }

    public static tiny_int operator <<(tiny_int t, int i)
    {
        return new tiny_int(t.value << i);
    }

    public static tiny_int operator >>(tiny_int t, int i)
    {
        return new tiny_int(t.value >> i);
    }

    public static tiny_int operator &(tiny_int t, int i)
    {
        return new tiny_int(t.value & i);
    }

    public static tiny_int operator |(tiny_int t, int i)
    {
        return new tiny_int(t.value | i);
    }

    private int value;
}

// Every line starting with a double slash will be ignored by the processing machine,
// just like these two.
//
// Since the square root of 269,696 is approximately 519, we create a variable named "n"
// and give it this value.
  int n = 519;
 
// The while-condition is in parentheses
// * is for multiplication
// % is for modulo operation
// != is for "not equal"
  while ( ((n * n) % 1000000)!= 269696 )
    n = n + 1;
 
// n is incremented until the while-condition is met, so n should finally be the
// smallest positive integer whose square ends in the digits 269,696. To see n, we
// need to send it to the monitoring device (named console).
  Console.WriteLine(n);

public static bool IsLeapYear(int year)
{
    return year % 400 == 0 || (year % 100!= 0 && year % 4 == 0);
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Net;
 
namespace YahooSearch
{
    class Program
    {
        static void Main(string[] args)
        {
            YahooSearch yahooSearch = new YahooSearch("test");
 
            foreach (YahooResult result in yahooSearch.search_results)
            {
                Console.WriteLine(result.title);
            }
 
            Console.ReadLine();
        }
    }
 
    class YahooSearch
    {
        private string query;
        private int page;
        private string url;
        private string content;
        private List<YahooResult> results;
 
        public YahooSearch(string query, int page = 1)
        {
            this.query = query;
            this.page = page;
            this.url = "http://search.yahoo.com/search?p=" + this.query + "&b=" + ((this.page - 1) * 10 + 1);
            this.content = new WebClient().DownloadString(this.url);
        }
 
        public List<YahooResult> search_results
        {
            get
            {
                if (this.results == null)
                {
                    this.results = new List<YahooResult>();
 
                    foreach (Match match in Regex.Matches(this.content, "<a class=\"yschttl spt\" href=\".+?\">(.+?)</a></h3></div>(.+?)</div>.*?<span class=url>(.+?)</span>"))
                    {
                        this.results.Add(new YahooResult(fix(match.Groups[1].Value), fix(match.Groups[2].Value), fix(match.Groups[3].Value)));
                    }
                }
 
                return this.results;
            }
        }
 
        public YahooSearch nextpage
        {
            get
            {
                return new YahooSearch(this.query, this.page + 1);
            }
        }
 
        private static string fix(string x)
        {
            return Regex.Replace(Regex.Replace(x, "<[^<]*?>", ""), "&amp;", "&");
        }
    }
 
    class YahooResult
    {
        public string title;
        public string content;
        public string url;
 
        public YahooResult(string title, string content, string url)
        {
            this.title = title;
            this.content = content;
            this.url = url;
        }
    }
}

using System;
 
namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            const int samples = 1000000;
            Console.WriteLine("Generator  1 count  0 count  % 1 count");
            for (int n = 3; n <= 6; n++)
            {
                // function randN, per task description
                Func<int> randN = () =>
                {
                    if (new Random().Next(n) == 0)
                    {
                        return 1;
                    }
                    return 0;
                };
                int[] b = new int[2];
                for (int x = 0; x < samples; x++)
                {
                    b[randN()]++;
                }
                Console.WriteLine("randN({0})   {1,7}  {2,7}    {3,5:0.00}%",
                    n, b[1], b[0], (float)b[1] * 100 / samples);

                // function unbiased, per task description
                Func<int> unbiased = () =>
                {
                    int b1 = randN();
                    int b2 = randN();
                    while (b1 == b2)
                    {
                        b1 = randN();
                        b2 = randN();
                    }
                    return b1;
                };
                int[] u = new int[2];
                for (int x = 0; x < samples; x++)
                {
                    u[unbiased()]++;
                }
                Console.WriteLine("unbiased   {0,7}  {1,7}    {2,5:0.00}%",
                    u[1], u[0], (float)u[1] * 100 / samples);
            }
        }
    }
}

using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using System.Threading.Tasks;
 
namespace ImageCompare
{
	class Program
	{
		static void Main(string[] args)
		{
			var task = Compare("Lenna50.jpg", "Lenna100.jpg");
			task.Wait();
			Console.WriteLine(task.Result);
		}
 
		static async Task<double> Compare(string firstImage, string secondImage)
		{
			var img1 = await GetImageData(firstImage);
			var img2 = await GetImageData(secondImage);
 
			if (img1.Width!= img2.Width || img1.Height!= img2.Height)
			{
				return double.NaN;
			}
 
			var diff = 0.0;
 
			for (var i = 0; i < img1.Width * img1.Height; i++)
			{
				diff += Math.Abs(img1.Pixels[i].R - img2.Pixels[i].R) / 255.0;
				diff += Math.Abs(img1.Pixels[i].G - img2.Pixels[i].G) / 255.0;
				diff += Math.Abs(img1.Pixels[i].B - img2.Pixels[i].B) / 255.0;
			}
 
			return 100.0 * diff / (img1.Width * img1.Height * 3);
		}
 
		static async Task<ImageData> GetImageData(string url)
		{
			var img = new Bitmap(url);
			var canvas = new Bitmap(img.Width, img.Height);
			var g = Graphics.FromImage(canvas);
			g.DrawImage(img, 0, 0);
			var imgData = canvas.LockBits(new Rectangle(0, 0, img.Width, img.Height), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
			var pixels = new Color[img.Width * img.Height];
			Marshal.Copy(imgData.Scan0, pixels, 0, pixels.Length);
			canvas.UnlockBits(imgData);
			return new ImageData(img.Width, img.Height, pixels);
		}
 
		class ImageData
		{
			public int Width { get; }
			public int Height { get; }
			public Color[] Pixels { get; }
 
			public ImageData(int width, int height, Color[] pixels)
			{
				Width = width;
				Height = height;
				Pixels = pixels;
			}
		}
	}
}

