using System;

public class HofstadterQSequence
{
    public static void Main()
    {
        const int size = 100000;
        int[] hofstadters = new int[size];
        hofstadters[0] = 1;
        hofstadters[1] = 1;
        for (int i = 3; i < size; i++)
        {
            hofstadters[i - 1] = hofstadters[i - 1 - hofstadters[i - 1 - 1]] + hofstadters[i - 1 - hofstadters[i - 2 - 1]];
        }
        Console.Write("The first 10 numbers are: ");
        for (int i = 0; i < 10; i++)
        {
            Console.Write(hofstadters[i] + " ");
        }
        Console.WriteLine();
        Console.WriteLine("The 1000'th term is " + hofstadters[999] + "!");
        int less_than_preceding = 0;
        for (int i = 0; i < size - 1; i++)
        {
            if (hofstadters[i + 1] < hofstadters[i])
            {
                less_than_preceding++;
            }
        }
        Console.WriteLine("In array of size: " + size + ", " + less_than_preceding + " times a number was preceded by a greater number!");
    }
}

