using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.IO;
 
namespace License
{
    class Program
    {
        const int INOUT_LEN = 4;
        const int TIME_LEN = 20;
        const int MAX_MAXOUT = 1000;
        static string[] inout = new string[INOUT_LEN];
        static string[] time = new string[TIME_LEN];
        static uint jobnum;
        static string[,] maxtime = new string[MAX_MAXOUT, TIME_LEN];
        static void Main(string[] args)
        {
            StreamReader inStream = null;
            int l_out = 0, maxout = -1, maxcount = 0;
            if (args.Length > 1)
            {
                inStream = new StreamReader(args[1]);
                if (inStream == null)
                {
                    Console.WriteLine("cannot read {0}", args[1]);
                    Environment.Exit(1);
                }
            }
            else
            {
                inStream = new StreamReader(Console.OpenStandardInput());
            }
            while (inStream.EndOfStream == false)
            {
                string line = inStream.ReadLine();
                string[] tokens = line.Split(' ');
                inout[0] = tokens[1];
                time[0] = tokens[3];
                jobnum = uint.Parse(tokens[5]);
                if (inout[0] == "OUT")
                    l_out++;
                else
                    l_out--;
                if (l_out > maxout)
                {
                    maxout = l_out;
                    maxcount = 0;
                    maxtime[0, 0] = "";
                }
                if (l_out == maxout)
                {
                    if (maxcount < MAX_MAXOUT)
                    {
                        maxtime[maxcount, 0] = time[0];
                        maxcount++;
                    }
                    else
                    {
                        Console.WriteLine("increase MAX_MAXOUT (now it is {0})", MAX_MAXOUT);
                        Environment.Exit(1);
                    }
                }
            }
            Console.WriteLine("Maximum simultaneous license use is {0} at the following times:", maxout);
            for (l_out = 0; l_out < maxcount; l_out++)
            {
                Console.WriteLine(maxtime[l_out, 0]);
