using System;
using System.Collections.Generic;
 
namespace MutualRecursion
{
    class MutualRecursion
    {
        static void Main(string[] args)
        {
            int max = 20;
            Console.WriteLine("First {0} values of the Female sequence: ", max);
            for (int i = 0; i < max; i++)
            {
                Console.WriteLine("  f({0}) = {1}", i, f(i));
            }
            Console.WriteLine("First {0} values of the Male sequence: ", max);
            for (int i = 0; i < 20; i++)
            {
                Console.WriteLine("  m({0}) = {1}", i, m(i));
            }
        }
 
        private static Dictionary<int, int> F_MAP = new Dictionary<int, int>();
 
        private static int f(int n)
        {
            if (F_MAP.ContainsKey(n))
            {
                return F_MAP[n];
            }
            int fn = n == 0? 1 : n - m(f(n - 1));
            F_MAP.Add(n, fn);
            return fn;
        }
 
        private static Dictionary<int, int> M_MAP = new Dictionary<int, int>();
 
        private static int m(int n)
        {
            if (M_MAP.ContainsKey(n))
            {
                return M_MAP[n];
            }
            int mn = n == 0? 0 : n - f(m(n - 1));
            M_MAP.Add(n, mn);
            return mn;
        }
    }
}

using System;
using System.Linq;
 
namespace PermutationTest
{
    class Program
    {
        static void Main(string[] args)
        {
            var treatmentGroup = new[] { 85, 88, 75, 66, 25, 29, 83, 39, 97 };
            var controlGroup = new[] { 68, 41, 10, 49, 16, 65, 32, 92, 28, 98 };
            var under = PermutationTest(treatmentGroup, controlGroup);
            Console.WriteLine("under={0:0.00}%, over={1:0.00}%", under, 100 - under);
        }
 
        static double PermutationTest(int[] a, int[] b)
        {
            var ab = a.Concat(b).ToArray();
            var tobs = Statistic(ab, a);
            var under = 0;
            var count = 0;
            for (var i = 0; i < ab.Length; i++)
            {
                var perm = new int[a.Length];
                for (var j = 0; j < perm.Length; j++)
                {
                    perm[j] = ab[i + j];
                }
                if (Statistic(ab, perm) <= tobs)
                {
                    under++;
                }
                count++;
            }
            return under * 100.0 / count;
        }
 
        static double Statistic(int[] ab, int[] a)
        {
            var sumab = ab.Sum();
            var suma = a.Sum();
            return suma / (double)a.Length - (sumab - suma) / (double)(ab.Length - a.Length);
        }
    }
}

