namespace Circle
{
    class Program
    {
        static void Main(string[] args)
        {
            var td = new List<Tuple<Point, Point, double>>
            {
                new Tuple<Point, Point, double>(new Point(0.1234, 0.9876), new Point(0.8765, 0.2345), 2.0),
                new Tuple<Point, Point, double>(new Point(0.0000, 2.0000), new Point(0.0000, 0.0000), 1.0),
                new Tuple<Point, Point, double>(new Point(0.1234, 0.9876), new Point(0.1234, 0.9876), 2.0),
                new Tuple<Point, Point, double>(new Point(0.1234, 0.9876), new Point(0.8765, 0.2345), 0.5),
                new Tuple<Point, Point, double>(new Point(0.1234, 0.9876), new Point(0.1234, 0.9876), 0.0),
            };

            foreach (var tc in td)
            {
                Console.WriteLine("p1: " + tc.Item1);
                Console.WriteLine("p2: " + tc.Item2);
                Console.WriteLine("r: " + tc.Item3);
                var c1 = new Point();
                var c2 = new Point();
                var Case = Circles(tc.Item1, tc.Item2, tc.Item3, ref c1, ref c2);
                Console.WriteLine("  " + Case);
                switch (Case)
                {
                    case "CoR0":
                    case "Diam":
                        Console.WriteLine("   Center: " + c1);
                        break;
                    case "Two":
                        Console.WriteLine("   Center 1: " + c1);
                        Console.WriteLine("   Center 2: " + c2);
                        break;
                }
                Console.WriteLine();
            }
        }

        private static string Circles(Point p1, Point p2, double r, ref Point c1, ref Point c2)
        {
            if (p1 == p2)
            {
                if (r == 0)
                {
                    return "CoR0";
                }
                return "Co";
            }
            if (r == 0)
            {
                return "R0";
            }
            var dx = p2.X - p1.X;
            var dy = p2.Y - p1.Y;
            var q = Math.Sqrt(dx * dx + dy * dy);
            if (q > 2 * r)
            {
                return "Far";
            }
            var m = new Point((p1.X + p2.X) / 2, (p1.Y + p2.Y) / 2);
            if (q == 2 * r)
            {
                return "Diam";
            }
            var d = Math.Sqrt(r * r - q * q / 4);
            var ox = d * dx / q;
            var oy = d * dy / q;
            c1 = new Point(m.X - oy, m.Y + ox);
            c2 = new Point(m.X + oy, m.Y - ox);
            return "Two";
        }
    }

    public class Point
    {
        public double X { get; set; }
        public double Y { get; set; }

        public Point()
        {
        }

        public Point(double x, double y)
        {
            X = x;
            Y = y;
        }

        public override string ToString()
        {
            return string.Format("({0}, {1})", X, Y);
        }
    }
}

