public class Node<T> where T : Number
{
    public T data;
    public Node<T> prev;
    public Node<T> next;
    public Node(T data, Node<T> prev = null, Node<T> next = null)
    {
        this.data = data;
        this.prev = prev;
        this.next = next;
    }
    public override string ToString()
    {
        var sb = new StringBuilder(this.data.ToString());
        var node = this.next;
        while (node!= null)
        {
            sb.Append(" -> ", node.data.ToString());
            node = node.next;
        }
        return sb.ToString();
    }
}
 
public static void insert<T>(Node<T> after, Node<T> new) where T : Number
{
    new.next = after.next;
    if (after.next!= null)
        after.next.prev = new;
    new.prev = after;
    after.next = new;
}
 
public static void Main(string[] args)
{
    var a = new Node<int>(1);
    var b = new Node<int>(3, a);
    a.next = b;
    Console.WriteLine("Before insertion : " + a);
    var c = new Node<int>(2);
    insert(a, c);
    Console.WriteLine("After  insertion : " + a);
}

