namespace Shoelace
{
    class Program
    {
        struct point
        {
            public double x, y;
        }
 
        static double shoelace(string inputFile)
        {
            int i, numPoints;
            double leftSum = 0, rightSum = 0;
 
            point[] pointSet;
            StreamReader fp = new StreamReader(inputFile);
 
            numPoints = Convert.ToInt32(fp.ReadLine());
 
            pointSet = new point[numPoints + 1];
 
            for (i = 0; i < numPoints; i++)
            {
                string[] line = fp.ReadLine().Split(' ');
                pointSet[i].x = Convert.ToDouble(line[0]);
                pointSet[i].y = Convert.ToDouble(line[1]);
            }
 
            fp.Close();
 
            pointSet[numPoints] = pointSet[0];
 
            for (i = 0; i < numPoints; i++)
            {
                leftSum += pointSet[i].x * pointSet[i + 1].y;
                rightSum += pointSet[i + 1].x * pointSet[i].y;
            }
 
            return 0.5 * Math.Abs(leftSum - rightSum);
        }
 
        static void Main(string[] args)
        {
            if (args.Length == 0)
                Console.WriteLine("\nUsage : {0} <full path of polygon vertices file>", args[0]);
 
            else
                Console.WriteLine("The polygon area is {0} square units.", shoelace(args[0]));
        }
    }
}

