namespace Riddler
{
    class Program
    {
        static void Main(string[] args)
        {
            int coconuts = 11;
            outer:
            for (int ns = 2; ns <= 9; ns++)
            {
                int[] hidden = new int[ns];
                coconuts = (coconuts / ns) * ns + 1;
                while (true)
                {
                    int nc = coconuts;
                    for (int s = 1; s <= ns; s++)
                    {
                        if (nc % ns == 1)
                        {
                            hidden[s - 1] = nc / ns;
                            nc -= hidden[s - 1] + 1;
                            if (s == ns && nc % ns == 0)
                            {
                                Console.WriteLine($"{ns} sailors require a minimum of {coconuts} coconuts");
                                for (int t = 1; t <= ns; t++)
                                    Console.WriteLine($"\tSailor {t} hides {hidden[t - 1]}");
                                Console.WriteLine($"\tThe monkey gets {ns}");
                                Console.WriteLine($"\tFinally, each sailor takes {nc / ns}\n");
                                continue outer;
                            }
                        }
                        else
                            break;
                    }
                    coconuts += ns;
                }
            }
        }
    }
