namespace LinearCombination
{
    class Program
    {
        static void Main(string[] args)
        {
            var combos = new List<int[]>
            {
                new int[] {1, 2, 3},
                new int[] {0, 1, 2, 3},
                new int[] {1, 0, 3, 4},
                new int[] {1, 2, 0},
                new int[] {0, 0, 0},
                new int[] {0},
                new int[] {1, 1, 1},
                new int[] {-1, -1, -1},
                new int[] {-1, -2, 0, -3},
                new int[] {-1},
            };
            foreach (var c in combos)
            {
                var t = string.Join(", ", c);
                Console.WriteLine($"{t,-15}  ->  {LinearCombo(c)}");
            }
        }
 
        static string LinearCombo(int[] c)
        {
            var sb = new StringBuilder();
            for (int i = 0; i < c.Length; i++)
            {
                var n = c[i];
                if (n == 0)
                {
                    continue;
                }
                var op = "";
                switch (n)
                {
                    case int x when x < 0 && sb.Length == 0:
                        op = "-";
                        break;
                    case int x when x < 0:
                        op = " - ";
                        break;
                    case int x when x > 0 && sb.Length == 0:
                        op = "";
                        break;
                    default:
                        op = " + ";
                        break;
                }
                var av = n;
                if (av < 0)
                {
                    av = -av;
                }
                var coeff = $"{av}*";
                if (av == 1)
                {
                    coeff = "";
                }
                sb.Append($"{op}{coeff}e({i + 1})");
            }
            if (sb.Length == 0)
            {
                return "0";
            }
            else
            {
                return sb.ToString();
            }
        }
    }
}

