                //	 s.r: w, m, n
                "a.1: 1, L, a",
                "a.B: 1, S, h"
            );

            tm("Unary adder",
                1, 0, 0, '0', "1110111",
                "1.1: 0, R, 2", // write 0 rigth goto 2
                "2.1: 1, R, 2", // while (1) rigth
                "2.0: 1, S, 0"  // write 1 stay halt
            );

            tm("Three-state busy beaver",
                1, 0, 0, '0', "0",
                "1.0: 1, R, 2",
                "1.1: 1, R, 0",
                "2.0: 0, R, 3",
                "2.1: 1, R, 2",
                "3.0: 1, L, 3",
                "3.1: 1, L, 1"
            );
        }

        static void tm(string d, char s, char e, int i, char b, string t, params string[] r)
        {
            Console.WriteLine(d);
            if (i < 0 || i >= t.Length) return;
            var re = new System.Text.RegularExpressions.Regex(b.ToString(), System.Text.RegularExpressions.RegexOptions.None);
            write('*', s, i, t = t.ToCharArray());
            var p = new Dictionary<string, (char w, int m, char n)>();
            r.ToList().ForEach(e => ((char s, char r, char w, char m, char n) => p[s + '.' + r] = (w, "RL".IndexOf(m) - 1, n))(e.Split(new char[] {'', '.', ',', ':' }, StringSplitOptions.RemoveEmptyEntries)));
            for (var n = 1; s!= e; n += 1)
            {
                var (w, m, n1) = p[s + '.' + t[i]];
                t[i] = w;
                s = n1;
                i += m;
                if (i == -1) i = 0, t.ToList().Insert(0, b);
                else if (i == t.Length) t[i] = b;
                write(n, s, i, t);
            }
            Console.WriteLine();
            void write(char n, char s, int i, char[] t)
            {
                t = t.ToArray();
                t = t.Take(i).Concat(new char[] { '<' }).Concat(new char[] { t[i] }).Concat(new char[] { '>' }).Concat(t.Skip(i + 1)).ToArray();
                Console.WriteLine(string.Format("{0}: {1} [{2}]", string.Format("{0,3}", n), s, new string(t).Replace(b.ToString(), " ")));
            }
        }
    }
}

