namespace Hofstadter_Conway_10000_sequence
{
    class HofstadterConwaySequence
    {
        private static int MAX = (int)Math.Pow(2, 20) + 1;
        private static int[] HCS = new int[MAX];
        static HofstadterConwaySequence()
        {
            HCS[1] = 1;
            HCS[2] = 1;
            for (int n = 3; n < MAX; n++)
            {
                int nm1 = HCS[n - 1];
                HCS[n] = HCS[nm1] + HCS[n - nm1];
            }
        }

        public static void Main(string[] args)
        {
            int mNum = 0;
            for (int m = 1; m < 20; m++)
            {
                int min = (int)Math.Pow(2, m);
                int max = min * 2;
                double maxRatio = 0.0;
                int nVal = 0;
                for (int n = min; n <= max; n++)
                {
                    double ratio = (double)HCS[n] / n;
                    if (ratio > maxRatio)
                    {
                        maxRatio = Math.Max(ratio, maxRatio);
                        nVal = n;
                    }
                    if (ratio >= 0.55)
                    {
                        mNum = n;
                    }
                }
                Console.WriteLine("Max ratio between 2^{0} and 2^{1} is {2} at n = {3}", m, m + 1, maxRatio, nVal);
            }
            Console.WriteLine("Mallow's number is {0}.", mNum);
        }
    }
}

