using System;
 
public class Wilson
{
    public static void Main()
    {
        Console.WriteLine("  n | prime?\n------------");
        foreach (var p in new[] { 2, 3, 9, 15, 29, 37, 47, 57, 67, 77, 87, 97, 237, 409, 659 })
        {
            Console.WriteLine("{0,3} | {1}", p, IsPrime(p));
        }
        Console.WriteLine("\nFirst 120 primes by Wilson's theorem:");
        var n = 0;
        var p = 1;
        while (n < 120)
        {
            if (IsPrime(p))
            {
                n++;
                Console.Write("{0,3}{1}", p, n % 20 == 0? "\n" : " ");
            }
            p++;
        }
        Console.WriteLine("\n1000th through 1015th primes:");
        n = 0;
        p = 1;
        var i = 0;
        while (n < 1015)
        {
            if (IsPrime(p))
            {
                n++;
                if (n >= 1000)
                {
                    i++;
                    Console.Write("{0,3}{1}", p, i % 16 == 0? "\n" : " ");
                }
            }
            p++;
        }
    }
 
    private static bool IsPrime(int p)
    {
        return p > 1 && FactorialMod(p - 1, p) == p - 1;
    }
 
    private static int FactorialMod(int n, int p)
    {
        var f = 1;
        while (n!= 0 && f!= 0)
        {
            f = (f * n) % p;
            n--;
        }
        return f;
    }
}

