    class Program
    {
        static void Main(string[] args)
        {
            var random = new Random();
            while (true)
            {
                var values = new int[6];
                var vsum = 0;
                for (var i = 0; i < values.Length; i++)
                {
                    var numbers = new int[4];
                    for (var j = 0; j < numbers.Length; j++)
                    {
                        numbers[j] = 1 + random.Next(6);
                    }
                    Array.Sort(numbers);
                    var nsum = 0;
                    for (var j = 1; j < numbers.Length; j++)
                    {
                        nsum += numbers[j];
                    }
                    values[i] = nsum;
                    vsum += values[i];
                }
                if (vsum < 75)
                {
                    continue;
                }
                var vcount = 0;
                for (var i = 0; i < values.Length; i++)
                {
                    if (values[i] >= 15)
                    {
                        vcount++;
                    }
                }
                if (vcount < 2)
                {
                    continue;
                }
                Console.WriteLine("The 6 random numbers generated are:");
                Console.WriteLine(string.Join(", ", values));
                Console.WriteLine("\nTheir sum is {0} and {1} of them are >= 15", vsum, vcount);
