using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace LZW
{
    class Program
    {
        static void Main(string[] args)
        {
            var comp = LZW.compress("TOBEORNOTTOBEORTOBEORNOT");
            var decomp = LZW.decompress(comp);
            Console.WriteLine(comp);
            Console.WriteLine(decomp);
            Console.ReadKey();
        }
    }

    public class LZW
    {
        public static List<int> compress(string uncompressed)
        {
            // Build the dictionary.
            int i;
            Dictionary<string, int> dictionary = new Dictionary<string, int>();
            string c;
            string wc;
            string w = "";
            List<int> result = new List<int>();
            int dictSize = 256;
            for (i = 0; i < 256; i += 1)
            {
                dictionary.Add(Convert.ToString(Convert.ToChar(i)), i);
            }

            for (i = 0; i < uncompressed.Length; i += 1)
            {
                c = Convert.ToString(uncompressed[i]);
                wc = w + c;
                //Do not use dictionary[wc] because javascript arrays 
                //will return values for array['pop'], array['push'] etc
                // if (dictionary[wc]) {
                if (dictionary.ContainsKey(wc))
                {
                    w = wc;
                }
                else
                {
                    result.Add(dictionary[w]);
                    // Add wc to the dictionary.
                    dictionary.Add(wc, dictSize++);
                    w = c;
                }
            }

            // Output the code for w.
            if (w!= "")
            {
                result.Add(dictionary[w]);
            }
            return result;
        }

        public static string decompress(List<int> compressed)
        {
            // Build the dictionary.
            int i;
            Dictionary<int, string> dictionary = new Dictionary<int, string>();
            string w;
            string result;
            string entry = "";
            int k;
            int dictSize = 256;
            for (i = 0; i < 256; i += 1)
            {
                dictionary.Add(i, Convert.ToString(Convert.ToChar(i)));
            }

            w = Convert.ToString(Convert.ToChar(compressed[0]));
            result = w;
            for (i = 1; i < compressed.Count; i += 1)
            {
                k = compressed[i];
                if (dictionary.ContainsKey(k))
                {
                    entry = dictionary[k];
                }
                else
                {
                    if (k == dictSize)
                    {
                        entry = w + w[0];
                    }
                    else
                    {
                        return null;
                    }
                }

                result += entry;

                // Add w+entry[0] to the dictionary.
                dictionary.Add(dictSize++, w + entry[0]);

                w = entry;
            }
            return result;
        }
    }
}

