using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace VectorProds
{
    public class Vector3D<T> where T : struct
    {
        private T a, b, c;

        public Vector3D(T a, T b, T c)
        {
            this.a = a;
            this.b = b;
            this.c = c;
        }

        public double dot(Vector3D<T> vec)
        {
            return (Convert.ToDouble(a) * Convert.ToDouble(vec.a) +
                    Convert.ToDouble(b) * Convert.ToDouble(vec.b) +
                    Convert.ToDouble(c) * Convert.ToDouble(vec.c));
        }

        public Vector3D<double> cross(Vector3D<T> vec)
        {
            double newA = Convert.ToDouble(b) * Convert.ToDouble(vec.c) - Convert.ToDouble(c) * Convert.ToDouble(vec.b);
            double newB = Convert.ToDouble(c) * Convert.ToDouble(vec.a) - Convert.ToDouble(a) * Convert.ToDouble(vec.c);
            double newC = Convert.ToDouble(a) * Convert.ToDouble(vec.b) - Convert.ToDouble(b) * Convert.ToDouble(vec.a);
            return new Vector3D<double>(newA, newB, newC);
        }

        public double scalTrip(Vector3D<T> vecB, Vector3D<T> vecC)
        {
            return this.dot(vecB.cross(vecC));
        }

        public Vector3D<double> vecTrip(Vector3D<T> vecB, Vector3D<T> vecC)
        {
            return this.cross(vecB.cross(vecC));
        }

        public override string ToString()
        {
            return "<" + a.ToString() + ", " + b.ToString() + ", " + c.ToString() + ">";
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            Vector3D<int> a = new Vector3D<int>(3, 4, 5);
            Vector3D<int> b = new Vector3D<int>(4, 3, 5);
            Vector3D<int> c = new Vector3D<int>(-5, -12, -13);

            Console.WriteLine(a.dot(b));
            Console.WriteLine(a.cross(b));
            Console.WriteLine(a.scalTrip(b, c));
            Console.WriteLine(a.vecTrip(b, c));
        }
    }
}

#include <iostream>
#include <cmath>
 
const double R = 6371;
const double TO_RAD = (3.1415926536 / 180);
 
double dist(double th1, double ph1, double th2, double ph2)
{
	double dx, dy, dz;
	ph1 -= ph2;
	ph1 *= TO_RAD, th1 *= TO_RAD, th2 *= TO_RAD;
 
	dz = sin(th1) - sin(th2);
	dx = cos(ph1) * cos(th1) - cos(th2);
	dy = sin(ph1) * cos(th1);
	return asin(sqrt(dx * dx + dy * dy + dz * dz) / 2) * 2 * R;
}
 
int main()
{
	double d = dist(36.12, -86.67, 33.94, -118.4);
	/* Americans don't know kilometers */
	std::cout << "dist: " << d << " km (" << d / 1.609344 << " mi.)" << std::endl;
 
	return 0;
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace ConsoleApplication1
{
    class Program
    {
        static string[] TENS = { null, null, "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety" };
        static string[] SMALL = { "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen" };
        static string[] HUGE = { null, null, "million", "billion", "trillion", "quadrillion", "quintillion", "sextillion", "septillion", "octillion", "nonillion", "decillion" };
 
        static string nonzero(string c, int n, string connect = "")
        {
            return n == 0? "" : connect + c + spell_integer(n);
        }
 
        static string last_and(string num)
        {
            if (num.Contains(','))
            {
                string[] pre_last = num.Split(',');
                string last = pre_last[pre_last.Length - 1];
                if (!last.Contains("and"))
                {
                    last = "and" + last;
                }
                num = string.Join(",", pre_last) + "," + last;
            }
            return num;
        }
 
        static string big(int e, int n)
        {
            if (e == 0)
            {
                return spell_integer(n);
            }
            else if (e == 1)
            {
                return spell_integer(n) + " thousand";
            }
            else
            {
                return spell_integer(n) + " " + HUGE[e];
            }
        }
 
        static IEnumerable<int> base1000_rev(int n)
        {
            while (n!= 0)
            {
                n = Math.DivRem(n, 1000, out int r);
                yield return r;
            }
        }
 
        static string spell_integer(int n)
        {
            if (n < 0)
            {
                return "minus " + spell_integer(-n);
            }
            else if (n < 20)
            {
                return SMALL[n];
            }
            else if (n < 100)
            {
                int a = n / 10;
                int b = n % 10;
                return TENS[a] + nonzero("-", b);
            }
            else if (n < 1000)
            {
                int a = n / 100;
                int b = n % 100;
                return SMALL[a] + " hundred" + nonzero(" ", b, " and");
            }
            else
            {
                string num = string.Join(", ", base1000_rev(n).Where(x => x!= 0).Reverse().Select((x, e) => big(e, x)));
                return last_and(num);
            }
        }
 
        static void Main(string[] args)
        {
            // examples
            for (int n = 0; n < 20; n++)
            {
                Console.WriteLine("{0,4} -> {1}", n, spell_integer(n));
            }
            Console.WriteLine();
 
            int m = 201021002001;
            while (m!= 0)
            {
                Console.WriteLine("{0,12} -> {1}", m, spell_integer(m));
                m /= -10;
            }
            Console.WriteLine("{0,12} -> {1}", m, spell_integer(m));
            Console.WriteLine();
 
            Console.ReadKey();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace BWT
{
    class Program
    {
        const int STX = 0x02;
        const int ETX = 0x03;
 
        static void rotate(ref string a)
        {
            char t = a[a.Length - 1];
            for (int i = a.Length - 1; i > 0; i--)
            {
                a = a.Remove(i, 1);
                a = a.Insert(i - 1, t.ToString());
            }
            a = a.Remove(0, 1);
            a = a.Insert(0, t.ToString());
        }
 
        static string bwt(string s)
        {
            foreach (char c in s)
            {
                if (c == STX || c == ETX)
                {
                    throw new Exception("Input can't contain STX or ETX");
                }
            }
 
            string ss = "";
            ss += STX;
            ss += s;
            ss += ETX;
 
            List<string> table = new List<string>();
            for (int i = 0; i < ss.Length; i++)
            {
                table.Add(ss);
                rotate(ref ss);
            }
            table.Sort();
 
            string outp = "";
            foreach (string s1 in table)
            {
                outp += s1[s1.Length - 1];
            }
            return outp;
        }
 
        static string ibwt(string r)
        {
            int len = r.Length;
            List<string> table = new List<string>();
            for (int i = 0; i < len; i++)
            {
                for (int j = 0; j < len; j++)
                {
                    table.Add(r[j] + table[j]);
                }
                table.Sort();
            }
            foreach (string row in table)
            {
                if (row[row.Length - 1] == ETX)
                {
                    return row.Substring(1, row.Length - 2);
                }
            }
            return "";
        }
 
        static string makePrintable(string s)
        {
            string ls = s;
            for (int i = 0; i < ls.Length; i++)
            {
                if (ls[i] == STX)
                {
                    ls = ls.Remove(i, 1);
                    ls = ls.Insert(i, "^");
                }
                else if (ls[i] == ETX)
                {
                    ls = ls.Remove(i, 1);
                    ls = ls.Insert(i, "|");
                }
            }
            return ls;
        }
 
        static void Main(string[] args)
        {
            string[] tests = {
                "banana",
                "appellee",
                "dogwood",
                "TO BE OR NOT TO BE OR WANT TO BE OR NOT?",
                "SIX.MIXED.PIXIES.SIFT.SIXTY.PIXIE.DUST.BOXES",
                "\u0002ABC\u0003"
            };
 
            foreach (string test in tests)
            {
                Console.WriteLine(makePrintable(test));
                Console.WriteLine(" --> ");
 
                string t = "";
                try
                {
                    t = bwt(test);
                    Console.WriteLine(makePrintable(t));
                }
                catch (Exception e)
                {
                    Console.WriteLine("Error " + e.Message);
                }
 
                string r = ibwt(t);
                Console.WriteLine(" --> " + r);
                Console.WriteLine();
            }
 
            Console.ReadKey();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Length of the deck of cards | Perfect shuffles needed to obtain the same deck back");
            for (int length = 8; length <= 10000; length *= 2)
            {
                List<int> deck = Enumerable.Range(0, length).ToList();
                int shuffles_needed = AfterHowManyIsEqual(MagicShuffle, deck, deck);
                Console.WriteLine("{0} | {1}", length, shuffles_needed);
            }
        }
 
        static List<int> MagicShuffle(List<int> deck)
        {
            int half = deck.Count / 2;
            return deck.Select((x, i) => new { Index = i, Value = x })
               .GroupBy(x => x.Index / half)
               .SelectMany(x => x.Select(y => y.Value))
               .ToList();
        }
 
        static int AfterHowManyIsEqual<T>(Func<List<T>, List<T>> shuffle_type, List<T> start, List<T> end)
        {
            start = shuffle_type(start);
            int counter = 1;
            while (!start.SequenceEqual(end))
            {
                start = shuffle_type(start);
                counter++;
            }
            return counter;
        }
    }
}

using System;
