using System;
using System.Drawing;
using System.Windows.Forms;

namespace BarnsleyFern
{
    public partial class Form1 : Form
    {
        public Form1()
        {
            InitializeComponent();
        }

        private void Form1_Load(object sender, EventArgs e)
        {
            pBarnsleyFern(pictureBox1, 100000);
        }

        // DCLs
        private Bitmap bitmap;
        private Graphics g;
        private int w, h;
        private double x, y, xw, yw;
        private Random r = new Random();

        // Like in PARI/GP: return random number 0..max-1
        private int randgp(int max)
        {
            return r.Next(max);
        }

        // Clean canvas
        private void cleanCanvas()
        {
            g.FillRectangle(Brushes.White, 0, 0, w, h);
        }

        // MAIN LOOP
        private void pBarnsleyFern(PictureBox canvas, int lim)
        {
            // DCLs
            w = canvas.Width;
            h = canvas.Height;
            bitmap = new Bitmap(w, h);
            g = Graphics.FromImage(bitmap);
            x = 0.;
            y = 0.;
            xw = 0.;
            yw = 0.;
            // Clean canvas
            cleanCanvas();
            // MAIN LOOP
            for (int i = 0; i < lim; i++)
            {
                int r = randgp(100);
                if (r <= 1)
                {
                    xw = 0;
                    yw = 0.16 * y;
                }
                else if (r <= 8)
                {
                    xw = 0.2 * x - 0.26 * y;
                    yw = 0.23 * x + 0.22 * y + 1.6;
                }
                else if (r <= 15)
                {
                    xw = -0.15 * x + 0.28 * y;
                    yw = 0.26 * x + 0.24 * y + 0.44;
                }
                else
                {
                    xw = 0.85 * x + 0.04 * y;
                    yw = -0.04 * x + 0.85 * y + 1.6;
                }
                x = xw;
                y = yw;
                g.FillRectangle(Brushes.Green, (float)(x * 50 + 260), (float)(-y * 50 + 540), 1, 1);
            } //fend i
            canvas.Image = bitmap;
        }
    }
}

public static TreeSet<long> factors(long n)
{
    TreeSet<long> factors = new TreeSet<long>();
    factors.Add(n);
    factors.Add(1L);
    for (long test = n - 1; test >= Math.Sqrt(n); test--)
        if (n % test == 0)
        {
            factors.Add(test);
            factors.Add(n / test);
        }
    return factors;
}

using System;
 
namespace VirtualClone
{
    class T
    {
        public virtual void Identify()
        {
            Console.WriteLine("I am a genuine T");
        }
        public virtual T Clone()
        {
            return (T)this.MemberwiseClone();
        }
    }
 
    class S : T
    {
        public override void Identify()
        {
            Console.WriteLine("I am an S");
        }
        public override S Clone()
        {
            return (S)this.MemberwiseClone();
        }
    }
 
    class X
    {
        public X(T t)
        {
            member = t;
        }
 
        public X(X other)
        {
            member = other.member.Clone();
        }
 
        public void IdentifyMember()
        {
            member.Identify();
        }
 
        private T member;
    }
 
    class Program
    {
        static void Main(string[] args)
        {
            X original = new X(new S());
            X copy = new X(original);
            copy.IdentifyMember();
        }
    }
}

