using System;
using System.Linq;

public class NumberClassifications
{
    public static void Main(string[] args)
    {
        int deficient = 0;
        int perfect = 0;
        int abundant = 0;

        for (long i = 1; i <= 20_000; i++)
        {
            long sum = properDivsSum(i);
            if (sum < i)
                deficient++;
            else if (sum == i)
                perfect++;
            else
                abundant++;
        }
        Console.WriteLine("Deficient: " + deficient);
        Console.WriteLine("Perfect: " + perfect);
        Console.WriteLine("Abundant: " + abundant);
    }

    public static long properDivsSum(long n)
    {
        return Enumerable.Range(1, (int)((n + 1) / 2)).Where(i => n!= i && n % i == 0).Sum();
    }
}

