using System;
 
public class Logic
{
	public enum Trit
	{
		TRUE,
		MAYBE,
		FALSE
	}
 
	public static Trit and(Trit a, Trit b)
	{
		if (a == Trit.TRUE)
		{
			return b;
		}
		else if (a == Trit.MAYBE)
		{
			return (b == Trit.FALSE)? Trit.FALSE : Trit.MAYBE;
		}
		else
		{
			return Trit.FALSE;
		}
	}
 
	public static Trit or(Trit a, Trit b)
	{
		if (a == Trit.TRUE)
		{
			return Trit.TRUE;
		}
		else if (a == Trit.MAYBE)
		{
			return (b == Trit.TRUE)? Trit.TRUE : Trit.MAYBE;
		}
		else
		{
			return b;
		}
	}
 
	public static Trit tIf(Trit a, Trit b)
	{
		if (a == Trit.TRUE)
		{
			return b;
		}
		else if (a == Trit.MAYBE)
		{
			return (b == Trit.TRUE)? Trit.TRUE : Trit.MAYBE;
		}
		else
		{
			return Trit.TRUE;
		}
	}
 
	public static Trit not(Trit a)
	{
		if (a == Trit.TRUE)
		{
			return Trit.FALSE;
		}
		else if (a == Trit.MAYBE)
		{
			return Trit.MAYBE;
		}
		else
		{
			return Trit.TRUE;
		}
	}
 
	public static Trit equals(Trit a, Trit b)
	{
		if (a == Trit.TRUE)
		{
			return b;
		}
		else if (a == Trit.MAYBE)
		{
			return Trit.MAYBE;
		}
		else
		{
			return not(b);
		}
	}
 
	public static void Main(string[] args)
	{
		foreach (Trit a in Enum.GetValues(typeof(Trit)))
		{
			Console.WriteLine("not " + a + ": " + not(a));
		}
		foreach (Trit a in Enum.GetValues(typeof(Trit)))
		{
			foreach (Trit b in Enum.GetValues(typeof(Trit)))
			{
				Console.WriteLine(a + " and " + b + ": " + and(a, b) + "\t " + a + " or " + b + ": " + or(a, b) + "\t " + a + " implies " + b + ": " + tIf(a, b) + "\t " + a + " = " + b + ": " + equals(a, b));
			}
		}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
namespace Knapsack
{
    class Program
    {
        struct item_t
        {
            public string name;
            public double value;
            public double weight;
            public double volume;
        }
 
        static item_t[] items = new item_t[] {
            new item_t { name = "panacea", value = 3000.0, weight = 0.3, volume = 0.025 },
            new item_t { name = "ichor", value = 1800.0, weight = 0.2, volume = 0.015 },
            new item_t { name = "gold", value = 2500.0, weight = 2.0, volume = 0.002 }
        };
 
        static int n = items.Length;
        static int[] count;
        static int[] best;
        static double best_value;
 
        static void knapsack(int i, double value, double weight, double volume)
        {
            int j, m1, m2, m;
            if (i == n)
            {
                if (value > best_value)
                {
                    best_value = value;
                    for (j = 0; j < n; j++)
                    {
                        best[j] = count[j];
                    }
                }
                return;
            }
            m1 = (int)(weight / items[i].weight);
            m2 = (int)(volume / items[i].volume);
            m = m1 < m2? m1 : m2;
            for (count[i] = m; count[i] >= 0; count[i]--)
            {
                knapsack(
                    i + 1,
                    value + count[i] * items[i].value,
                    weight - count[i] * items[i].weight,
                    volume - count[i] * items[i].volume
                );
            }
        }
 
        static void Main(string[] args)
        {
            count = new int[n];
            best = new int[n];
            best_value = 0;
            knapsack(0, 0.0, 25.0, 0.25);
            for (int i = 0; i < n; i++)
            {
                Console.WriteLine("{0} {1}", best[i], items[i].name);
            }
            Console.WriteLine("best value: {0}", best_value);
        }
    }
}

