using System;
using System.Collections.Generic;
using System.Linq;
 
namespace Partition
{
    class Program
    {
        static void Main(string[] args)
        {
            PrintPartitions(GeneratePartitions(new[] { 2, 0, 2 }));
            PrintPartitions(GeneratePartitions(new[] { 1, 1, 1 }));
            PrintPartitions(GeneratePartitions(new[] { 2, 3 }));
            PrintPartitions(GeneratePartitions(new[] { 0 }));
        }
 
        static void PrintPartitions(IEnumerable<IEnumerable<IEnumerable<int>>> result)
        {
            Console.WriteLine("Partitions:");
            foreach (var partition in result)
            {
                Console.WriteLine(string.Join(", ", partition.Select(x => string.Join(", ", x))));
            }
        }
 
        static IEnumerable<IEnumerable<IEnumerable<int>>> GeneratePartitions(int[] args)
        {
            // calculate the sum of all partitions
            var max = args.Sum();
 
            // generate combinations with the given lengths
            // for each partition
            var c = args.Select(arg => Enumerable.Range(1, max).Combinations(arg)).ToArray();
 
            // create a cartesian product of all individual combinations
            // filter/keep only where all the elements are there and exactly once
            return c.CartesianProduct().Where(x => x.SelectMany(y => y).Distinct().Count() == max);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Fibonacci
{
    class Program
    {
        static void Main(string[] args)
        {
            Func<int, int> fiblike = (start) =>
            {
                int addnum = start.Length;
                int[] memo = start.ToArray();
                Func<int, int> fibber = (n) =>
                {
                    try
                    {
                        return memo[n];
                    }
                    catch (IndexOutOfRangeException)
                    {
                        int ans = fibber(n - addnum) + fibber(n - addnum - 1);
                        memo[n] = ans;
                        return ans;
                    }
                };
                return fibber;
            };

            Func<int, int> fibo = fiblike(new int[] { 1, 1 });
            Func<int, int> lucas = fiblike(new int[] { 2, 1 });

            for (int n = 2; n < 11; n++)
            {
                Func<int, int> fibber = fiblike(Enumerable.Range(0, n).Select(i => (int)Math.Pow(2, i)).ToArray());
                Console.WriteLine("n={0,2}, {1,5}nacci -> {2}...", n, "fibo", string.Join(" ", Enumerable.Range(0, 15).Select(i => fibber(i))));
            }

            Console.ReadLine();
        }
    }
}

