using System;
using System.Collections.Generic;
using System.Linq;
 
/* returns the number itself, its smallest prime factor and all its prime factors */
public static Tuple<int, int, List<int>> PrimeFactorInfo(int n)
{
    if (n <= 1) throw new ArgumentException("Number must be more than one");
    if (IsPrime(n)) return new Tuple<int, int, List<int>>(n, n, new List<int> { n });
    var factors = new List<int>();
    var factor = 2;
    var nn = n;
    while (true)
    {
        if (nn % factor == 0)
        {
            factors.Add(factor);
            nn /= factor;
            if (nn == 1) return new Tuple<int, int, List<int>>(n, factors.Min(), factors);
            if (IsPrime(nn)) factor = nn;
        }
        else if (factor >= 3) factor += 2;
        else factor = 3;
    }
}
 
public static bool IsPrime(int n)
{
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    if (n % 3 == 0) return n == 3;
    var d = 5;
    while (d * d <= n)
    {
        if (n % d == 0) return false;
        d += 2;
        if (n % d == 0) return false;
        d += 4;
    }
    return true;
}
 
public static void Main(string[] args)
{
    var numbers = new List<int> { 12757923, 12878611, 12878893, 12757923, 15808973, 15780709, 197622519 };
    var info = numbers.AsParallel()
                     .Select(PrimeFactorInfo)
                     .ToList();
    var maxFactor = info.Max(x => x.Item2);
    var results = info.Where(x => x.Item2 == maxFactor);
    Console.WriteLine("The following number(s) have the largest minimal prime factor of " + maxFactor + ":");
    foreach (var result in results)
    {
        Console.WriteLine("  " + result.Item1 + " whose prime factors are " + string.Join(", ", result.Item3));
    }
}

