namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] names = { "gARY", "Earl", "Billy", "Felix", "Mary", "sHIRley" };
            foreach (string name in names)
            {
                print_verse(name);
            }
        }
 
        static void print_verse(string name)
        {
            string x, y;
            int b = 1, f = 1, m = 1, i = 1;
 
            /* ensure name is in title-case */
            x = name.ToLower();
            x = x.Substring(0, 1).ToUpper() + x.Substring(1);
 
            if (name.ToUpper().Contains("AEIOU"))
            {
                y = x.Substring(1);
            }
            else
            {
                y = x;
            }
 
            switch (x.Substring(0, 1))
            {
                case "B": b = 0; break;
                case "F": f = 0; break;
                case "M": m = 0; break;
                default: break;
            }
 
            Console.WriteLine(x + ", " + x + ", bo-" + ((b == 1)? "b" : "") + y);
            Console.WriteLine("Banana-fana fo-" + ((f == 1)? "f" : "") + y);
            Console.WriteLine("Fee-fi-mo-" + ((m == 1)? "m" : "") + y);
            Console.WriteLine(x + "!\n");
        }
    }
}

