class Kelvin
{
    public double degrees;
 
    public Kelvin(double degrees)
    {
        this.degrees = degrees;
    }
 
    public double toCelsius()
    {
        return this.degrees - 273.15;
    }
 
    public double toFahreneit()
    {
        return (this.degrees - 273.15) * 1.8 + 32.0;
    }
 
    public double toRankine()
    {
        return (this.degrees - 273.15) * 1.8 + 32.0 + 459.67;
    }
}
 
class Program
{
    static void Main(string[] args)
    {
        Console.Write("Enter the temperature in degrees Kelvin : ");
        double degrees = double.Parse(Console.ReadLine());
        Kelvin k = new Kelvin(degrees);
        string f = " {0,1:F2}";
        Console.WriteLine();
        Console.WriteLine("K  " + f, k.degrees);
        Console.WriteLine("C  " + f, k.toCelsius());
        Console.WriteLine("F  " + f, k.toFahreneit());
        Console.WriteLine("R  " + f, k.toRankine());
    }
}

