using System;
using System.Collections.Generic;
using System.Linq;
 
public class ABC
{
 
    public static void Main(string[] args)
    {
        List<string> blocks = new List<string>
        {
            "BO", "XK", "DQ", "CP", "NA",
            "GT", "RE", "TG", "QD", "FS",
            "JW", "HU", "VI", "AN", "OB",
            "ER", "FS", "LY", "PC", "ZM"
        };
 
        foreach (string word in new List<string> { "", "A", "BARK", "BOOK", "TREAT", "COMMON", "SQUAD", "CONFUSE" })
        {
            Console.WriteLine("{0}: {1}", word.Length == 0? "\"\"" : word, CanMakeWord(word, blocks));
        }
    }
 
    public static bool CanMakeWord(string word, List<string> blocks)
    {
        if (word.Length == 0)
            return true;
 
        char c = word[0];
        for (int i = 0; i < blocks.Count; i++)
        {
            string b = blocks[i];
            if (b[0]!= c && b[1]!= c)
                continue;
            Swap(blocks, 0, i);
            if (CanMakeWord(word.Substring(1), blocks.GetRange(1, blocks.Count - 1)))
                return true;
            Swap(blocks, 0, i);
        }
 
        return false;
    }
 
    public static void Swap<T>(IList<T> list, int index1, int index2)
    {
        T temp = list[index1];
        list[index1] = list[index2];
        list[index2] = temp;
    }
}

using System;
