namespace GoToCSharp
{
    class Program
    {
        static void Main(string[] args)
        {
            var myVar = 3.14;
            var myPointer = &myVar;
            Console.WriteLine("Address:", myPointer, &myVar);
            Console.WriteLine($"Address: {myPointer} {&myVar}");
 
            var addr64 = 0L;
            var addr32 = 0;
            var ptr = (IntPtr)myPointer;
            if (Marshal.SizeOf(ptr) <= Marshal.SizeOf(addr64))
            {
                addr64 = (long)ptr.ToInt64();
                Console.WriteLine($"Pointer stored in   int64: {addr64:X16}");
            }
            if (Marshal.SizeOf(ptr) <= Marshal.SizeOf(addr32))
            {
                // Only runs on architectures where a pointer is <= 32 bits
                addr32 = (int)ptr.ToInt32();
                Console.WriteLine($"Pointer stored in   int32: {addr32:X8}");
            }
            var addr = (int)ptr.ToInt32();
            Console.WriteLine($"Pointer stored in uintptr: {addr:X8}");
 
            Console.WriteLine($"value as float: {myVar}");
            var i = (int*)myPointer;
            Console.WriteLine($"value as int32: {*i:X8}");
        }
    }
}

