using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ProperDivisors
{
    class Program
    {
        static void Main(string[] args)
        {
            // Proper divisors
            Func<int, int[]> properDivisors = (n) =>
            {
                if (n < 2) return new int[0];
                else
                {
                    var rRoot = Math.Sqrt(n);
                    var intRoot = (int)Math.Floor(rRoot);

                    var lows = Enumerable.Range(1, intRoot).Where(x => (n % x) == 0);

                    return lows.Concat(lows.Skip(1).Select(x => n / x).Reverse().Skip((rRoot == intRoot)? 1 : 0)).ToArray();
                }
            };

            // [m..n]
            Func<int, int, int[]> range = (m, n) =>
            {
                var a = new int[n - m + 1];
                for (int i = n + 1; i-- > 0;) a[i - 1] = i;
                return a;
            };

            var tblOneToTen = new List<string[]> { new string[] { "Number", "Proper Divisors", "Count" } };
            tblOneToTen.AddRange(Enumerable.Range(1, 10).Select(x => new string[] { x.ToString(), string.Join(", ", properDivisors(x)), properDivisors(x).Length.ToString() }));

            var dctMostBelow20k = Enumerable.Range(1, 20000).Aggregate(new { n = 0, divisorCount = 0 }, (a, x) =>
            {
                var lng = properDivisors(x).Length;
                return lng > a.divisorCount? new { n = x, divisorCount = lng } : a;
            });

            // [[a]] -> bool -> s -> s
            Func<List<string[]>, bool, string, string> wikiTable = (lstRows, blnHeaderRow, strStyle) =>
            {
                var sb = new StringBuilder();
                sb.Append("{| class=\"wikitable\" ");
                if (!string.IsNullOrEmpty(strStyle)) sb.Append("style=\"" + strStyle + "\"");
                sb.Append(string.Join("", lstRows.Select((lstRow, iRow) =>
                {
                    var strDelim = (blnHeaderRow && iRow == 0)? "!" : "|";
                    return "\n|-\n" + strDelim + " " + string.Join(" " + strDelim + strDelim + " ", lstRow.Select(v => v == null? " " : v)) + " ";
                })));
                sb.Append("\n|}");
                return sb.ToString();
            };

            Console.WriteLine(wikiTable(tblOneToTen, true, null));
            Console.WriteLine("\nMost proper divisors below 20,000:\n\n  " + dctMostBelow20k.ToString());
            Console.ReadLine();
        }
    }
}

