using System;
using System.Collections.Generic;
using System.Linq;
 
namespace Kolakoski
{
    class Program
    {
        static void Main(string[] args)
        {
            var ias = new int[][] {
                new int[] { 1, 2 }, new int[] { 2, 1 },
                new int[] { 1, 3, 1, 2 }, new int[] { 1, 3, 2, 1 }
            };
            var lens = new int[] { 20, 20, 30, 30 };
            for (var i = 0; i < ias.Length; i++)
            {
                var ia = ias[i];
                var len = lens[i];
                var kol = ia.Kolakoski(len);
                Console.WriteLine($"First {len} members of the sequence generated by {ia.AsList()}:");
                Console.WriteLine(kol.AsList());
                var p = kol.PossibleKolakoski();
                Console.WriteLine($"Possible Kolakoski sequence? {p? "Yes" : "No"}\n");
            }
        }
    }
 
    public static class Extensions
    {
        public static string AsList(this int[] ia)
        {
            return ia.Aggregate("[", (s, i) => s + i + ", ");
        }
    }
 
    public static class Kolakoski
    {
        public static int[] Kolakoski(this int[] ia, int len)
        {
            var s = new int[len];
            var i = 0;
            var k = 0;
            while (true)
            {
                s[i] = ia.NextInCycle(k);
                if (s[k] > 1)
                {
                    for (var j = 0; j < s[k] - 1; j++)
                    {
                        if (++i == len) return s;
                        s[i] = s[i - 1];
                    }
                }
                if (++i == len) return s;
                k++;
            }
        }
 
        public static int NextInCycle(this int[] ia, int index)
        {
            return ia[index % ia.Length];
        }
 
        public static bool PossibleKolakoski(this int[] ia)
        {
            var len = ia.Length;
            var rle = new List<int>();
            var prev = ia[0];
            var count = 1;
            for (var i = 1; i < len; i++)
            {
                if (ia[i] == prev)
                {
                    count++;
                }
                else
                {
                    rle.Add(count);
                    count = 1;
                    prev = ia[i];
                }
            }
            // no point adding final 'count' to rle as we're not going to compare it anyway
            for (var i = 0; i < rle.Count; i++)
            {
                if (rle[i]!= ia[i]) return false;
            }
            return true;
        }
    }
}

