using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace ProjectEulerTasks
{
    class Task073
    {
        static void Main(string[] args)
        {
            Stopwatch sw = new Stopwatch();
            sw.Start();
 
            int[] lims = { 97, 986, 9875, 98764, 987653 };
            int[] count = new int[5];
            int[][] omitted = new int[5][];
            for (int i = 0; i < 5; i++)
            {
                omitted[i] = new int[10];
            }
 
            for (int i = 0; i < 5; i++)
            {
                int[] nDigits = new int[i + 2];
                int[] dDigits = new int[i + 2];
                int[] blank = new int[i + 2];
                for (int n = 12; n <= lims[i]; n++)
                {
                    Array.Copy(blank, nDigits, i + 2);
                    bool nOk = GetDigits(n, i + 2, nDigits);
                    if (!nOk)
                    {
                        continue;
                    }
                    for (int d = n + 1; d <= lims[i] + 1; d++)
                    {
                        Array.Copy(blank, dDigits, i + 2);
                        bool dOk = GetDigits(d, i + 2, dDigits);
                        if (!dOk)
                        {
                            continue;
                        }
                        for (int nix = 0; nix < i + 2; nix++)
                        {
                            int digit = nDigits[nix];
                            int dix = Array.IndexOf(dDigits, digit);
                            if (dix >= 0)
                            {
                                int rn = RemoveDigit(nDigits, i + 2, nix);
                                int rd = RemoveDigit(dDigits, i + 2, dix);
                                if ((double)n / d == (double)rn / rd)
                                {
                                    count[i]++;
                                    omitted[i][digit]++;
                                    if (count[i] <= 12)
                                    {
                                        Console.WriteLine("{0}/{1} = {2}/{3} by omitting {4}'s", n, d, rn, rd, digit);
                                    }
                                }
                            }
                        }
                    }
                }
            }
 
            for (int i = 2; i <= 6; i++)
            {
                Console.WriteLine("There are {0} {1}-digit fractions of which:", count[i - 2], i);
                for (int j = 1; j <= 9; j++)
                {
                    if (omitted[i - 2][j] == 0)
                    {
                        continue;
                    }
                    Console.WriteLine("{0,6} have {1}'s omitted", omitted[i - 2][j], j);
                }
                Console.WriteLine();
            }
 
            sw.Stop();
            Console.WriteLine("Elapsed={0}", sw.Elapsed.ToString());
        }
 
        private static int RemoveDigit(int[] digits, int le, int idx)
        {
            int sum = 0;
            int pow = pows[le - 2];
            for (int i = 0; i < le; i++)
            {
                if (i == idx)
                {
                    continue;
                }
                sum += digits[i] * pow;
                pow /= 10;
            }
            return sum;
        }
 
        private static int[] pows = { 1, 10, 100, 1000, 10000 };
 
        private static bool GetDigits(int n, int le, int[] digits)
        {
            for (; n > 0; n /= 10)
            {
                int r = n % 10;
                if (r == 0 || Array.IndexOf(digits, r) >= 0)
                {
                    return false;
                }
                le--;
                digits[le] = r;
            }
            return true;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace CrowdError
{
	class Program
	{
		static float mean(float[] arr, int size)
		{
			int i = 0;
			float sum = 0;
 
			while (i!= size)
				sum += arr[i++];
 
			return sum / size;
		}
 
		static float variance(float reference, float[] arr, int size)
		{
			int i = 0;
			float[] newArr = new float[size];
 
			for (; i < size; i++)
				newArr[i] = (reference - arr[i]) * (reference - arr[i]);
 
			return mean(newArr, size);
		}
 
		static float[] extractData(string str, ref int len)
		{
			float[] arr;
			int i = 0, count = 1;
			string[] token;
 
			while (str[i]!= 00)
			{
				if (str[i++] == ',')
					count++;
			}
 
			arr = new float[count];
			len = count;
 
			token = str.Split(',');
 
			i = 0;
 
			while (i < len)
			{
				arr[i++] = float.Parse(token[i]);
			}
 
			return arr;
		}
 
		static void Main(string[] args)
		{
			float[] arr;
			float reference, meanVal;
			int len;
			if (args.Length!= 2)
				Console.WriteLine("Usage : {0} <reference value> <observations separated by commas>", args[0]);
			else
			{
				arr = extractData(args[1], ref len);
 
				reference = float.Parse(args[0]);
 
				meanVal = mean(arr, len);
 
				Console.WriteLine("Average Error : {0}", variance(reference, arr, len));
				Console.WriteLine("Crowd Error : {0}", (reference - meanVal) * (reference - meanVal));
				Console.WriteLine("Diversity : {0}", variance(meanVal, arr, len));
			}
		}
	}
}

