public static string StripCharacters(string original, string toStrip)
{
    var result = new StringBuilder();
    foreach (var c in original)
    {
        if (!toStrip.Contains(c))
        {
            result.Append(c);
        }
    }
    return result.ToString();
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Deal
{
    class Program
    {
        const string sSuits = "CDHS";
        const string sNums = "A23456789TJQK";
        const int rMax32 = int.MaxValue;
        static int seed = 1;
        static Random rnd = new Random();
        static int Rnd()
        {
            seed = (seed * 214013 + 2531011) & rMax32;
            return seed >> 16;
        }
        static int[] Deal(int s)
        {
            seed = s;
            int[] t = new int[52];
            for (int i = 0; i < 52; i++)
            {
                t[i] = 51 - i;
            }
            for (int i = 0; i < 51; i++)
            {
                int j = 51 - Rnd() % (52 - i);
                int temp = t[i];
                t[i] = t[j];
                t[j] = temp;
            }
            return t;
        }
        static void Show(int[] cs)
        {
            for (int i = 0; i < cs.Length; i++)
            {
                Console.Write(" {0}{1}", sNums[cs[i] / 4], sSuits[cs[i] % 4]);
                if ((i + 1) % 8 == 0 || i + 1 == cs.Length)
                {
                    Console.WriteLine();
                }
            }
        }
        static void Main(string[] args)
        {
            int game;
            switch (args.Length)
            {
                case 0:
                    game = 1 + rnd.Next(32000);
                    break;
                case 1:
                    if (int.TryParse(args[0], out game) && game >= 1 && game <= 32000)
                    {
                        break;
                    }
                    goto default;
                default:
                    Console.WriteLine("usage: deal [game]");
                    Console.WriteLine("       where game is a number in the range 1 to 32000");
                    return;
            }
            Console.WriteLine("\nGame #{0}", game);
            Show(Deal(game));
        }
    }
}

