using System;
using System.IO;
using System.Linq;
 
public class Program
{
    public static void RemoveLines(string fileName, int startLine, int numLines)
    {
        if (string.IsNullOrEmpty(fileName) || startLine < 1 || numLines < 1)
        {
            throw new ArgumentException();
        }
        var f = new FileInfo(fileName);
        if (!f.Exists)
        {
            Console.WriteLine($"{fileName} does not exist");
            return;
        }
        var lines = File.ReadAllLines(fileName);
        var size = lines.Length;
        if (startLine > size)
        {
            Console.WriteLine("The starting line is beyond the length of the file");
            return;
        }
        var n = numLines;
        if (startLine + numLines - 1 > size)
        {
            Console.WriteLine("Attempting to remove some lines which are beyond the end of the file");
            n = size - startLine + 1;
        }
        lines = lines.Take(startLine - 1).Concat(lines.Skip(startLine + n - 1)).ToArray();
        File.WriteAllLines(fileName, lines);
    }
    public static void PrintFile(string fileName, string message)
    {
        if (string.IsNullOrEmpty(fileName))
        {
            throw new ArgumentException();
        }
        var f = new FileInfo(fileName);
        if (!f.Exists)
        {
            Console.WriteLine($"{fileName} does not exist");
            return;
        }
        Console.WriteLine($"\nContents of {fileName} {message}:\n");
        File.ReadAllLines(fileName).ToList().ForEach(Console.WriteLine);
    }
    public static void Main(string[] args)
    {
        PrintFile("input.txt", "before removal");
        RemoveLines("input.txt", 2, 3);
        PrintFile("input.txt", "after removal of 3 lines starting from the second");
    }
}

