using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace Wheels
{
    class Wheel
    {
        private List<char> values;
        private int index;
 
        public Wheel()
        {
            index = 0;
        }
 
        public Wheel(List<char> data)
        {
            values = data;
            index = 0;
            if (values.Count < 1)
            {
                throw new Exception("Not enough elements");
            }
        }
 
        public char front()
        {
            return values[index];
        }
 
        public void popFront()
        {
            index = (index + 1) % values.Count;
        }
    }
 
    class NamedWheel
    {
        private Dictionary<char, Wheel> wheels;
 
        public NamedWheel()
        {
            wheels = new Dictionary<char, Wheel>();
        }
 
        public void put(char c, Wheel w)
        {
            wheels[c] = w;
        }
 
        public char front(char c)
        {
            char v = wheels[c].front();
            while ('A' <= v && v <= 'Z')
            {
                v = wheels[v].front();
            }
            return v;
        }
 
        public void popFront(char c)
        {
            char v = wheels[c].front();
            wheels[c].popFront();
 
            while ('A' <= v && v <= 'Z')
            {
                char d = wheels[v].front();
                wheels[v].popFront();
                v = d;
            }
        }
    }
 
    class Program
    {
        static void group1()
        {
            Wheel w = new Wheel(new List<char> { '1', '2', '3' });
            for (int i = 0; i < 20; i++)
            {
                Console.Write(" " + w.front());
                w.popFront();
            }
            Console.WriteLine();
        }
 
        static void group2()
        {
            Wheel a = new Wheel(new List<char> { '1', 'B', '2' });
            Wheel b = new Wheel(new List<char> { '3', '4' });
 
            NamedWheel n = new NamedWheel();
            n.put('A', a);
            n.put('B', b);
 
            for (int i = 0; i < 20; i++)
            {
                Console.Write(" " + n.front('A'));
                n.popFront('A');
            }
            Console.WriteLine();
        }
 
        static void group3()
        {
            Wheel a = new Wheel(new List<char> { '1', 'D', 'D' });
            Wheel d = new Wheel(new List<char> { '6', '7', '8' });
 
            NamedWheel n = new NamedWheel();
            n.put('A', a);
            n.put('D', d);
 
            for (int i = 0; i < 20; i++)
            {
                Console.Write(" " + n.front('A'));
                n.popFront('A');
            }
            Console.WriteLine();
        }
 
        static void group4()
        {
            Wheel a = new Wheel(new List<char> { '1', 'B', 'C' });
            Wheel b = new Wheel(new List<char> { '3', '4' });
            Wheel c = new Wheel(new List<char> { '5', 'B' });
 
