using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Numerics;
 
namespace RosettaCode
{
    class Program
    {
        static void Main(string[] args)
        {
            for (int i = 0; i < 10; i++)
            {
                faulhaber(i);
            }
        }
 
        static BigInteger binomial(int n, int k)
        {
            if (n < 0 || k < 0 || n < k)
            {
                return -1;
            }
            if (n == 0 || k == 0)
            {
                return 1;
            }
 
            BigInteger num = 1;
            for (int i = k + 1; i <= n; i++)
            {
                num = num * i;
            }
 
            BigInteger denom = 1;
            for (int i = 2; i <= n - k; i++)
            {
                denom = denom * i;
            }
 
            return num / denom;
        }
 
        static BigInteger bernoulli(int n)
        {
            if (n < 0)
            {
                throw new Exception("n cannot be less than zero");
            }
 
            BigInteger[] a = new BigInteger[16];
            for (int m = 0; m <= n; m++)
            {
                a[m] = 1 / (m + 1);
                for (int j = m; j >= 1; j--)
                {
                    a[j - 1] = (a[j - 1] - a[j]) * j;
                }
            }
 
            if (n!= 1)
            {
                return a[0];
            }
            return -a[0];
        }
 
        static void faulhaber(int p)
        {
            Console.Write("{0} : ", p);
            BigInteger q = 1 / (p + 1);
            int sign = -1;
            for (int j = 0; j <= p; j++)
            {
                sign = -1 * sign;
                BigInteger coeff = q * sign * binomial(p + 1, j) * bernoulli(j);
                if (coeff == 0)
                {
                    continue;
                }
                if (j == 0)
                {
                    if (coeff!= 1)
                    {
                        if (coeff == -1)
                        {
                            Console.Write("-");
                        }
                        else
                        {
                            Console.Write(coeff);
                        }
                    }
                }
                else
                {
                    if (coeff == 1)
                    {
                        Console.Write(" + ");
                    }
                    else if (coeff == -1)
                    {
                        Console.Write(" - ");
                    }
                    else if (0 < coeff)
                    {
                        Console.Write(" + ");
                        Console.Write(coeff);
                    }
                    else
                    {
                        Console.Write(" - ");
                        Console.Write(-coeff);
                    }
                }
                int pwr = p + 1 - j;
                if (pwr > 1)
                {
                    Console.Write("n^{0}", pwr);
                }
                else
                {
                    Console.Write("n");
                }
            }
            Console.WriteLine();
        }
    }
}

