using System;
 
class Program
{
    static int countDivisors(int n)
    {
        int i, count;
        if (n < 2) return 1;
        count = 2; // 1 and n
        for (i = 2; i <= n/2; ++i)
        {
            if (n%i == 0) ++count;
        }
        return count;
    }
 
    static void Main()
    {
        int n, d, maxDiv = 0, count = 0;
        Console.WriteLine("The first 20 anti-primes are:");
        for (n = 1; count < 20; ++n)
        {
            d = countDivisors(n);
            if (d > maxDiv)
            {
                Console.Write("{0} ", n);
                maxDiv = d;
                count++;
            }
        }
        Console.WriteLine();
    }
}

