namespace Entropy
{
    class Program
    {
        static void Main(string[] args)
        {
            var arg = args.FirstOrDefault()?? throw new ArgumentException("Need a string.");
            Console.WriteLine($"Entropy of {arg} is {Entropy(arg)}.");
        }
 
        static double Entropy(string s)
        {
            var histogram = new long[256];
 
            foreach (var b in s)
            {
                histogram[b]++;
            }
 
            return histogram
               .Where(h => h!= 0)
               .Select(h => (double)h / s.Length)
               .Select(ratio => -ratio * Math.Log(ratio, 2))
               .Sum();
        }
    }
}

