using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
 
namespace IBAN
{
    class Program
    {
        static void Main(string[] args)
        {
            var lengthByCountryCode = new Dictionary<string, int>
            {
                {"AL", 28}, {"AD", 24}, {"AT", 20}, {"AZ", 28}, {"BE", 16}, {"BH", 22},
                {"BA", 20}, {"BR", 29}, {"BG", 22}, {"CR", 21}, {"HR", 21}, {"CY", 28},
                {"CZ", 24}, {"DK", 18}, {"DO", 28}, {"EE", 20}, {"FO", 18}, {"FI", 18},
                {"FR", 27}, {"GE", 22}, {"DE", 22}, {"GI", 23}, {"GR", 27}, {"GL", 18},
                {"GT", 28}, {"HU", 28}, {"IS", 26}, {"IE", 22}, {"IL", 23}, {"IT", 27},
                {"KZ", 20}, {"KW", 30}, {"LV", 21}, {"LB", 28}, {"LI", 21}, {"LT", 20},
                {"LU", 20}, {"MK", 19}, {"MT", 31}, {"MR", 27}, {"MU", 30}, {"MC", 27},
                {"MD", 24}, {"ME", 22}, {"NL", 18}, {"NO", 15}, {"PK", 24}, {"PS", 29},
                {"PL", 28}, {"PT", 25}, {"RO", 24}, {"SM", 27}, {"SA", 24}, {"RS", 22},
                {"SK", 24}, {"SI", 19}, {"ES", 24}, {"SE", 24}, {"CH", 21}, {"TN", 24},
                {"TR", 26}, {"AE", 23}, {"GB", 22}, {"VG", 24},
            };
 
            Func<string, bool> isValidIBAN = iban =>
            {
                if (iban.Length < 4)
                {
                    return false;
                }
                iban = Regex.Replace(iban, @"\s+", "");
                iban = iban.ToUpper();
 
                if (lengthByCountryCode[iban.Substring(0, 2)]!= iban.Length)
                {
                    return false;
                }
                iban = iban.Substring(4) + iban.Substring(0, 4);
 
                var result = 0;
                foreach (var ch in iban)
                {
                    var n = 0;
                    if ('0' <= ch && ch <= '9')
                    {
                        n = ch - '0';
                    }
                    else if ('A' <= ch && ch <= 'Z')
                    {
                        n = 10 + ch - 'A';
                    }
                    else
                    {
                        return false;
                    }
 
                    if (n < 10)
                    {
                        result = (10 * result + n) % 97;
                    }
                    else
                    {
                        result = (100 * result + n) % 97;
                    }
                }
                return result == 1;
            };
 
            var tests = new[]
            {
                new {iban = "GB82 WEST 1234 5698 7654 32", valid = true},
                new {iban = "GB82 TEST 1234 5698 7654 32", valid = false},
            };
            foreach (var test in tests)
            {
                if (isValidIBAN(test.iban) == test.valid)
                {
                    return;
                }
                Console.WriteLine("Expected {0} to be {1}", test.iban, test.valid);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace NegativeBase
{
    class Program
    {
        static string digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
 
        static string reverse(string s)
        {
            char[] charArray = s.ToCharArray();
            Array.Reverse(charArray);
            return new string(charArray);
        }
 
        static string encodeNegBase(long n, long b)
        {
            if (b < -62 || b > -1)
            {
                throw new Exception("base must be between -62 and -1 inclusive");
            }
            if (n == 0)
            {
                return "0";
            }
            string outStr = "";
            while (n!= 0)
            {
                long rem = n % b;
                n /= b;
                if (rem < 0)
                {
                    n++;
                    rem -= b;
                }
                outStr += digits[(int)rem];
            }
            outStr = reverse(outStr);
            return outStr;
        }
 
        static long decodeNegBase(string ns, long b)
        {
            if (b < -62 || b > -1)
            {
                throw new Exception("base must be between -62 and -1 inclusive");
            }
            if (ns == "0")
            {
                return 0;
            }
            long total = 0;
            long bb = 1;
            ns = reverse(ns);
            for (int i = 0; i < ns.Length; i++)
            {
                total += digits.IndexOf(ns[i]) * bb;
                bb *= b;
            }
            return total;
        }
 
        static void Main(string[] args)
        {
            long[] numbers = { 10, 146, 15, -942, 1488588316238 };
            long[] bases = { -2, -3, -10, -62, -62 };
            for (int i = 0; i < numbers.Length; i++)
            {
                long n = numbers[i];
                long b = bases[i];
                string ns = encodeNegBase(n, b);
                Console.WriteLine("{0,13} encoded in base {1,-3} = {2}", n, b, ns);
                n = decodeNegBase(ns, b);
                Console.WriteLine("{0,13} decoded in base {1,-3} = {2}", ns, b, n);
                Console.WriteLine();
            }
            Console.ReadLine();
