using System;
using System.Collections.Generic;
using System.Linq;
 
namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine(string.Join(",", ex(new int[] { -7, 1, 5, 2, -4, 3, 0 })));
 
            // sequence of 1,000,000 random numbers, with values
            // chosen so that it will be likely to have a couple
            // of equalibrium indexes.
            var rand = new Random();
            var verylong = new int[1000000];
            for (int i = 0; i < verylong.Length; i++)
            {
                verylong[i] = rand.Next(1001) - 500;
            }
            Console.WriteLine(string.Join(",", ex(verylong)));
        }
 
        static List<int> ex(int[] s)
        {
            var eq = new List<int>();
            long r = 0;
            foreach (var el in s)
            {
                r += el;
            }
            long l = 0;
            for (int i = 0; i < s.Length; i++)
            {
                r -= s[i];
                if (l == r)
                {
                    eq.Add(i);
                }
                l += s[i];
            }
            return eq;
        }
    }
}

