public class P
{
    public int x;
    public int y;
    public int sum;
    public int prod;
 
    public P(int x, int y, int sum, int prod)
    {
        this.x = x;
        this.y = y;
        this.sum = sum;
        this.prod = prod;
    }
}
 
public class Program
{
    public static void Main(string[] args)
    {
        var candidates = new List<P>();
        for (var x = 2; x <= 49; x++)
        {
            for (var y = x + 1; y <= 100 - x; y++)
            {
                candidates.Add(new P(x, y, x + y, x * y));
            }
        }
 
        var sums = candidates.GroupBy(p => p.sum);
        var prods = candidates.GroupBy(p => p.prod);
 
        var fact1 = candidates.Where(p => sums[p.sum].All(p2 => prods[p.prod].Count() > 1));
        var fact2 = fact1.Where(p => prods[p.prod].Intersect(fact1).Count() == 1);
        var fact3 = fact2.Where(p => sums[p.sum].Intersect(fact2).Count() == 1);
        Console.WriteLine("The only solution is : ");
        foreach (var p in fact3)
        {
            Console.WriteLine($"x = {p.x}, y = {p.y}");
        }
    }
}

