namespace AGM
{
    class Program
    {
        static void agm(ref BigInteger in1, ref BigInteger in2, ref BigInteger out1, ref BigInteger out2)
        {
            out1 = (in1 + in2) / 2;
            out2 = BigInteger.Sqrt(in1 * in2);
        }
 
        static void Main(string[] args)
        {
            BigInteger x0 = 1;
            BigInteger y0 = 1;
            BigInteger resA = 0;
            BigInteger resB = 0;
            BigInteger Z = 1;
            BigInteger var = 0;
 
            int n = 1;
            for (int i = 0; i < 8; i++)
            {
                agm(ref x0, ref y0, ref resA, ref resB);
                var = (resA - x0) * (resA - x0);
                var *= n;
                Z -= var;
                n += n;
                agm(ref resA, ref resB, ref x0, ref y0);
                var = (x0 - resA) * (x0 - resA);
                var *= n;
                Z -= var;
                n += n;
            }
            x0 *= x0;
            x0 /= Z;
            Console.WriteLine(x0);
            Console.ReadKey();
        }
    }
}

using System;
using System.Drawing;
 
namespace Raster
{
    public partial class Bitmap
    {
        // Circle plots a circle with center x, y and radius r.
        // Limiting behavior:
        // r < 0 plots no pixels.
        // r = 0 plots a single pixel at x, y.
        // r = 1 plots four pixels in a diamond shape around the center pixel at x, y.
        public void Circle(int x, int y, int r, Pixel p)
        {
            if (r < 0)
            {
                return;
            }
            // Bresenham algorithm
            int x1 = -r;
            int y1 = 0;
            int err = 2 - 2 * r;
            while (true)
            {
                SetPx(x - x1, y + y1, p);
                SetPx(x - y1, y - x1, p);
                SetPx(x + x1, y - y1, p);
                SetPx(x + y1, y + x1, p);
                int r1 = err;
                if (r1 > x1)
                {
                    x1++;
                    err += x1 * 2 + 1;
                }
                if (r1 <= y1)
                {
                    y1++;
                    err += y1 * 2 + 1;
                }
                if (x1 >= 0)
                {
                    break;
                }
            }
        }
 
        public void CircleRgb(int x, int y, int r, Rgb c)
        {
            Circle(x, y, r, c.Pixel());
        }
    }
}

using System;

public class StdDev
{
    int n = 0;
    double sum = 0;
    double sum2 = 0;

    public double sd(double x)
    {
        n++;
        sum += x;
        sum2 += x * x;

        return Math.Sqrt(sum2 / n - sum * sum / n / n);
    }

    public static void Main(string[] args)
    {
        double[] testData = { 2, 4, 4, 4, 5, 5, 7, 9 };
        StdDev sd = new StdDev();

        foreach (double x in testData)
        {
            Console.WriteLine(sd.sd(x));
        }
    }
}

