namespace CocktailSort
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] arr = new int[77];
            Random rand = new Random();
            for (int i = 0; i < 77; i++)
            {
                arr[i] = rand.Next(1, 77);
            }
            Console.WriteLine("Original: ");
            Console.WriteLine("==========");
            for (int i = 0; i < 77; i++)
            {
                Console.Write(arr[i] + ", ");
            }
            Console.WriteLine();
            Console.WriteLine();
            Console.WriteLine("Sorted: ");
            Console.WriteLine("========");
            CocktailSort(arr);
            for (int i = 0; i < 77; i++)
            {
                Console.Write(arr[i] + ", ");
            }
            Console.WriteLine();
            Console.WriteLine();
            Console.WriteLine();
            Console.WriteLine();
            Console.ReadKey();
        }
        static void CocktailSort(int[] arr)
        {
            bool notSorted = true;
            while (notSorted)
            {
                notSorted = false;
                for (int a = 0; a < arr.Length - 1; a++)
                {
                    if (arr[a] > arr[a + 1])
                    {
                        Swap(ref arr[a], ref arr[a + 1]);
                        notSorted = true;
                    }
                }
                if (!notSorted) break;
                notSorted = false;
                for (int a = arr.Length - 1; a > 0; a--)
                {
                    if (arr[a - 1] > arr[a])
                    {
                        Swap(ref arr[a], ref arr[a - 1]);
                        notSorted = true;
                    }
                }
            }
        }
        static void Swap(ref int a, ref int b)
        {
            int t = a;
            a = b;
            b = t;
        }
    }
}

