using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Drawing;
using System.Drawing.Imaging;
using System.Threading.Tasks;
 
namespace BrownianTree
{
    class Program
    {
        const int NUM_PARTICLES = 1000;
        const int SIZE = 800;
        static void Main(string[] args)
        {
            int[,] world = new int[SIZE, SIZE];
            Random rand = new Random();
            // set the seed
            world[rand.Next(SIZE), rand.Next(SIZE)] = 1;
 
            for (int i = 0; i < NUM_PARTICLES; i++)
            {
                // set particle's position
                int px = rand.Next(SIZE);
                int py = rand.Next(SIZE);
 
                while (true)
                {
                    // randomly choose a direction
                    int dx = rand.Next(3) - 1;
                    int dy = rand.Next(3) - 1;
 
                    if (dx + px < 0 || dx + px >= SIZE || dy + py < 0 || dy + py >= SIZE)
                    {
                        // plop the particle into some other random location
                        px = rand.Next(SIZE);
                        py = rand.Next(SIZE);
                    }
                    else if (world[py + dy, px + dx]!= 0)
                    {
                        // bumped into something
                        world[py, px] = 1;
                        break;
                    }
                    else
                    {
                        py += dy;
                        px += dx;
                    }
                }
            }
 
            Bitmap img = new Bitmap(SIZE, SIZE);
            Graphics g = Graphics.FromImage(img);
            g.Clear(Color.Black);
 
            for (int y = 0; y < SIZE; y++)
            {
                for (int x = 0; x < SIZE; x++)
                {
                    if (world[y, x]!= 0)
                    {
                        img.SetPixel(x, y, Color.White);
                    }
                }
            }
 
            img.Save("brownian_tree.bmp", ImageFormat.Bmp);
        }
    }
}

