task_description:
Implement some operations on variable-length quantities, at least including conversions from a normal number in the language to the binary representation of the variable-length quantity for that number, and vice versa. Any variants are acceptable.



Task

With above operations,

convert these two numbers 0x200000 (2097152 in decimal) and 0x1fffff (2097151 in decimal) into sequences of octets (an eight-bit byte); 
display these sequences of octets;
convert these sequences of octets back to numbers, and check that they are equal to original numbers.

code:
// version 1.0.6
 
using System;
 
public class Program
{
    public static byte[] toOctets(int n)
    {
        var s = Convert.ToString(n, 2);
        var r = s.Length % 7;
        var z = s.Length / 7;
        if (r > 0)
        {
            z++;
            s = s.PadLeft(z * 7, '0');
        }
        s = string.Join("", Enumerable.Range(0, z).Select(i => "1" + s.Substring(i * 7, 7)));
        s = s.Substring(0, s.Length - 8) + "0" + s.Substring(s.Length - 7);
        return Enumerable.Range(0, z).Select(i => Convert.ToByte(s.Substring(i * 8, 8), 2)).ToArray();
    }
 
    public static int fromOctets(byte[] ba)
    {
        var s = string.Join("", ba.Select(b => Convert.ToString(b, 2).PadLeft(7, '0').Substring(0, 7)));
        return Convert.ToInt32(s, 2);
    }
 
    public static void Main(string[] args)
    {
        var tests = new int[] { 0x7f, 0x3fff, 0x200000, 0x1fffff };
        foreach (var test in tests)
        {
            var ba = toOctets(test);
            Console.Write("{0,8:x} -> ", test);
            var s = string.Join(" ", ba.Select(b => string.Format("0x{0:x2}", b)));
            Console.WriteLine("{0,20} <- {1,8:x}", s, fromOctets(ba));
        }
    }
}

using System;
using System.Diagnostics;
 
namespace ConsoleApplication1
{
    class Program
    {
        static int ipow(int base, int exp)
        {
            int pow = base;
            int v = 1;
            if (exp < 0)
            {
                Debug.Assert(base!= 0);  /* divide by zero */
                return (base * base!= 1)? 0 : (exp & 1)? base : 1;
            }
 
            while (exp > 0)
            {
                if (exp & 1) v *= pow;
                pow *= pow;
                exp >>= 1;
            }
            return v;
        }
 
        static double dpow(double base, int exp)
        {
            double v = 1.0;
            double pow = (exp < 0)? 1.0 / base : base;
            if (exp < 0) exp = -exp;
 
            while (exp > 0)
            {
                if (exp & 1) v *= pow;
                pow *= pow;
                exp >>= 1;
            }
            return v;
        }
 
        static void Main(string[] args)
        {
            Console.WriteLine("2^6 = {0}", ipow(2, 6));
            Console.WriteLine("2^-6 = {0}", ipow(2, -6));
            Console.WriteLine("2.71^6 = {0}", dpow(2.71, 6));
            Console.WriteLine("2.71^-6 = {0}", dpow(2.71, -6));
        }
    }
}

public static List<Point> Clip(List<Point> subjectPolygon, List<Point> clipPolygon)
{
    List<Point> outputList = new List<Point>();
    Point cp1 = clipPolygon[clipPolygon.Count - 1];
    foreach (Point clipVertex in clipPolygon)
    {
        Point cp2 = clipVertex;
        List<Point> inputList = outputList;
        outputList = new List<Point>();
        Point s = inputList[inputList.Count - 1];
        foreach (Point subjectVertex in inputList)
        {
            Point e = subjectVertex;
            if (Inside(e))
            {
                if (!Inside(s))
                {
                    outputList.Add(ComputeIntersection());
                }
                outputList.Add(e);
            }
            else if (Inside(s))
            {
                outputList.Add(ComputeIntersection());
            }
            s = e;
        }
        cp1 = cp2;
    }
    return outputList;
}
 
private static bool Inside(Point p)
{
    return (cp2.X - cp1.X) * (p.Y - cp1.Y) > (cp2.Y - cp1.Y) * (p.X - cp1.X);
}
 
private static Point ComputeIntersection()
{
    double dcX = cp1.X - cp2.X;
    double dcY = cp1.Y - cp2.Y;
    double dpX = s.X - e.X;
    double dpY = s.Y - e.Y;
    double n1 = cp1.X * cp2.Y - cp1.Y * cp2.X;
    double n2 = s.X * e.Y - s.Y * e.X;
    double n3 = 1.0 / (dcX * dpY - dcY * dpX);
    return new Point((n1 * dpX - n2 * dcX) * n3, (n1 * dpY - n2 * dcY) * n3);
}

