namespace Fusc
{
    class Program
    {
        static void Main(string[] args)
        {
            var fusc = Fusc();
            var longestFusc = LongestFusc();
 
            Console.WriteLine("First 61:");
            for (int i = 0; i < 61; i++)
            {
                Console.Write(fusc.Next() + " ");
            }
 
            Console.WriteLine("\n\nLength records:");
            for (int i = 0; i < 6; i++)
            {
                Console.WriteLine($"fusc({longestFusc.Next().Item1}) = {longestFusc.Next().Item2}");
            }
 
            Console.ReadLine();
        }
 
        static IEnumerable<int> Fusc()
        {
            var q = new Queue<int>();
            q.Enqueue(1);
            yield return 0;
            yield return 1;
 
            while (true)
            {
                var x = q.Dequeue();
                q.Enqueue(x);
                yield return x;
 
                x += q.Peek();
                q.Enqueue(x);
                yield return x;
            }
        }
 
        static IEnumerable<(int, int)> LongestFusc()
        {
            var sofar = 0;
            var i = 0;
            foreach (var f in Fusc())
            {
                if (f >= sofar)
                {
                    yield return (i, f);
                    sofar = 10 * sofar == 0? 10 : sofar;
                }
                i++;
            }
        }
    }
}

