public class Node
{
    public int val;
    public Node back;
 
    public Node(int val)
    {
        this.val = val;
    }
}
 
public class Program
{
    public static void Main()
    {
        Console.WriteLine(string.Join(", ", lis(new int[] { 3, 2, 6, 4, 5, 1 })));
        Console.WriteLine(string.Join(", ", lis(new int[] { 0, 8, 4, 12, 2, 10, 6, 14, 1, 9, 5, 13, 3, 11, 7, 15 })));
    }
 
    public static List<int> lis(int[] n)
    {
        List<Node> pileTops = new List<Node>();
        // sort into piles
        for (int i = 0; i < n.Length; i++)
        {
            // binary search
            int low = 0, high = pileTops.Count - 1;
            while (low <= high)
            {
                int mid = low + (high - low) / 2;
                if (pileTops[mid].val >= n[i])
                {
                    high = mid - 1;
                }
                else
                {
                    low = mid + 1;
                }
            }
            int index = low;
            Node node = new Node(n[i]);
            if (index > 0)
            {
                node.back = pileTops[index - 1];
            }
            pileTops[index] = node;
        }
 
        List<int> result = new List<int>();
        Node node = pileTops[pileTops.Count - 1];
        while (node!= null)
        {
            result.Insert(0, node.val);
            node = node.back;
        }
        return result;
    }
}

