namespace CommonPath
{
    class Program
    {
        static void Main(string[] args)
        {
            var cdpInput = new List<string>
            {
                "/home/user1/tmp/coverage/test",
                "/home/user1/tmp/covert/operator",
                "/home/user1/tmp/coven/members"
            };
            Console.WriteLine($"Common path is: {CommonPath(cdpInput)}");
        }
 
        static string CommonPath(List<string> input, string sep = "/")
        {
            var splitStrings = input.Select(i => i.Split(sep.ToCharArray()));
            var rotate = splitStrings.Select(i => i.Select((e, j) => splitStrings.Select(k => k.ElementAt(j)).ToArray()).ToArray());
            var allElementsEqual = rotate.Select(i => i.Select(j => j.All(k => k == j[0])).ToArray());
            var commonPath = allElementsEqual.Select(i => i.Select((j, k) => j? splitStrings.Select(l => l.ElementAt(k)).ToArray() : new string[] { }).ToArray());
            return string.Join(sep, commonPath.Select(i => i.Select(j => j.FirstOrDefault()).ToArray()));
        }
    }
}

