using System;
 
namespace MeanTime
{
    class Program
    {
        static void Main(string[] args)
        {
            var sum = 0;
            var count = 0;
            foreach (var arg in args)
            {
                var seconds = time_to_seconds(arg);
                sum += seconds;
                count++;
            }
            var seconds = Math.Floor(sum / count);
            Console.WriteLine("Mean time is {0}", seconds_to_time(seconds));
        }
 
        static int time_to_seconds(string hms)
        {
            var parts = hms.Split(':');
            var h = int.Parse(parts[0]);
            var m = int.Parse(parts[1]);
            var s = int.Parse(parts[2]);
            if (h < 12)
            {
                h += 24;
            }
            var seconds = int.Parse(parts[0]) * 60 * 60 + int.Parse(parts[1]) * 60 + int.Parse(parts[2]);
            return seconds;
        }
 
        static string seconds_to_time(double s)
        {
            var h = Math.Floor(s / (60 * 60));
            if (h < 10)
            {
                h = "0" + h;
            }
            s = s % (60 * 60);
 
            var m = Math.Floor(s / 60);
            if (m < 10)
            {
                m = "0" + m;
            }
            s = s % 60;
            if (s < 10)
            {
                s = "0" + s;
            }
            return h + ":" + m + ":" + s;
        }
    }
}

