public static void Shell(int[] seq)
{
    int inc = seq.Length / 2;
    while (inc > 0)
    {
        for (int i = inc; i < seq.Length; i++)
        {
            int el = seq[i];
            while (i >= inc && seq[i - inc] > el)
            {
                seq[i] = seq[i - inc];
                i -= inc;
            }
            seq[i] = el;
        }
        inc = inc == 2? 1 : inc * 5 / 11;
    }
}

