namespace RK4
{
    class Program
    {
        static void Main(string[] args)
        {
            double y = 1.0;
            double x = 0.0;
            double step = 0.1;
            int steps = 0;
            int maxSteps = 101;
            int sampleEveryN = 10;
 
            while (steps < maxSteps)
            {
                if (steps % sampleEveryN == 0)
                {
                    Console.WriteLine("y(" + x + ") =  \t" + y + "\t ± " + (actual(x) - y).ToString("E"));
                }
 
                y = rk4(y, x, step, f);
 
                // using integer math for the step addition
                // to prevent floating point errors as 0.2 + 0.1 != 0.3
                x = ((x * 10) + (step * 10)) / 10;
                steps += 1;
            }
 
            Console.ReadKey();
        }
 
        static double rk4(double y, double x, double dx, Func<double, double, double> f)
        {
            double k1 = dx * f(x, y);
            double k2 = dx * f(x + dx / 2.0, y + k1 / 2.0);
            double k3 = dx * f(x + dx / 2.0, y + k2 / 2.0);
            double k4 = dx * f(x + dx, y + k3);
 
            return y + (k1 + 2.0 * k2 + 2.0 * k3 + k4) / 6.0;
        }
 
        static double f(double x, double y)
        {
            return x * Math.Sqrt(y);
        }
 
        static double actual(double x)
        {
            return (1 / 16) * (x * x + 4) * (x * x + 4);
        }
    }
}

