namespace Humble_Numbers
{
    class Program
    {
        static void Main(string[] args)
        {
            int count = 0;
            int num = 0;
            int digits = 10;
            int limit = (int)Math.Pow(10, digits);
            int[] humble = new int[digits + 1];
            while ((num += 1) < limit)
            {
                if (humble(num))
                {
                    humble[num.ToString().Length] += 1;
                    if (count < 50)
                    {
                        Console.Write(num + " ");
                    }
                    count += 1;
                }
            }
            Console.WriteLine("\n\nOf the first {0} humble numbers:\n", count);
            for (int i = 1; i <= digits; i++)
            {
                Console.WriteLine("{0,5} have {1,2} digits", humble[i], i);
            }
            Console.ReadLine();
        }
        static bool humble(int i)
        {
            while (i % 2 == 0)
            {
                i /= 2;
            }
            while (i % 3 == 0)
            {
                i /= 3;
            }
            while (i % 5 == 0)
            {
                i /= 5;
            }
            while (i % 7 == 0)
            {
                i /= 7;
            }
            return i == 1;
        }
    }
}

