namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            SMA foo = new SMA(3);
            SMA bar = new SMA(5);
 
            int[] data = { 1, 2, 3, 4, 5, 5, 4, 3, 2, 1 };
            foreach (int i in data)
            {
                foo.add(i);
                Console.WriteLine("Added " + i + " avg: " + foo.avg());
            }
            Console.WriteLine();
            foreach (int i in data)
            {
                bar.add(i);
                Console.WriteLine("Added " + i + " avg: " + bar.avg());
            }
 
            Console.ReadKey();
        }
    }
 
    class SMA
    {
        private int period;
        private double[] window; // Holds the values to calculate the average of.
 
        // Logically, head is before tail
        private double[] head; // Points at the oldest element we've stored.
        private double[] tail; // Points at the newest element we've stored.
 
        private double total; // Cache the total so we don't sum everything each time.
 
        public SMA(int period)
        {
            this.period = period;
            window = new double[period];
            head = null;
            tail = null;
            total = 0;
        }
 
        // Adds a value to the average, pushing one out if nescessary
        public void add(double val)
        {
            // Special case: Initialization
            if (head == null)
            {
                head = window;
                head[0] = val;
                tail = head;
                inc(ref tail);
                total = val;
                return;
            }
 
            // Were we already full?
            if (head == tail)
            {
                // Fix total-cache
                total -= head[0];
                // Make room
                inc(ref head);
            }
 
            // Write the value in the next spot.
            tail[0] = val;
            inc(ref tail);
 
            // Update our total-cache
            total += val;
        }
 
        // Returns the average of the last P elements added to this SMA.
        // If no elements have been added yet, returns 0.0
        public double avg()
        {
            int size = this.size();
            if (size == 0)
            {
                return 0; // No entries => 0 average
            }
            return total / (double)size; // Cast to double for floating point arithmetic
        }
 
        // Bumps the given pointer up by one.
        // Wraps to the start of the array if needed.
        private void inc(ref double[] p)
        {
            if (++p[0] >= window.Length)
            {
                p[0] = 0;
            }
        }
 
        // Returns how many numbers we have stored.
        private int size()
        {
            if (head == null)
                return 0;
            if (head == tail)
                return period;
            return (period + (int)tail[0] - (int)head[0]) % period;
        }
    }
}

