using System;
 
public class Chowla {
  public static void Main(string[] args) {
    for (uint n = 1; n < 38; n ++) Console.WriteLine("chowla({0}) = {1}", n, chowla(n));
 
    uint n, count = 0, power = 100;
    for (n = 2; n < 10000001; n ++) {
      if (chowla(n) == 0) count ++;
      if (n % power == 0) Console.WriteLine("There is {0} primes < {1}", count, power), power *= 10;
    }
 
    count = 0;
    uint limit = 350000000;
    uint k = 2, kk = 3, p;
    for ( ; ; ) {
      if ((p = k * kk) > limit) break;
      if (chowla(p) == p - 1) {
        Console.WriteLine("{0} is a perfect number", p);
        count ++;
      }
      k = kk + 1; kk += k;
    }
    Console.WriteLine("There are {0} perfect numbers < {1}", count, limit);
  }
 
  public static uint chowla(uint n) {
    uint sum = 0;
    for (uint i = 2, j; i * i <= n; i ++) if (n % i == 0) sum += i + (i == (j = n / i)? 0 : j);
    return sum;
  }
}

