namespace Rextester
{
    public class Program
    {
        public static void Main(string[] args)
        {
            runTest(12, 1);
            runTest(12, 2);
            runTest(123, 45);
            runTest(123, 12345);
            runTest(123, 678910);
        }
 
        private static void runTest(int l, int n)
        {
            Console.WriteLine("p(" + l + ", " + n + ") = %,d".Format(p(l, n)));
        }
 
        public static int p(int l, int n)
        {
            int m = n;
            int test = 0;
            double log = Math.Log(2.0) / Math.Log(10.0);
            int factor = 1;
            int loop = l;
            while (loop > 10)
            {
                factor *= 10;
                loop /= 10;
            }
            while (m > 0)
            {
                test++;
                int value = (int)(factor * Math.Pow(10.0, test * log % 1));
                if (value == l)
                {
                    m--;
                }
            }
            return test;
        }
    }
}

