namespace Cholesky
{
    class Program
    {
        static void Main(string[] args)
        {
            double[][] arr3 = new double[][] { new double[] { 25, 15, -5 }, new double[] { 15, 18, 0 }, new double[] { -5, 0, 11 } };
            double[][] arr4 = new double[][] { new double[] { 18, 22, 54, 42 }, new double[] { 22, 70, 86, 62 }, new double[] { 54, 86, 174, 134 }, new double[] { 42, 62, 134, 106 } };
            Console.WriteLine(string.Join("\n", cholesky(arr3).Select(x => string.Join(" ", x))));
            Console.WriteLine(string.Join("\n", cholesky(arr4).Select(x => string.Join(" ", x))));
            Console.ReadKey();
        }
 
        static double[][] cholesky(double[][] array)
        {
            double[][] zeros = new double[array.Length][];
            for (int i = 0; i < array.Length; i++)
            {
                zeros[i] = new double[array.Length];
            }
            double[][] L = zeros.Select((row, r) => row.Select((v, c) =>
            {
                double sum = row.Take(c).Select((s, i) => i < c? s + L[r][i] * L[c][i] : s).Sum();
                return L[r][c] = c < r + 1? r == c? Math.Sqrt(array[r][r] - sum) : (array[r][c] - sum) / L[c][c] : v;
            }).ToArray()).ToArray();
            return L;
        }
    }
}

