using System.Diagnostics;
using System.Linq;
 
namespace WordChain
{
    class Program
    {
        static void Main(string[] args)
        {
            var pokimon = new[]
            {
                "audino", "bagon", "baltoy", "banette", "bidoof", "braviary", "bronzor", "carracosta", "charmeleon",
                "cresselia", "croagunk", "darmanitan", "deino", "emboar", "emolga", "exeggcute", "gabite", "girafarig",
                "gulpin", "haxorus", "heatmor", "heatran", "ivysaur", "jellicent", "jumpluff", "kangaskhan", "kricketune",
                "landorus", "ledyba", "loudred", "lumineon", "lunatone", "machamp", "magnezone", "mamoswine", "nosepass",
                "petilil", "pidgeotto", "pikachu", "pinsir", "poliwrath", "poochyena", "porygon2", "porygonz",
                "registeel", "relicanth", "remoraid", "rufflet", "sableye", "scolipede", "scrafty", "seaking", "sealeo",
                "silcoon", "simisear", "snivy", "snorlax", "spoink", "starly", "tirtouga", "trapinch", "treecko",
                "tyrogue", "vigoroth", "vulpix", "wailord", "wartortle", "whismur", "wingull", "yamask"
            };
 
            FindPaths(pokimon);
        }
 
        private static void FindPaths(string[] names)
        {
            var t0 = Stopwatch.StartNew();
            Console.WriteLine("Checking: {0} names", names.Length);
            var lookup = BuildLookup(names);
 
            var maxNum = 0;
            var maxPaths = new List<string[]>();
 
            void ParseResult(object[] arr)
            {
                foreach (var el in arr)
                {
                    if (el is object[] subArr)
                    {
                        ParseResult(subArr);
                    }
                    else
                    {
                        if (arr.Length > maxNum)
                        {
                            maxNum = arr.Length;
                            maxPaths = new List<string[]> { (string[])arr };
                        }
                        if (arr.Length == maxNum)
                        {
                            maxPaths.Add((string[])arr);
                        }
                    }
                }
            }
 
            void SearchWords(string word, List<string> res)
            {
                var cs = GetCandidates(lookup[EndsWith(word)], res);
                if (cs.Length == 0)
                {
                    ParseResult(res.ToArray());
                }
                else
                {
                    foreach (var e in cs)
                    {
                        var newRes = new List<string>(res) { e };
                        SearchWords(e, newRes);
                    }
                }
            }
 
            foreach (var word in names)
            {
                var res = new List<string> { word };
                SearchWords(word, res);
            }
 
            t0.Stop();
            Console.WriteLine("Execution time (hr): {0}s {1}ms", t0.Elapsed.Seconds, t0.Elapsed.Milliseconds);
            Console.WriteLine("Max Path: {0}", maxNum);
            Console.WriteLine("Matching Paths: {0}", maxPaths.Count);
            Console.WriteLine("Example Path: {0}", string.Join(", ", maxPaths[0]));
        }
 
        private static string EndsWith(string word)
        {
            return word[word.Length - 1].ToString();
        }
 
        private static string[] GetCandidates(string[] words, List<string> used)
        {
            return words.Where(e =>!used.Contains(e)).ToArray();
        }
 
        private static Dictionary<string, string[]> BuildLookup(string[] words)
        {
            var lookup = new Dictionary<string, string[]>();
            foreach (var e in words)
            {
                var start = e[0].ToString();
                if (!lookup.ContainsKey(start))
                {
                    lookup.Add(start, new[] { e });
                }
                else
                {
                    lookup[start] = lookup[start].Concat(new[] { e }).ToArray();
                }
            }
            return lookup;
        }
    }
}

