namespace BellTriangle
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = 51;
            int[][] tri = new int[n][];
            for (int i = 0; i < n; i++)
            {
                tri[i] = new int[i];
            }
            tri[1][0] = 1;
            for (int i = 2; i < n; i++)
            {
                tri[i][0] = tri[i - 1][i - 2];
                for (int j = 1; j < i; j++)
                {
                    tri[i][j] = tri[i][j - 1] + tri[i - 1][j - 1];
                }
            }
            Console.WriteLine("First fifteen and fiftieth Bell numbers:");
            for (int i = 1; i < 16; i++)
            {
                Console.WriteLine("{0,2}: {1}", i, tri[i][0]);
            }
            Console.WriteLine("50: {0}", tri[50][0]);
            Console.WriteLine();
            Console.WriteLine("The first ten rows of Bell's triangle:");
            for (int i = 1; i < 11; i++)
            {
                for (int j = 0; j < i; j++)
                {
                    Console.Write("{0,6}", tri[i][j]);
                }
                Console.WriteLine();
            }
            Console.ReadLine();
        }
    }
}

