using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using System.Diagnostics;
 
namespace XiaolinWu
{
    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length!= 1)
            {
                Console.WriteLine("usage: XiaolinWu.exe [output-file]");
                return;
            }
 
            var blue = Color.FromArgb(0, 0, 255);
            var yellow = Color.FromArgb(255, 255, 0);
            var img = new Bitmap(500, 500, PixelFormat.Format24bppRgb);
            using (var g = Graphics.FromImage(img))
            {
                g.Clear(blue);
                for (int a = 10; a < 431; a += 60)
                {
                    DrawLine(g, new Point(10, 10), new Point(490, a), yellow);
                    DrawLine(g, new Point(10, 10), new Point(a, 490), yellow);
                }
                DrawLine(g, new Point(10, 10), new Point(490, 490), yellow);
            }
            img.Save(args[0]);
            Console.WriteLine("image saved to {0}", args[0]);
        }
 
        static void DrawLine(Graphics g, Point p1, Point p2, Color color)
        {
            int x1 = p1.X;
            int y1 = p1.Y;
            int x2 = p2.X;
            int y2 = p2.Y;
            int dx = x2 - x1;
            int dy = y2 - y1;
            bool steep = Math.Abs(dx) < Math.Abs(dy);
            if (steep)
            {
                int t = x1;
                x1 = y1;
                y1 = t;
                t = x2;
                x2 = y2;
                y2 = t;
            }
            if (x2 < x1)
            {
                int t = x1;
                x1 = x2;
                x2 = t;
                t = y1;
                y1 = y2;
                y2 = t;
            }
            int grad = dy / dx;
            double intery = y1 + FPart(x1) * grad;
            Action<Point> drawEndpoint = pt =>
            {
                int x = pt.X;
                int y = pt.Y;
                int xend = (int)Math.Round(x);
                double yend = y + grad * (xend - x);
                double xgap = RfPart(x + 0.5);
                int px = steep? yend : xend;
                int py = steep? xend : yend;
                PutPixel(g, new Point(px, py), color, RfPart(yend) * xgap);
                PutPixel(g, new Point(px, py + 1), color, FPart(yend) * xgap);
            };
            int xstart = (int)Math.Ceiling(x1);
            drawEndpoint(new Point(xstart, (int)Math.Round(intery)));
            xstart++;
            int xend = (int)Math.Floor(x2);
            for (int x = xstart; x <= xend; x++)
            {
                int y = (int)Math.Round(intery);
                PutPixel(g, new Point(x, y), color, RfPart(intery));
                PutPixel(g, new Point(x, y + 1), color, FPart(intery));
                intery += grad;
            }
        }
 
        static double FPart(double x)
        {
            return x - Math.Floor(x);
        }
 
        static double RfPart(double x)
        {
            return 1 - FPart(x);
        }
 
        static void PutPixel(Graphics g, Point pt, Color color, double alpha)
        {
            var c = Color.FromArgb(
                (int)Math.Round(alpha * color.R + (1 - alpha) * g.GetPixel(pt.X, pt.Y).R),
                (int)Math.Round(alpha * color.G + (1 - alpha) * g.GetPixel(pt.X, pt.Y).G),
                (int)Math.Round(alpha * color.B + (1 - alpha) * g.GetPixel(pt.X, pt.Y).B));
            g.FillRectangle(new SolidBrush(c), pt.X, pt.Y, 1, 1);
        }
    }
}

