namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            var tab1 = new List<List<string>> {
                new List<string> { "27", "Jonah" },
                new List<string> { "18", "Alan" },
                new List<string> { "28", "Glory" },
                new List<string> { "18", "Popeye" },
                new List<string> { "28", "Alan" }
            };
            var tab2 = new List<List<string>> {
                new List<string> { "Jonah", "Whales" },
                new List<string> { "Jonah", "Spiders" },
                new List<string> { "Alan", "Ghosts" },
                new List<string> { "Alan", "Zombies" },
                new List<string> { "Glory", "Buffy" }
            };
            var tab3 = Join(tab1, 1, tab2, 0);
            Console.WriteLine("Table A: ");
            PrintTable(tab1);
            Console.WriteLine("Table B: ");
            PrintTable(tab2);
            Console.WriteLine("Joined tables: ");
            PrintTable(tab3);
            Console.ReadLine();
        }
        static void PrintTable(List<List<string>> table)
        {
            for (int i = 0; i < table.Count; i++)
            {
                Console.Write(i + ":");
                for (int j = 0; j < table[i].Count; j++)
                {
                    Console.Write("\t" + table[i][j]);
                }
                Console.WriteLine();
            }
        }
        static List<List<string>> Join(List<List<string>> a, int columna, List<List<string>> b, int columnb)
        {
            var hashmap = new Dictionary<string, List<int>>();
            // hash
            for (int i = 0; i < a.Count; i++)
            {
                if (!hashmap.ContainsKey(a[i][columna]))
                {
                    hashmap.Add(a[i][columna], new List<int>());
                }
                hashmap[a[i][columna]].Add(i);
            }
            // map
            var result = new List<List<string>>();
            for (int i = 0; i < b.Count; i++)
            {
                if (hashmap.ContainsKey(b[i][columnb]))
                {
                    foreach (var index in hashmap[b[i][columnb]])
                    {
                        var row = new List<string>();
                        row.AddRange(a[index]);
                        row.AddRange(b[i]);
                        result.Add(row);
                    }
                }
            }
            return result;
        }
    }
}

using System;
 
public class Vc
{
        public static void vc(int n, int base, out int num, out int denom)
        {
                int p = 0, q = 1;
 
                while (n!= 0) {
                        p = p * base + (n % base);
                        q *= base;
                        n /= base;
                }
 
                num = p;  
                denom = q;
 
                while (p!= 0) { int n = p; p = q % p; q = n; }
                num /= q;
                denom /= q;
        }
 
        public static void Main()
        {
                int d, n, i, b;
                for (b = 2; b < 6; b++) {
                        Console.Write("base {0}:", b);
                        for (i = 0; i < 10; i++) {
                                vc(i, b, out n, out d);
                                if (n!= 0) Console.Write("  {0}/{1}", n, d);
                                else   Console.Write("  0");
                        }
                        Console.WriteLine();
                }
        }
}

