			}
 
			string docname;
			XmlDocument doc;
			XPathExpression xpath = XPathExpression.Compile(args[2]);
			XPathNodeIterator nodeset;
			XPathResultType result;
			int i;
			string keyword;
 
			docname = args[1];
			doc = getdoc(docname);
			result = getnodeset(doc, xpath);
			if (result == XPathResultType.NodeSet)
			{
				nodeset = result.CreateNavigator().Select(xpath);
				for (i = 0; i < nodeset.Count; i++)
				{
					nodeset.MoveNext();
					keyword = nodeset.Current.Value;
					Console.WriteLine("Value {0}: {1}", i + 1, keyword);
				}
			}
			doc.Dispose();
		}
 
		static XmlDocument getdoc(string docname)
		{
			XmlDocument doc = new XmlDocument();
			doc.Load(docname);
			return doc;
		}
 
		static XPathResultType getnodeset(XmlDocument doc, XPathExpression xpath)
		{
			XPathNavigator nav = doc.CreateNavigator();
			return nav.Evaluate(xpath);
		}
	}
}

using System;
using System.Collections.Generic;
 
class Program
{
    static void Main()
    {
        var ss = ncs(new[] { 1, 2, 3, 4 });
        Console.WriteLine(ss.Length + " non-continuous subsequences:");
        foreach (var s in ss)
        {
            Console.WriteLine("  " + string.Join(", ", s));
        }
    }
 
    static int[] n2(int[] ss, int[] tail, int seq)
    {
        if (tail.Length == 0)
        {
            if (seq!= cmc)
            {
                return null;
            }
            return ss;
        }
        return n2(ss, tail.Skip(1).ToArray(), skip[seq]);
    }
 
    static int[] ncs(int[] s)
    {
        if (s.Length < 3)
        {
            return null;
        }
        return n2(null, s.Skip(1).ToArray(), m);
    }
 
    const int m = 0;
    const int c = 1;
    const int cm = 2;
    const int cmc = 3;
 
    static int[] skip = { m, cm, cm, cmc };
    static int[] incl = { c, c, cmc, cmc };
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            var scanner = new System.IO.StreamReader(Console.OpenStandardInput(8192));

            var total = 0;
            var quit = false;

            bool itob(int i)
            {
                if (i == 0)
                {
                    return false;
                }
                return true;
            }

            void getChoice()
            {
                while (true)
                {
                    Console.Write("Your choice 1 to 3 : ");
                    var text = scanner.ReadLine();
                    if (text == "q" || text == "Q")
                    {
                        quit = true;
                        return;
                    }
                    if (!int.TryParse(text, out var input))
                    {
                        Console.WriteLine("Invalid number, try again");
                        continue;
                    }
                    var newTotal = total + input;
                    switch (input)
                    {
                        case < 1 or > 3:
                            Console.WriteLine("Out of range, try again");
                            break;
                        case > 21:
                            Console.WriteLine("Too big, try again");
                            break;
                        default:
                            total = newTotal;
                            Console.WriteLine("Running total is now", total);
                            return;
                    }
                }
            }

            var computer = itob(new Random().Next(2));
            Console.WriteLine("Enter q to quit at any time\n");
            if (computer)
            {
                Console.WriteLine("The computer will choose first");
            }
            else
            {
                Console.WriteLine("You will choose first");
            }
            Console.WriteLine("\nRunning total is now 0\n");
            var choice = 0;
            for (var round = 1; ; round++)
            {
                Console.WriteLine($"ROUND {round}:\n");
                for (var i = 0; i < 2; i++)
                {
                    if (computer)
                    {
                        if (total < 18)
                        {
                            choice = 1 + new Random().Next(3);
                        }
                        else
                        {
                            choice = 21 - total;
                        }
                        total += choice;
                        Console.WriteLine("The computer chooses", choice);
                        Console.WriteLine("Running total is now", total);
                        if (total == 21)
                        {
                            Console.WriteLine("\nSo, commiserations, the computer has won!");
                            return;
                        }
                    }
                    else
                    {
                        getChoice();
                        if (quit)
                        {
                            Console.WriteLine("OK, quitting the game");
                            return;
                        }
                        if (total == 21)
                        {
                            Console.WriteLine("\nSo, congratulations, you've won!");
                            return;
                        }
                    }
                    Console.WriteLine();
                    computer =!computer;
                }
            }
        }
    }
}

