using System;
using System.IO;

public class Rot13
{
    public static void Main(string[] args)
    {
        if (args.Length >= 1)
        {
            foreach (string file in args)
            {
                using (Stream in_Renamed = new BufferedStream(new FileStream(file, FileMode.Open)))
                {
                    rot13(in_Renamed, Console.OpenStandardOutput());
                }
            }
        }
        else
        {
            rot13(Console.OpenStandardInput(), Console.OpenStandardOutput());
        }
    }

    private static void rot13(Stream in_Renamed, Stream out_Renamed)
    {
        int ch;
        while ((ch = in_Renamed.ReadByte())!= -1)
        {
            out_Renamed.WriteByte(rot13((char)ch));
        }
    }

    private static char rot13(char ch)
    {
        if (ch >= 'A' && ch <= 'Z')
        {
            return (char)(((ch - 'A') + 13) % 26 + 'A');
        }
        if (ch >= 'a' && ch <= 'z')
        {
            return (char)(((ch - 'a') + 13) % 26 + 'a');
        }
        return ch;
    }
}

