using System;
 
public class TruncatablePrimes {
 
    public static bool isPrime(int n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        if (n % 3 == 0) return n == 3;
        int d = 5;
        while (d * d <= n) {
            if (n % d == 0) return false;
            d += 2;
            if (n % d == 0) return false;
            d += 4;
        }
        return true;
    }
 
    public static void Main(string[] args) {
        char j;
        int p;
        int pow;
        int lMax = 2;
        int rMax = 2;
        string s;
 
        // calculate maximum left truncatable prime less than 1 million
        for( int i = 3; i <= 999997; i += 2) {
            s = i.ToString();
            if (s.Contains('0')) continue;
            j = s[s.Length - 1];
            if (j == '1' || j == '9') continue;
            p = i;
            pow = 1;
            for (int k = 1; k < s.Length; k++) pow *= 10;
            while(pow > 1) {
                if (!isPrime(p)) continue;
                p %= pow;
                pow /= 10;
            }
            lMax = i;
        }
 
        // calculate maximum right truncatable prime less than 1 million
        for( int i = 3; i <= 799999; i += 2) {
            s = i.ToString();
            if (s.Contains('0')) continue;
            j = s[0];
            if (j == '1' || j == '4' || j == '6') continue;
            p = i;
            while(p > 0) {
                if (!isPrime(p)) continue;
                p /= 10;
            }
            rMax = i;
        }
 
        Console.WriteLine("Largest left  truncatable prime : " + lMax.ToString());
        Console.WriteLine("Largest right truncatable prime : " + rMax.ToString());    
    }
}

public static void Line(float x1, float y1, float x2, float y2, Color color)
{
    // Bresenham's line algorithm
    bool steep = (Math.Abs(y2 - y1) > Math.Abs(x2 - x1));
    if (steep)
    {
        float temp = x1;
        x1 = y1;
        y1 = temp;
        temp = x2;
        x2 = y2;
        y2 = temp;
    }
    if (x1 > x2)
    {
        float temp = x1;
        x1 = x2;
        x2 = temp;
        temp = y1;
        y1 = y2;
        y2 = temp;
    }
    float dx = x2 - x1;
    float dy = Math.Abs(y2 - y1);
    float error = dx / 2.0f;
    int ystep = (y1 < y2)? 1 : -1;
    int y = (int)y1;
    int maxX = (int)x2;
    for (int x = (int)x1; x <= maxX; x++)
    {
        if (steep)
        {
            SetPixel(y, x, color);
        }
        else
        {
            SetPixel(x, y, color);
        }
        error -= dy;
        if (error < 0)
        {
            y += ystep;
            error += dx;
        }
    }
}

