using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
 
namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] GivenPermutations = { "ABCD", "CABD", "ACDB", "DACB", "BCDA", "ACBD", "ADCB", "CDAB", "DABC", "BCAD", "CADB", "CDBA", "CBAD", "ABDC", "ADBC", "BDCA", "DCBA", "BACD", "BADC", "BDAC", "CBDA", "DBCA", "DCAB" };
            List<string> permutations = new List<string>();
            string initial = "ABCD";
            permutations.Add(initial);
 
            while (true)
            {
                string p = permutations.Last();
                string next = NextPermutation(p);
                if (next == permutations.First())
                    break;
                permutations.Add(next);
            }
 
            List<string> missing = new List<string>();
            HashSet<string> given_permutations = new HashSet<string>(GivenPermutations);
            missing = permutations.Except(given_permutations).ToList();
            foreach (string s in missing)
                Console.WriteLine(s);
        }
 
        static string NextPermutation(string s)
        {
            int i = s.Length - 1;
            while (i > 0 && s[i - 1] >= s[i])
                i--;
            if (i <= 0)
                return String.Empty;
 
            int j = s.Length - 1;
            while (s[j] <= s[i - 1])
                j--;
            char temp = s[i - 1];
            s = s.Remove(i - 1, 1);
            s = s.Insert(i - 1, s[j].ToString());
            s = s.Remove(j, 1);
            s = s.Insert(j, temp.ToString());
            return s;
        }
    }
}

