using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            var tables = new List<List<Tuple<string, string>>>();
            tables.Add(new List<Tuple<string, string>>()
            {
                new Tuple<string, string>("1", "2"),
                new Tuple<string, string>("3", "1"),
                new Tuple<string, string>("3", "6"),
                new Tuple<string, string>("6", "7"),
                new Tuple<string, string>("7", "6"),
                new Tuple<string, string>("2", "3"),
                new Tuple<string, string>("4", "2"),
                new Tuple<string, string>("4", "3"),
                new Tuple<string, string>("4", "5"),
                new Tuple<string, string>("5", "6"),
                new Tuple<string, string>("5", "4"),
                new Tuple<string, string>("8", "5"),
                new Tuple<string, string>("8", "7"),
                new Tuple<string, string>("8", "6")
            });
            tables.Add(new List<Tuple<string, string>>()
            {
                new Tuple<string, string>("A", "B"),
                new Tuple<string, string>("B", "C"),
                new Tuple<string, string>("C", "A"),
                new Tuple<string, string>("A", "Other")
            });
            foreach (var table in tables)
            {
                var nodes = from_edges(table);
                foreach (var g in trajan(nodes))
                {
                    Console.WriteLine(string.Join(",", g));
                }
                Console.WriteLine();
            }
            Console.ReadLine();
        }
 
        public static List<Node> from_edges(List<Tuple<string, string>> edges)
        {
            var nodes = new Dictionary<string, Node>();
            foreach (var edge in edges)
            {
                var v = edge.Item1;
                var w = edge.Item2;
                if (!nodes.ContainsKey(v))
                {
                    nodes.Add(v, new Node());
                }
                if (!nodes.ContainsKey(w))
                {
                    nodes.Add(w, new Node());
                }
                nodes[v].succ.Add(nodes[w]);
            }
            var res = new List<Node>();
            foreach (var node in nodes)
            {
                node.Value.id = node.Key;
                res.Add(node.Value);
            }
            return res;
        }
 
        public static IEnumerable<List<string>> trajan(List<Node> V)
        {
            var S = new List<Node>();
            foreach (var v in V)
            {
                if (v.root == null)
                {
                    foreach (var g in strongconnect(v, S))
                    {
                        yield return g;
                    }
                }
            }
        }
 
        public static IEnumerable<List<string>> strongconnect(Node v, List<Node> S)
        {
            v.root = S.Count;
            S.Add(v);
            foreach (var w in v.succ)
            {
                if (w.root == null)
                {
                    foreach (var g in strongconnect(w, S))
                    {
                        yield return g;
                    }
                }
                if (w.root >= 0)
                {
                    v.root = Math.Min(v.root, w.root);
                }
            }
            if (v.root == S.Count)
            {
                var res = S.Skip(v.root).ToList();
                S.RemoveRange(v.root, S.Count - v.root);
                foreach (var w in res)
                {
                    w.root = -1;
                }
                yield return res.Select(x => x.id).ToList();
            }
        }
    }
 
    public class Node
    {
        public string id;
        public int? root;
        public List<Node> succ;
        public Node()
        {
            root = null;
            succ = new List<Node>();
        }
    }
}

using System;
using System.Numerics;
 
namespace Currency
{
    class Program
    {
        static void Main(string[] args)
        {
            var hamburger = new Currency(5.50);
            var milkshake = new Currency(2.86);
            var preTax = hamburger * 4_000_000_000_000_000 + milkshake * 2;
            Console.WriteLine($"Price before tax: {preTax}");
            var tax = preTax.CalculateTax();
            Console.WriteLine($"Tax: {tax}");
            var postTax = preTax + tax;
            Console.WriteLine($"Price after tax: {postTax}");
        }
    }
 
    class Currency
    {
        public BigRational Amount { get; }
 
        public Currency(double num)
        {
            Amount = new BigRational(((num * 100.0) as long), 100);
        }
 
        public static Currency operator +(Currency a, Currency b)
        {
            return new Currency(a.Amount + b.Amount);
        }
 
        public static Currency operator *(Currency a, long b)
        {
            return new Currency(a.Amount * b);
        }
 
        public override string ToString()
        {
            var cents = (Amount * 100).ToInteger();
            return $"${cents / 100}.{cents % 100}";
        }
 
        public Currency CalculateTax()
        {
            var taxVal = new BigRational(765, 100);
            var amount = (Amount * taxVal).Ceiling() / 100;
            return new Currency(amount);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            const int limit = 201; // means sieve numbers < 201

            // sieve
            bool[] c = new bool[limit]; // c for composite.  false means prime candidate
            c[1] = true; // 1 not considered prime
            int p = 2;
            while (true)
            {
                // first allowed optimization:  outer loop only goes to sqrt(limit)
                int p2 = p * p;
                if (p2 >= limit)
                {
                    break;
                }
                // second allowed optimization:  inner loop starts at sqr(p)
                for (int i = p2; i < limit; i += p)
                {
                    c[i] = true; // it's a composite

                }
                // scan to get next prime for outer loop
                while (true)
                {
                    p++;
                    if (!c[p])
                    {
                        break;
                    }
                }
            }

            // sieve complete.  now print a representation.
            for (int n = 1; n < limit; n++)
            {
                if (c[n])
                {
                    Console.Write(" .");
                }
                else
                {
                    Console.Write("{0,3}", n);
                }
                if (n % 20 == 0)
                {
                    Console.WriteLine("");
                }
            }
        }
    }
}

