using System;
using System.Collections.Generic;
using System.Linq;
 
namespace LatinSquare
{
    class Program
    {
        static void Main(string[] args)
        {
            LatinSquare(5);
            LatinSquare(5);
            LatinSquare(10);
        }
 
        static void LatinSquare(int n)
        {
            if (n <= 0)
            {
                Console.WriteLine("[]\n");
                return;
            }
            var latin = new int[n][];
            for (int i = 0; i < n; i++)
            {
                latin[i] = new int[n];
                if (i == n - 1)
                {
                    break;
                }
                for (int j = 0; j < n; j++)
                {
                    latin[i][j] = j;
                }
            }
            // first row
            Shuffle(latin[0], n);
 
            // middle row(s)
            for (int i = 1; i < n - 1; i++)
            {
                bool shuffled = false;
            shuffling:
                for (;!shuffled; )
                {
                    Shuffle(latin[i], n);
                    for (int k = 0; k < i; k++)
                    {
                        for (int j = 0; j < n; j++)
                        {
                            if (latin[k][j] == latin[i][j])
                            {
                                continue shuffling;
                            }
                        }
                    }
                    shuffled = true;
                }
            }
 
            // last row
            for (int j = 0; j < n; j++)
            {
                var used = new bool[n];
                for (int i = 0; i < n - 1; i++)
                {
                    used[latin[i][j]] = true;
                }
                for (int k = 0; k < n; k++)
                {
                    if (!used[k])
                    {
                        latin[n - 1][j] = k;
                        break;
                    }
                }
            }
            PrintSquare(latin, n);
        }
 
        static void PrintSquare(int[][] latin, int n)
        {
            for (int i = 0; i < n; i++)
            {
                Console.WriteLine(string.Join(" ", latin[i]));
            }
            Console.WriteLine();
        }
 
        static void Shuffle(int[] row, int n)
        {
            var rand = new Random();
            for (int i = 0; i < n; i++)
            {
                int j = rand.Next(i, n);
                int temp = row[i];
                row[i] = row[j];
                row[j] = temp;
            }
        }
    }
}

/* TrySort.cs */
 
using System;
using System.Collections;
using System.Runtime.InteropServices;
 
public class TrySort {
    static bool useC;
    static TrySort() {
	try {
	    System.loadLibrary("TrySort");
	    useC = true;
	} catch(UnsatisfiedLinkError e) {
	    useC = false;
	}
    }
 
    [DllImport("TrySort")]
    static extern void sortInC(int[] ary);
 
    class IntList : AbstractList {
	int[] ary;
	IntList(int[] ary) { this.ary = ary; }
	public Integer get(int i) { return ary[i]; }
	public Integer set(int i, Integer j) {
	    Integer o = ary[i]; ary[i] = j; return o;
	}
	public int size() { return ary.length; }
    }
 
    class ReverseAbsCmp : Comparator {
	public int compare(Integer pa, Integer pb) {
	    /* Order from highest to lowest absolute value. */
	    int a = pa > 0? -pa : pa;
	    int b = pb > 0? -pb : pb;
	    return a < b? -1 : a > b? 1 : 0;
	}
    }
 
    static void sortInJava(int[] ary) {
	Collections.sort(new IntList(ary), new ReverseAbsCmp());
    }
 
    public static void main(String[] args) {
	/* Create an array of random integers. */
	int[] ary = new int[1000000];
	Random rng = new Random();
	for (int i = 0; i < ary.length; i++)
	    ary[i] = rng.nextInt();
 
	/* Do the reverse sort. */
	if (useC) {
	    System.out.print("Sorting in C...  ");
	    sortInC(ary);
	} else {
	    System.out.print
		("Missing library for C!  Sorting in Java...  ");
	    sortInJava(ary);
