using System;
 
public class Program
{
    public static void Main()
    {
        int prod = 1;
        int sum = 0;
        const int x = 5;
        const int y = -5;
        const int z = -2;
        const int one = 1;
        const int three = 3;
        const int seven = 7;
        int p = pow(11, x);
        int j;
 
        Action process = () =>
        {
            sum += abs(j);
            if (abs(prod) < (1 << 27) && j!= 0)
            {
                prod *= j;
            }
        };
 
        for (j = -three; j <= pow(3, 3); j += three)
        {
            process();
        }
        for (j = -seven; j <= seven; j += x)
        {
            process();
        }
        for (j = 555; j <= 550 - y; j++)
        {
            process();
        }
        for (j = 22; j >= -28; j -= three)
        {
            process();
        }
        for (j = 1927; j <= 1939; j++)
        {
            process();
        }
        for (j = x; j >= y; j -= -z)
        {
            process();
        }
        for (j = p; j <= p + one; j++)
        {
            process();
        }
        Console.WriteLine("sum  = " + commatize(sum));
        Console.WriteLine("prod = " + commatize(prod));
    }
 
    public static int pow(int n, uint e)
    {
        if (e == 0)
        {
            return 1;
        }
        int prod = n;
        for (uint i = 2; i <= e; i++)
        {
            prod *= n;
        }
        return prod;
    }
 
    public static int abs(int n)
    {
        if (n >= 0)
        {
            return n;
        }
        return -n;
    }
 
    public static string commatize(int n)
    {
        string s = n.ToString();
        if (n < 0)
        {
            s = s.Substring(1);
        }
        int le = s.Length;
        for (int i = le - 3; i >= 1; i -= 3)
        {
            s = s.Substring(0, i) + "," + s.Substring(i);
        }
        if (n >= 0)
        {
            return " " + s;
        }
        return "-" + s;
    }
}

