using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Numerics;
 
namespace PellEquation
{
    class Program
    {
        static void Main(string[] args)
        {
            for (int n = 61; n <= 277; n += 124)
            {
                BigInteger x, y;
                SolvePell(n, out x, out y);
                Console.WriteLine("x^2 - {0} * y^2 = 1 for x = {1} and y = {2}", n, x, y);
            }
        }
 
        static void SolvePell(int n, out BigInteger x, out BigInteger y)
        {
            x = (BigInteger)Math.Sqrt(n);
            BigInteger y1 = x, z = 1, r = x << 1;
            BigInteger e1 = 1, e2 = 0;
            BigInteger f1 = 0, f2 = 1;
            while (true)
            {
                y1 = r * z - y1;
                z = (n - y1 * y1) / z;
                r = (x + y1) / z;
 
                e1 = e2; e2 = e1 + e2 * r;
                f1 = f2; f2 = f1 + f2 * r;
 
                BigInteger a = f2 * x + e2;
                BigInteger b = f2;
                if (a * a - n * b * b == 1)
                {
                    x = a; y = b;
                    return;
                }
            }
        }
    }
}

