    class Program
    {
        static void Main(string[] args)
        {
            do
            {
                Console.Write("\ninput a boolean expression (e.g. 'a & b'): ");
                string expr = Console.ReadLine().Trim().ToLower();
                if (expr.Length == 0)
                    break;

                List<string> vars = new List<string>();
                foreach (Match m in Regex.Matches(expr, @"\p{Alpha}+"))
                    vars.Add(m.Value);

                if (vars.Count == 0)
                {
                    Console.WriteLine("no variables detected in your boolean expression");
                    continue;
                }

                foreach (string v in vars)
                    Console.Write(v + "\t");
                Console.WriteLine("| " + expr);

                List<string> prefix = new List<string>();
                List<string> suffix = new List<string>();
                foreach (string v in vars)
                {
                    prefix.Add("foreach (bool " + v + " in new bool[] { false, true })");
                    suffix.Add("}");
                }

                string body = "Console.Write(";
                foreach (string v in vars)
                    body += v + ".ToString() + \"\t\" + ";
                body += "\"| \" + " + expr + ".ToString());";

                string code = string.Join("\n", prefix) + "\n" + body + "\n" + string.Join("\n", suffix);
                Console.WriteLine(code);
                ScriptEngine engine = IronRuby.Ruby.CreateEngine();
                engine.Execute(code);
            } while (true);
        }
    }
