namespace Hofstadter_Q_sequence
{
    class Program
    {
        static void Main(string[] args)
        {
            int v1 = int.Parse(args[0]);
            int v2 = int.Parse(args[1]);
            HashSet<int> r = new HashSet<int>();
            HashSet<int> s = new HashSet<int>();
            for (int n = 1; n <= v2; n++)
            {
                if (n <= v1)
                    r.Add(hofstadter(n, 0));
                s.Add(hofstadter(0, n));
            }
            Console.WriteLine("R" + r);
            Console.WriteLine("S" + s);

            int m = Math.Max(r.Max(), s.Max());
            for (int n = 1; n <= m; n++)
                if (r.Contains(n) == s.Contains(n))
                    Console.WriteLine("integer " + n + " either in both or neither set");
        }

        static int hofstadter(int rlistSize, int slistSize)
        {
            int n = rlistSize > slistSize? rlistSize : slistSize;
            List<int> rlist = new List<int> { 1, 3, 7 };
            List<int> slist = new List<int> { 2, 4, 5, 6 };
            List<int> list = rlistSize > 0? rlist : slist;
            int target_size = rlistSize > 0? rlistSize : slistSize;

            while (list.Count > target_size) list.RemoveAt(list.Count - 1);

            while (list.Count < target_size)
            {
                int lastIndex = rlist.Count - 1;
                int lastr = rlist[lastIndex];
                int r = lastr + slist[lastIndex];
                rlist.Add(r);
                for (int s = lastr + 1; s < r && list.Count < target_size; s++)
                    slist.Add(s);
            }

            int v = list[n - 1];
            return v;
        }
    }
}

using System;
