namespace DDate
{
    class Program
    {
        static void Main(string[] args)
        {
            int year, doy;
            if (args.Length == 0)
            {
                DateTime now = DateTime.Now;
                year = now.Year;
                doy = now.DayOfYear;
            }
            else if (args.Length == 3)
            {
                year = int.Parse(args[0]);
                doy = DayOfYear(int.Parse(args[1]), int.Parse(args[2]));
            }
            else
            {
                throw new Exception("Invalid number of arguments");
            }
            Console.WriteLine(DDate(year, doy));
        }
 
        static string DDate(int y, int d)
        {
            int dyear = 1166 + y;
            if (IsLeapYear(y))
            {
                if (d == 60)
                {
                    return string.Format("St. Tib's Day, YOLD {0}", dyear);
                }
                else if (d >= 60)
                {
                    d--;
                }
            }
            return string.Format("{0}, {1} {2}, YOLD {3}",
                DayOfWeek(d % 5), Season((d % 73 == 0? d - 1 : d) / 73), Date(d), dyear);
        }
 
        static string DayOfWeek(int x)
        {
            switch (x)
            {
                case 1: return "Sweetmorn";
                case 2: return "Boomtime";
                case 3: return "Pungenday";
                case 4: return "Prickle-Prickle";
                default: return "Setting Orange";
            }
        }
 
        static string Season(int x)
        {
            switch (x)
            {
                case 0: return "Chaos";
                case 1: return "Discord";
                case 2: return "Confusion";
                case 3: return "Bureaucracy";
                default: return "The Aftermath";
            }
        }
 
        static int Date(int x)
        {
            return x % 73 == 0? 73 : x % 73;
        }
 
        static bool IsLeapYear(int y)
        {
            return y % 400 == 0 || (y % 4 == 0 && y % 100!= 0);
        }
 
        static int DayOfYear(int y, int m, int d)
        {
            int[] monthLengths = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
            for (int i = m - 1; i > 0; i--)
            {
                d += monthLengths[i - 1];
                if (i == 2 && IsLeapYear(y))
                {
                    d++;
                }
            }
            return d;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConsoleApplication1
{
    class Program
    {
        private interface Ring<T>
        {
            Ring<T> plus(Ring<T> rhs);

            Ring<T> times(Ring<T> rhs);

            int value();

            Ring<T> one();

            default Ring<T> pow(int p)
            {
                if (p < 0)
                {
                    throw new ArgumentException("p must be zero or greater");
                }

                int pp = p;
                Ring<T> pwr = this.one();
                while (pp-- > 0)
                {
                    pwr = pwr.times(this);
                }
                return pwr;
            }
        }

        private class ModInt : Ring<ModInt>
        {
            private int value;
            private int modulo;

            private ModInt(int value, int modulo)
            {
                this.value = value;
                this.modulo = modulo;
            }

            public Ring<ModInt> plus(Ring<ModInt> other)
            {
                if (!(other is ModInt))
                {
                    throw new ArgumentException("Cannot add an unknown ring.");
                }
                ModInt rhs = (ModInt)other;
                if (modulo!= rhs.modulo)
                {
                    throw new ArgumentException("Cannot add rings with different modulus");
                }
                return new ModInt((value + rhs.value) % modulo, modulo);
            }

            public Ring<ModInt> times(Ring<ModInt> other)
            {
                if (!(other is ModInt))
                {
                    throw new ArgumentException("Cannot multiple an unknown ring.");
                }
                ModInt rhs = (ModInt)other;
                if (modulo!= rhs.modulo)
                {
                    throw new ArgumentException("Cannot multiply rings with different modulus");
                }
                return new ModInt((value * rhs.value) % modulo, modulo);
            }

            public int value()
            {
                return value;
            }

            public Ring<ModInt> one()
            {
                return new ModInt(1, modulo);
            }

            public override string ToString()
            {
                return String.Format("ModInt({0}, {1})", value, modulo);
            }
        }

        private static Ring<T> f<T>(Ring<T> x)
        {
            return x.pow(100).plus(x).plus(x.one());
        }

        public static void Main(string[] args)
        {
            ModInt x = new ModInt(10, 13);
            Ring<ModInt> y = f(x);
            Console.WriteLine("x ^ 100 + x + 1 for x = ModInt(10, 13) is {0}", y);
            Console.ReadKey();
        }
    }
}

