namespace Euler
{
	class MainClass
	{
		public static void Main (string[] args)
		{
			// Function that takes differential-equation, initial condition,
			// ending x, and step size as parameters
			double eulersMethod(Func<double, double, double> f, double x1, double y1, double x2, double h) {
				// Header
				Console.WriteLine("\tX\t|\tY\t");
				Console.WriteLine("------------------------------------");
			 
				// Initial Variables
				double x=x1, y=y1;
			 
				// While we're not done yet
				// Both sides of the OR let you do Euler's Method backwards
				while ((x<x2 && x1<x2) || (x>x2 && x1>x2)) {
					// Print what we have
					Console.WriteLine("\t" + x + "\t|\t" + y);
			 
					// Calculate the next values
					y += h*f(x, y)
					x += h;
				}
			 
				return y;
			}
		 
			double cooling(double x, double y) {
				return -0.07 * (y-20);
			}
		 
			eulersMethod(cooling, 0, 100, 100, 10);
		}
	}
}

