namespace Rextester
{
    public class Program
    {
        public static void Main(string[] args)
        {
            var cs = new List<List<double>> {
                new List<double> { 15.0, 6.0, 42.0, 41.0, 7.0, 36.0, 49.0, 40.0, 39.0, 47.0, 43.0 },
                new List<double> { 36.0, 40.0, 7.0, 39.0, 41.0, 15.0 },
                new List<double> {
                    0.14082834,  0.09748790,  1.73131507,  0.87636009, -1.95059594,  0.73438555,
                   -0.03035726,  1.46675970, -0.74621349, -0.72588772,  0.63905160,  0.61501527,
                   -0.98983780, -1.00447874, -0.62759469,  0.66206163,  1.04312009, -0.10305385,
                    0.75775634,  0.32566578
                }
            };
 
            foreach (var c in cs) {
                Console.WriteLine(fivenum(c));
            }
        }
 
        public static double median(List<double> c) {
            if (c.Count == 0) throw new Exception("Range cannot be empty");
            var len = c.Count;
            var m = len / 2;
            if (len % 2 == 1) {
                return c[m];
            }
 
            return (c[m - 1] + c[m]) / 2.0;
        }
 
        public static Tuple<double, double, double, double, double> fivenum(List<double> c) {
            c.Sort();
 
            var len = c.Count;
            var m = len / 2;
            var lower = (len % 2 == 1)? m : m - 1;
            double r2 = median(c.GetRange(0, lower + 1));
            double r3 = median(c);
            double r4 = median(c.GetRange(lower + 1, len - lower - 1));
 
            return new Tuple<double, double, double, double, double>(c[0], r2, r3, r4, c[len - 1]);
        }
    }
}

