using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Numerics;
 
namespace ProjectEuler
{
    class Problem_30
    {
        static int MAX_LEN = 81;
        static BigInteger[] power = new BigInteger[10];
        static BigInteger[] dsum = new BigInteger[MAX_LEN + 1];
        static int[] cnt = new int[10];
        static int len;
 
        static void check_perm()
        {
            char[] s = dsum[0].ToString().ToCharArray();
            int[] out = new int[10];
 
            for (int i = 0; i < s.Length; i++)
            {
                int c = s[i] - '0';
                if (++out[c] > cnt[c]) return;
            }
 
            if (s.Length == len)
                Console.Write(" {0}", dsum[0]);
        }
 
        static void narc_(int pos, int d)
        {
            if (pos == 0)
            {
                check_perm();
                return;
            }
 
            do
            {
                dsum[pos - 1] = dsum[pos] + power[d];
                ++cnt[d];
                narc_(pos - 1, d);
                --cnt[d];
            } while (d-- > 0);
        }
 
        static void narc(int n)
        {
            len = n;
            for (int i = 0; i < 10; i++)
                power[i] = BigInteger.Pow(i, n);
 
            dsum[n] = 0;
 
            Console.Write("length {0}:", n);
            narc_(n, 9);
            Console.WriteLine();
        }
 
        static void Main(string[] args)
        {
            for (int i = 1; i <= MAX_LEN; i++) narc(i);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            var tests = new string[] {
                "3 4 2 * 1 5 - 2 3 ^ ^ / +",
                "1 2 + 3 4 + ^ 5 6 + ^",
            };

            var opa = new Dictionary<string, Tuple<int, bool>> {
                { "^", new Tuple<int, bool>(4, true) },
                { "*", new Tuple<int, bool>(3, false) },
                { "/", new Tuple<int, bool>(3, false) },
                { "+", new Tuple<int, bool>(2, false) },
                { "-", new Tuple<int, bool>(2, false) },
            };

            const int nPrec = 9;

            foreach (var t in tests)
            {
                parseRPN(t);
            }
        }

        static void parseRPN(string e)
        {
            Console.WriteLine("\npostfix: " + e);
            var stack = new List<Tuple<int, string>>();
            foreach (var tok in e.Split(' '))
            {
                Console.WriteLine("token: " + tok);
                if (opa.ContainsKey(tok))
                {
                    var op = opa[tok];
                    var rhs = stack[stack.Count - 1];
                    stack.RemoveAt(stack.Count - 1);
                    var lhs = stack[stack.Count - 1];
                    if (lhs.Item1 < op.Item1 || (lhs.Item1 == op.Item1 && op.Item2))
                    {
                        lhs = new Tuple<int, string>(lhs.Item1, "(" + lhs.Item2 + ")");
                    }
                    lhs = new Tuple<int, string>(lhs.Item1, lhs.Item2 + " " + tok + " ");
                    if (rhs.Item1 < op.Item1 || (rhs.Item1 == op.Item1 &&!op.Item2))
                    {
                        lhs = new Tuple<int, string>(lhs.Item1, lhs.Item2 + "(" + rhs.Item2 + ")");
                    }
                    else
                    {
                        lhs = new Tuple<int, string>(lhs.Item1, lhs.Item2 + rhs.Item2);
                    }
                    lhs = new Tuple<int, string>(op.Item1, lhs.Item2);
                    stack[stack.Count - 1] = lhs;
                }
                else
                {
                    stack.Add(new Tuple<int, string>(nPrec, tok));
                }
                foreach (var f in stack)
                {
                    Console.WriteLine("    " + f.Item1 + " " + f.Item2);
                }
            }
            Console.WriteLine("infix: " + stack[0].Item2);
        }
    }
}

