using System;
 
namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            var a = new int[] { 1, 3, 4, 5, 6, 7, 8, 9, 10 };
            var target = 6;
            var r = IterativeBinarySearch(a, target);
            Console.WriteLine(r < 0? $"{target} not found" : $"{target} found at index {r}");
            target = 250;
            r = IterativeBinarySearch(a, target);
            Console.WriteLine(r < 0? $"{target} not found" : $"{target} found at index {r}");
 
            target = 6;
            r = RecursiveBinarySearch(a, target, 0, a.Length);
            Console.WriteLine(r < 0? $"{target} not found" : $"{target} found at index {r}");
            target = 250;
            r = RecursiveBinarySearch(a, target, 0, a.Length);
            Console.WriteLine(r < 0? $"{target} not found" : $"{target} found at index {r}");
        }
 
        static int IterativeBinarySearch<T>(T[] a, T target) where T : IComparable<T>
        {
            var hi = a.Length - 1;
            var lo = 0;
            while (hi >= lo)
            {
                var guess = lo + (hi - lo) / 2;
                if (a[guess].CompareTo(target) > 0) hi = guess - 1;
                else if (a[guess].CompareTo(target) < 0) lo = guess + 1;
                else return guess;
            }
            return -1;
        }
 
        static int RecursiveBinarySearch<T>(T[] a, T target, int lo, int hi) where T : IComparable<T>
        {
            if (hi < lo) return -1;
 
            var guess = (hi + lo) / 2;
 
            return a[guess].CompareTo(target) > 0? RecursiveBinarySearch(a, target, lo, guess - 1) :
                a[guess].CompareTo(target) < 0? RecursiveBinarySearch(a, target, guess + 1, hi) : guess;
        }
    }
}

using System;
using System.Linq;
 
public class Test
{
    static char[] left  = "HXUCZVAMDSLKPEFJRIGTWOBNYQ".ToCharArray();
    static char[] right = "PTLNBQDEOYSFAVZKGJRIHWXUMC".ToCharArray();
 
    public static void Main()
    {
        string txt = "WELLDONEISBETTERTHANWELLSAID";
        Console.WriteLine(string.Join("", txt.Select(c => encrypt(c))));
    }
 
    static char encrypt(char c)
    {
        char coded_char = left[Array.IndexOf(right, c)];
 
        int index = Array.IndexOf(left, coded_char);
        left = left.Rotate(index);
        char[] part = left.Slice(1, 13).Rotate();
        left = left.Insert(1, part);
 
        index = Array.IndexOf(right, c);
        right = right.Rotate(index + 1);
        part = right.Slice(2, 12).Rotate();
        right = right.Insert(2, part);
 
        return left[0];
    }
}
 
public static class Extensions
{
    public static T[] Rotate<T>(this T[] array, int count)
    {
        T[] result = new T[array.Length];
        Array.Copy(array, count, result, 0, array.Length - count);
        Array.Copy(array, 0, result, array.Length - count, count);
        return result;
    }
 
    public static T[] Slice<T>(this T[] array, int start, int length)
    {
        T[] result = new T[length];
        Array.Copy(array, start, result, 0, length);
        return result;
    }
 
    public static T[] Insert<T>(this T[] array, int index, T[] items)
    {
        T[] result = new T[array.Length + items.Length];
        Array.Copy(array, 0, result, 0, index);
        Array.Copy(items, 0, result, index, items.Length);
        Array.Copy(array, index, result, index + items.Length, array.Length - index);
        return result;
    }
}

