using System;
using System.Numerics;
 
public class Binomial
{
    public static BigInteger BinomialCoefficient(BigInteger n, BigInteger k)
    {
        BigInteger d, g, r = 1;
        if (k == 0) return 1;
        if (k == 1) return n;
        if (k >= n) return (k == n)? 1 : 0;
        if (k > n / 2) k = n - k;
        for (d = 1; d <= k; d++)
        {
            if (r >= BigInteger.One - n)
            {
                BigInteger nr, dr;
                g = GCD(n, d); nr = n / g; dr = d / g;
                g = GCD(r, dr); r = r / g; dr = dr / g;
                if (r >= BigInteger.One - nr) return 0;
                r *= nr;
                r /= dr;
                n--;
            }
            else
            {
                r *= n--;
                r /= d;
            }
        }
        return r;
    }
 
    public static BigInteger GCD(BigInteger a, BigInteger b)
    {
        BigInteger t;
        if (b < a) { t = a; a = b; b = t; }
        while (b > 0) { t = b; b = a % b; a = t; }
        return a;
    }
 
    public static void Main()
    {
        Console.WriteLine(BinomialCoefficient(5, 3));
        Console.WriteLine(BinomialCoefficient(40, 19));
        Console.WriteLine(BinomialCoefficient(67, 31));
    }
}

using System;
using System.Numerics;
 
public class Hamming
{
    public static BigInteger[] hamming(int n)
    {
        BigInteger[] h = new BigInteger[n];
        h[0] = 1;
        BigInteger two = 2, three = 3, five = 5;
        BigInteger next2 = 2, next3 = 3, next5 = 5;
        int i = 0, j = 0, k = 0;
        for (int m = 1; m < n; m++)
        {
            h[m] = min(next2, min(next3, next5));
            if (h[m] == next2) { i++; next2 = two * h[i]; }
            if (h[m] == next3) { j++; next3 = three * h[j]; }
            if (h[m] == next5) { k++; next5 = five * h[k]; }
        }
        return h;
    }
 
    public static BigInteger min(BigInteger a, BigInteger b)
    {
        if (a < b) return a;
        return b;
    }
 
    public static void Main()
    {
        BigInteger[] h = hamming(1000000);
        Console.WriteLine(h[1691 - 1]);
        Console.WriteLine(h[h.Length - 1]);
    }
}

