using System;
 
public class MontyHall
{
    public static void Main(string[] args)
    {
        montyHall(1000000);
    }
 
    public static void montyHall(int games)
    {
        int switchWins = 0;
        int stayWins = 0;
        Random rnd = new Random();
        for (int i = 0; i < games; i++)
        {
            int[] doors = new int[3]; // all zero (goats) by default
            doors[rnd.Next(3)] = 1; // put car in a random door
            int choice = rnd.Next(3); // choose a door at random
            int shown;
            do
            {
                shown = rnd.Next(3); // the shown door
            }
            while (doors[shown] == 1 || shown == choice);
            stayWins += doors[choice];
            switchWins += doors[3 - choice - shown];
        }
        Console.WriteLine("Simulating " + games + " games:");
        Console.WriteLine("Staying   wins " + stayWins + " times");
        Console.WriteLine("Switching wins " + switchWins + " times");
    }
}

