        private static void ProcessString(string input)
        {
            var charMap = new Dictionary<char, int?>();
            char dup = '\0';
            int index = 0;
            int pos1 = -1;
            int pos2 = -1;
            foreach (var key in input)
            {
                index++;
                if (charMap.ContainsKey(key))
                {
                    dup = key;
                    pos1 = charMap[key].Value;
                    pos2 = index;
                    break;
                }
                charMap[key] = index;
            }
            var unique = dup == '\0'? "yes" : "no";
            var diff = dup == '\0'? "" : $"'{dup}'";
            var hex = dup == '\0'? "" : $"{Convert.ToInt32(dup):X}";
            var position = dup == '\0'? "" : $"{pos1} {pos2}";
            Console.WriteLine("{0,-40}  {1,6}  {2,10}  {3,8}  {4}  {5}", input, input.Length, unique, diff, hex, position);
        }
    }
}

