using System;
using System.Threading;
 
namespace Semaphore
{
	class MainClass
	{
		static Semaphore sem = new Semaphore(3, 3);
		static int count = 3;
		static int getcount() { return count; }
		static void acquire()
		{
			sem.WaitOne();
			count--;
		}
		static void release()
		{
			count++;
			sem.Release();
		}
		static void work(object id)
		{
			int i = 10;
			while (i-- > 0) {
				acquire();
				Console.WriteLine("#" + id + " acquired sema at " + getcount());
				Thread.Sleep(new Random().Next(4000));
				release();
				Thread.Sleep(0);
			}
		}
		public static void Main(string[] args)
		{
			Thread[] th = new Thread[4];
			int[] ids = { 1, 2, 3, 4 };
			for (int i = 4; i-- > 0;) th[i] = new Thread(new ParameterizedThreadStart(work));
			for (int i = 4; i-- > 0;) th[i].Start(ids[i]);
			for (int i = 4; i-- > 0;) th[i].Join();
			Console.WriteLine("all workers done");
		}
	}
}

