namespace AngleUnit
{
    public interface IAngleUnit
    {
        double TURN { get; }
        string NAME { get; }
    }
 
    public class Degrees : IAngleUnit
    {
        public double TURN { get { return 360.0; } }
        public string NAME { get { return "Degrees"; } }
    }
 
    public class Radians : IAngleUnit
    {
        public double TURN { get { return Math.PI * 2.0; } }
        public string NAME { get { return "Radians"; } }
    }
 
    public class Gradians : IAngleUnit
    {
        public double TURN { get { return 400.0; } }
        public string NAME { get { return "Gradians"; } }
    }
 
    public class Mils : IAngleUnit
    {
        public double TURN { get { return 6400.0; } }
        public string NAME { get { return "Mils"; } }
    }
 
    public class Angle<T> where T : IAngleUnit, new()
    {
        private double _val;
        private T _unit;
 
        public Angle(double val)
        {
            _val = val;
            _unit = new T();
        }
 
        public Angle<T> Normalize()
        {
            return new Angle<T>(_val % _unit.TURN);
        }
 
        public double Val()
        {
            return _val;
        }
 
        public Angle<U> Convert<U>() where U : IAngleUnit, new()
        {
            return new Angle<U>(_val * new U().TURN / _unit.TURN);
        }
 
        public string Name()
        {
            return _unit.NAME;
        }
    }
 
    class Program
    {
        static void PrintAngles<T>() where T : IAngleUnit, new()
        {
            double[] angles = { -2.0, -1.0, 0.0, 1.0, 2.0, 6.2831853, 16.0, 57.2957795, 359.0, 399.0, 6399.0, 1000000.0 };
            Console.WriteLine("{0,12} {1,12} {2,12} {3,12} {4,12} {5,12}", "Angle", "Unit", "Degrees", "Gradians", "Mils", "Radians");
 
            foreach (double angle in angles)
            {
                Angle<T> deg = new Angle<T>(angle).Normalize();
                Console.WriteLine("{0,12} {1,12} {2,12:F4} {3,12:F4} {4,12:F4} {5,12:F4}",
                    angle,
                    deg.Name(),
                    deg.Convert<Degrees>().Val(),
                    deg.Convert<Gradians>().Val(),
                    deg.Convert<Mils>().Val(),
                    deg.Convert<Radians>().Val()
                );
            }
 
            Console.WriteLine();
        }
 
        static void Main(string[] args)
        {
            PrintAngles<Degrees>();
            PrintAngles<Gradians>();
            PrintAngles<Mils>();
            PrintAngles<Radians>();
        }
    }
}

