using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.IO;
 
namespace Anagrams
{
    class Program
    {
        static void Main(string[] args)
        {
            var wordList = File.ReadAllText("unixdict.txt").Split(new char[] {'' });
            var anagrams = FindAnagrams(wordList);
            var derangedAnagrams = FindDerangedAnagrams(anagrams);
            var longestPair = FindLongestDerangedPair(derangedAnagrams);
            Console.WriteLine(string.Join(" ", longestPair));
        }
 
        static string[] FindLongestDerangedPair(List<string[]> derangedAnagrams)
        {
            var longestLen = derangedAnagrams[0][0].Length;
            var longestPair = derangedAnagrams[0];
            foreach (var danas in derangedAnagrams)
            {
                if (danas[0].Length > longestLen)
                {
                    longestLen = danas[0].Length;
                    longestPair = danas;
                }
            }
            return longestPair;
        }
 
        static List<string[]> FindDerangedAnagrams(Dictionary<string, List<string>> anagrams)
        {
            var deranged = new List<string[]>();
 
            bool IsDeranged(string w1, string w2)
            {
                for (var c = 0; c < w1.Length; c++)
                {
                    if (w1[c] == w2[c])
                    {
                        return false;
                    }
                }
                return true;
            }
 
            void FindDeranged(List<string> anas)
            {
                for (var a = 0; a < anas.Count; a++)
                {
                    for (var b = a + 1; b < anas.Count; b++)
                    {
                        if (IsDeranged(anas[a], anas[b]))
                        {
                            deranged.Add(new string[] { anas[a], anas[b] });
                        }
                    }
                }
            }
 
            foreach (var ana in anagrams)
            {
                var anas = ana.Value;
                FindDeranged(anas);
            }
 
            return deranged;
        }
 
        static Dictionary<string, List<string>> FindAnagrams(string[] wordList)
        {
            var anagrams = new Dictionary<string, List<string>>();
 
            foreach (var word in wordList)
            {
                var key = string.Concat(word.OrderBy(c => c));
                if (!anagrams.ContainsKey(key))
                {
                    anagrams[key] = new List<string>();
                }
                anagrams[key].Add(word);
            }
 
            foreach (var a in anagrams.Keys.ToList())
            {
                if (anagrams[a].Count < 2)
                {
                    anagrams.Remove(a);
                }
            }
 
            return anagrams;
        }
    }
}

