code:
// version 1.0.6
 
using System;
 
public class DigitalRoot {
    public static int SumDigits(long n) {
        if (n < 0L) throw new ArgumentException("Negative numbers not allowed");
        int sum = 0;
        long nn = n;
        while (nn > 0L) {
            sum += (int)(nn % 10);
            nn /= 10;
        }
        return sum;
    }
 
    public static (int, int) DigitalRoot(long n) {
        if (n < 0L) throw new ArgumentException("Negative numbers not allowed");
        if (n < 10L) return (Convert.ToInt32(n), 0);
        long dr = n;
        int ap = 0;
        while (dr > 9L) {
            dr = SumDigits(dr);
            ap++;
        }
        return (Convert.ToInt32(dr), ap);
    }
 
    public static void Main(string[] args) {
        long[] a = {1, 14, 267, 8128, 627615, 39390, 588225, 393900588225};
        foreach (long n in a) {
            var (dr, ap) = DigitalRoot(n);
            Console.WriteLine($"{n.ToString().PadRight(12)} has additive persistence {ap} and digital root of {dr}");
        }
    }
}

