using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Church
{
    public delegate Func<Func<T, T>, Func<T, T>> ChurchNum<T>(Func<T, T> f);

    class Program
    {
        public static ChurchNum<T> zero<T>()
        {
            return f => x => x;
        }

        public static ChurchNum<T> next<T>(ChurchNum<T> n)
        {
            return f => x => f(n(f)(x));
        }

        public static ChurchNum<T> plus<T>(ChurchNum<T> a)
        {
            return b => f => x => b(f)(a(f)(x));
        }

        public static ChurchNum<T> pow<T>(ChurchNum<T> m)
        {
            return n => m(n);
        }

        public static ChurchNum<T> mult<T>(ChurchNum<T> a)
        {
            return b => f => x => b(a(f))(x);
        }

        public static ChurchNum<T> toChurchNum<T>(int n)
        {
            if (n <= 0)
            {
                return zero<T>();
            }
            return next<T>(toChurchNum<T>(n - 1));
        }

        public static int toInt<T>(ChurchNum<T> c)
        {
            int counter = 0;
            ChurchNum<T> funCounter = f =>
            {
                counter++;
                return f;
            };

            plus<T>(zero<T>())(c)(funCounter)(x => x);

            return counter;
        }

        static void Main(string[] args)
        {
            ChurchNum<int> zero = zero<int>();
            ChurchNum<int> three = next<int>(next<int>(next<int>(zero)));
            ChurchNum<int> four = next<int>(next<int>(next<int>(next<int>(zero))));

            Console.WriteLine("3+4=" + toInt<int>(plus<int>(three)(four))); // prints 7
            Console.WriteLine("4+3=" + toInt<int>(plus<int>(four)(three))); // prints 7

            Console.WriteLine("3*4=" + toInt<int>(mult<int>(three)(four))); // prints 12
            Console.WriteLine("4*3=" + toInt<int>(mult<int>(four)(three))); // prints 12

            // exponentiation.  note the reversed order!
            Console.WriteLine("3^4=" + toInt<int>(pow<int>(four)(three))); // prints 81
            Console.WriteLine("4^3=" + toInt<int>(pow<int>(three)(four))); // prints 64

            Console.WriteLine("  8=" + toInt<int>(toChurchNum<int>(8))); // prints 8
        }
    }
}

