using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;
 
namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            // Look up the address to bind to
            IPAddress ipAddress = Dns.GetHostEntry("localhost").AddressList[0];
            IPEndPoint localEndPoint = new IPEndPoint(ipAddress, 12321);
 
            // Make a socket
            Socket listener = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
 
            // Associate the socket with its address
            listener.Bind(localEndPoint);
 
            // State that we've opened a server socket and are listening for connections
            listener.Listen(20);
 
            // Serve the listening socket until killed
            while (true)
            {
                // Block until we take one connection to the server socket
                Socket handler = listener.Accept();
 
                // If it was a successful connection, spawn a worker process to service it
                Task.Factory.StartNew(() =>
                {
                    echo_lines(handler);
                });
            }
        }
 
        static void echo_lines(Socket handler)
        {
            byte[] bytes = new byte[256];
            int bytesRec = handler.Receive(bytes);
 
            while (bytesRec > 0)
            {
                handler.Send(bytes, bytesRec, 0);
                bytesRec = handler.Receive(bytes);
            }
 
            handler.Shutdown(SocketShutdown.Both);
            handler.Close();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Numerics;
 
namespace Entropy
{
    class Program
    {
        static void Main(string[] args)
        {
            var fibWords = FibonacciWordGen();
            Console.WriteLine("{0,3} {1,9} {2,18} {3}", "N", "Length", "Entropy", "Word");
            int n = 1;
            for (; n < 10; n++)
            {
                var s = fibWords.Next();
                // Just to show the function and generator do the same thing:
                if (s!= FibonacciWord(n))
                {
                    Console.WriteLine("For {0}, generator produced {1}, function produced {2}", n, s, FibonacciWord(n));
                }
                Console.WriteLine("{0,3} {1,9} {2,18} {3}", n, s.Length, Entropy(s), s);
            }
            for (; n <= 37; n++)
            {
                var s = fibWords.Next();
                Console.WriteLine("{0,3} {1,9} {2,18}", n, s.Length, Entropy(s));
            }
        }
 
        static double Entropy(string s)
        {
            var m = new Dictionary<char, double>();
            foreach (var r in s)
            {
                if (m.ContainsKey(r))
                {
                    m[r]++;
                }
                else
                {
                    m[r] = 1;
                }
            }
            double hm = 0;
            foreach (var c in m)
            {
                hm += c.Value * Math.Log(c.Value, 2);
            }
            var l = (double)s.Length;
            return Math.Log(l, 2) - hm / l;
        }
 
        const string F_Word1 = "1";
        const string F_Word2 = "0";
 
        static string FibonacciWord(int n)
        {
            var a = F_Word1;
            var b = F_Word2;
            for (; n > 1; n--)
            {
                a = b;
                b = b + a;
            }
            return a;
        }
 
        static FibonacciWordGen FibonacciWordGen()
        {
            return new FibonacciWordGen();
        }
 
        class FibonacciWordGen
        {
            string a = F_Word1;
            string b = F_Word2;
 
            public string Next()
            {
                var s = a;
                a = b;
                b = b + a;
                return s;
            }
        }
    }
}

