namespace CIDR
{
    class Program
    {
        static void Main(string[] args)
        {
            if (args.Length == 0)
            {
                args = Console.In.ReadToEnd().Split(new string[] { "\r\n" }, StringSplitOptions.RemoveEmptyEntries);
            }

            foreach (var cidr in args)
            {
                var dotted = cidr.Split('/')[0];
                var size = int.Parse(cidr.Split('/')[1]);
                var binary = dotted.Split('.').Select(o => Convert.ToString(int.Parse(o), 2).PadLeft(8, '0')).Aggregate((a, b) => a + b);
                binary = binary.Substring(0, size) + "0".PadLeft(32 - size, '0');
                var canon = binary.Select((c, i) => new { c, i }).GroupBy(x => x.i / 8).Select(x => Convert.ToInt32(new string(x.Select(y => y.c).ToArray()), 2)).Aggregate((a, b) => a + "." + b);
                Console.WriteLine(canon + "/" + size);
            }
        }
    }
}

