public static class IntegerExtensions
{
    public static bool IsSmith(this int n)
    {
        if (n.IsPrime()) return false;
        return n.Digits().Sum() == n.PrimeDivision().Select(x => x.Key.Digits().Sum() * x.Value).Sum();
    }
 
    public static bool IsPrime(this int n)
    {
        if (n < 2) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        for (int i = 3; i <= Math.Sqrt(n); i += 2)
            if (n % i == 0) return false;
        return true;
    }
 
    public static IEnumerable<int> Digits(this int n)
    {
        while (n > 0)
        {
            yield return n % 10;
            n /= 10;
        }
    }
 
    public static Dictionary<int, int> PrimeDivision(this int n)
    {
        var res = new Dictionary<int, int>();
        for (int i = 2; i <= n; i++)
        {
            if (n % i == 0)
            {
                res[i] = 0;
                while (n % i == 0)
                {
                    res[i]++;
                    n /= i;
                }
            }
        }
        return res;
    }
}

