        {
            return string.Format("{0} {1} {2} {3}", id, name, salary, department);
        }
    }
 
    class Program
    {
        static void Main(string[] args)
        {
            int N = args.Length > 0? int.Parse(args[0]) : 3;
 
            var records = new SortedDictionary<string, List<Employee>>();
            using (var sc = new StreamReader("data.txt"))
            {
                while (!sc.EndOfStream)
                {
                    var rec = sc.ReadLine().Trim().Split(", ");
 
                    List<Employee> lst;
