namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] ary = { 6, 7, 8, 9, 2, 5, 3, 4, 1 };
            Console.WriteLine("before sort: {0}", string.Join(", ", ary));
            Console.WriteLine(" after sort: {0}", string.Join(", ", CircleSort(ary)));
            Console.ReadLine();
        }
 
        static int[] CircleSort(int[] ary)
        {
            int lo = 0;
            int hi = ary.Length - 1;
            int swaps = 0;
            while (CircleSort(ary, lo, hi, ref swaps) > 0) ;
            return ary;
        }
 
        static int CircleSort(int[] ary, int lo, int hi, ref int swaps)
        {
            if (lo == hi) return swaps;
            int low = lo;
            int high = hi;
            int mid = (lo + hi) / 2;
            while (lo < hi)
            {
                if (ary[lo] > ary[hi])
                {
                    int temp = ary[lo];
                    ary[lo] = ary[hi];
                    ary[hi] = temp;
                    swaps++;
                }
                lo++;
                hi--;
            }
            if (lo == hi && ary[lo] > ary[hi + 1])
            {
                int temp = ary[lo];
                ary[lo] = ary[hi + 1];
                ary[hi + 1] = temp;
                swaps++;
            }
            swaps += CircleSort(ary, low, mid, ref swaps);
            swaps += CircleSort(ary, mid + 1, high, ref swaps);
            return swaps;
        }
    }
}

