namespace SuperNumbers
{
    class Program
    {
        static void Main(string[] args)
        {
            var rd = new List<string> { "22", "333", "4444", "55555", "666666", "7777777", "88888888", "999999999" };
 
            for (uint ii = 2; ii < 5; ii++)
            {
                Console.WriteLine("First 10 super-{0} numbers:", ii);
                int count = 0;
 
                for (uint j = 3; ; j++)
                {
                    var k = ii * ipow(j, ii);
                    var kstr = k.ToString();
                    var needle = rd[(int)(ii - 2)];
                    var res = kstr.IndexOf(needle);
                    if (res!= -1)
                    {
                        count++;
                        Console.Write("{0} ", j);
                        if (count == 10)
                        {
                            Console.WriteLine("\n\n");
                            break;
                        }
                    }
                }
            }
 
            Console.ReadLine();
        }
 
        static uint ipow(uint baseNum, uint exp)
        {
            uint result = 1;
            while (exp!= 0)
            {
                if ((exp & 1) == 1)
                {
                    result *= baseNum;
                }
                exp >>= 1;
                baseNum *= baseNum;
            }
            return result;
        }
    }
}

