namespace CSV
{
    class CSV
    {
        private Dictionary<Point, string> _map = new Dictionary<Point, string>();
        private int _cols;
        private int _rows;

        public void open(File file)
        {
            open(file, ',');
        }

        public void open(File file, char delimiter)
        {
            StreamReader scanner = new StreamReader(file);
            scanner.useDelimiter(Character.toString(delimiter));

            clear();

            while (scanner.hasNextLine())
            {
                string[] values = scanner.nextLine().split(Character.toString(delimiter));

                int col = 0;
                foreach (string value in values)
                {
                    _map.put(new Point(col, _rows), value);
                    _cols = Math.max(_cols, ++col);
                }
                _rows++;
            }
            scanner.close();
        }

        public void save(File file)
        {
            save(file, ',');
        }

        public void save(File file, char delimiter)
        {
            FileWriter fw = new FileWriter(file);
            BufferedWriter bw = new BufferedWriter(fw);

            for (int row = 0; row < _rows; row++)
            {
                for (int col = 0; col < _cols; col++)
                {
                    Point key = new Point(col, row);
                    if (_map.containsKey(key))
                    {
                        bw.write(_map.get(key));
                    }

                    if ((col + 1) < _cols)
                    {
                        bw.write(delimiter);
                    }
                }
                bw.newLine();
            }
            bw.flush();
            bw.close();
        }

        public string get(int col, int row)
        {
            string val = "";
            Point key = new Point(col, row);
            if (_map.containsKey(key))
            {
                val = _map.get(key);
            }
            return val;
        }

        public void put(int col, int row, string value)
        {
            _map.put(new Point(col, row), value);
            _cols = Math.max(_cols, col + 1);
            _rows = Math.max(_rows, row + 1);
        }

        public void clear()
        {
            _map.clear();
            _cols = 0;
            _rows = 0;
        }

        public int rows()
        {
            return _rows;
        }

        public int cols()
        {
            return _cols;
        }

        public static void main(string[] args)
        {
            try
            {
                CSV csv = new CSV();

                csv.open(new File("test_in.csv"));
                csv.put(0, 0, "Column0");
                csv.put(1, 1, "100");
                csv.put(2, 2, "200");
                csv.put(3, 3, "300");
                csv.put(4, 4, "400");
                csv.save(new File("test_out.csv"));
            }
            catch (Exception e)
            {
            }
        }
    }
}

using System;
 
public class Program
{
    public static string Commatize(ulong n)
    {
        var s = n.ToString();
        var le = s.Length;
        for (var i = le - 3; i >= 1; i -= 3)
        {
            s = s.Substring(0, i) + "," + s.Substring(i);
        }
        return s;
    }
 
    public static void Main()
    {
        var starts = new ulong[] {100, 1000000, 10000000, 1000000000, 7123};
        var counts = new int[] {30, 15, 15, 10, 25};
        for (var i = 0; i < starts.Length; i++)
        {
            var count = 0;
            var j = starts[i];
            var pow = 100UL;
            while (j < pow*10)
            {
                pow *= 10;
            }
            Console.WriteLine("First {0} gapful numbers starting at {1}:", counts[i], Commatize(starts[i]));
            while (count < counts[i])
            {
                var fl = (j/pow)*10 + (j % 10);
                if (j%fl == 0)
                {
                    Console.Write("{0} ", j);
                    count++;
                }
                j++;
                if (j >= 10*pow)
                {
                    pow *= 10;
                }
            }
            Console.WriteLine();
        }
    }
}

