namespace ProjectEulerQuestions
{
    internal class Question135
    {
        private static void Main(string[] args)
        {
            string text = File.ReadAllText(@"C:\Project Euler\Project Euler100\p0135_words.txt").ToLower();
            Regex reg = new Regex(@"\p{Ll}+");
            MatchCollection matches = reg.Matches(text);
            Dictionary<string, int> groups = new Dictionary<string, int>();
            foreach (Match match in matches)
            {
                if (groups.ContainsKey(match.Value))
                {
                    groups[match.Value]++;
                }
                else
                {
                    groups.Add(match.Value, 1);
                }
            }
            var keyvals = groups.Select(x => new { x.Key, x.Value }).OrderByDescending(x => x.Value).Take(10).ToList();
            Console.WriteLine("Rank  Word  Frequency");
            Console.WriteLine("====  ====  =========");
            for (int rank = 1; rank <= 10; rank++)
            {
                string word = keyvals[rank - 1].Key;
                int freq = keyvals[rank - 1].Value;
                Console.WriteLine("{0,2}    {1,-4}    {2,5}", rank, word, freq);
            }
        }
    }
}

