namespace ConsoleApplication1
{
    class Program
    {
        static bool is_palindrome(string str)
        {
            int n = str.Length;
            for (int i = 0; i + 1 < n; ++i, --n)
            {
                if (str[i]!= str[n - 1])
                    return false;
            }
            return true;
        }

        static void Main(string[] args)
        {
            DateTime timestamp = DateTime.Now;
            int seconds_per_day = 24 * 60 * 60;
            int count = 15;
            string str;
            Console.WriteLine("Next {0} palindrome dates:", count);
            for (; count > 0; timestamp += TimeSpan.FromSeconds(seconds_per_day))
            {
                str = timestamp.ToString("yyyyMMdd");
                if (is_palindrome(str))
                {
                    str = timestamp.ToString("yyyy-MM-dd");
                    Console.WriteLine(str);
                    --count;
                }
            }
        }
    }
}

