            Console.WriteLine("The mean angle of {0} is: {1} degrees", string.Join(", ", angles), mean_angle(angles));
            angles = new double[] { 10, 20, 30 };
            Console.WriteLine("The mean angle of {0} is: {1} degrees", string.Join(", ", angles), mean_angle(angles));
        }
 
        static double deg2rad(double d)
        {
            return d * Math.PI / 180;
        }
 
        static double rad2deg(double r)
        {
            return r * 180 / Math.PI;
        }
 
        static double mean_angle(double[] deg)
        {
            return rad2deg(deg.Aggregate(0.0, (z, d) => z + Complex.FromPolarCoordinates(1, deg2rad(d))) / deg.Length).Arg;
        }
    }
}

public static string Lcs(string a, string b)
{
    var aSub = a.Substring(0, a.Length - 1);
    var bSub = b.Substring(0, b.Length - 1);

    if (a.Length == 0 || b.Length == 0)
    {
        return string.Empty;
    }
    else if (a[a.Length - 1] == b[b.Length - 1])
    {
        return Lcs(aSub, bSub) + a[a.Length - 1];
    }
    else
    {
        var x = Lcs(a, bSub);
        var y = Lcs(aSub, b);
        return x.Length > y.Length? x : y;
    }
}

