namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            // string creation
            string x = "hello world";

            // reassign string (no garbage collection)
            x = "";

            // string assignment with a null byte
            x = "ab\0";
            Console.WriteLine(x);
            Console.WriteLine(x.Length);

            // string comparison
            if (x == "hello")
            {
                Console.WriteLine("equal");
            }
            else
            {
                Console.WriteLine("not equal");
            }
            if (x < "bc")
            {
                Console.WriteLine("x is lexigraphically less than 'bc'");
            }

            // string cloning
            var y = x;
            Console.WriteLine(x == y);
            Console.WriteLine(ReferenceEquals(x, y));

            // check if empty
            string empty = "";
            if (empty.Length == 0)
            {
                Console.WriteLine("String is empty");
            }

            // append a byte
            x = "helloworld";
            x += (char)83;
            Console.WriteLine(x);

            // substring
            var slice = x.Substring(5, 5);
            Console.WriteLine(slice);

            // replace bytes
            var greeting = replaceFirst(x, "worldS", "");
            Console.WriteLine(greeting);

            // join strings
            var join = greeting +'' + slice;
            Console.WriteLine(join);

            Console.ReadKey();
        }

        static string replaceFirst(string s, string target, string replace)
        {
            var pos = s.IndexOf(target);
            if (pos == -1) return s;
            return s.Substring(0, pos) + replace + s.Substring(pos + target.Length);
        }
    }
}

