private static string GetCode(char c)
{
    switch (c)
    {
        case 'B':
        case 'F':
        case 'P':
        case 'V':
            return "1";
        case 'C':
        case 'G':
        case 'J':
        case 'K':
        case 'Q':
        case 'S':
        case 'X':
        case 'Z':
            return "2";
        case 'D':
        case 'T':
            return "3";
        case 'L':
            return "4";
        case 'M':
        case 'N':
            return "5";
        case 'R':
            return "6";
        default:
            return "";
    }
}

public static string Soundex(string s)
{
    string code, previous, soundex;
    code = s.ToUpper().Substring(0, 1) + "";

    // EDITED : previous = "7";
    previous = GetCode(s.ToUpper().Substring(0, 1));

    for (int i = 1; i < s.Length; i++)
    {
        string current = GetCode(s.ToUpper().Substring(i, 1));
        if (current.Length > 0 &&!current.Equals(previous))
        {
            code = code + current;
        }
        previous = current;
    }
    soundex = (code + "0000").Substring(0, 4);
    return soundex;
}

