using System;
using System.Text;
 
class LinkedList<E> {
    class Node<E>(E data, Node<E> prev = null, Node<E> next = null) {
        public E data;
        public Node<E> prev;
        public Node<E> next;
 
        public Node(E data, Node<E> prev = null, Node<E> next = null) {
            this.data = data;
            this.prev = prev;
            this.next = next;
        }
 
        public override string ToString() {
            var sb = new StringBuilder(this.data.ToString());
            var node = this.next;
            while (node!= null) {
                sb.Append(" -> ", node.data.ToString());
                node = node.next;
            }
            return sb.ToString();
        }
    }
 
    public Node<E> first;
    public Node<E> last;
 
    public void addFirst(E value) {
        if (first == null) {
            first = new Node<E>(value);
            last = first;
        }
        else {
            var node = first;
            first = new Node<E>(value, null, node);
            node.prev = first;
        }
    }
 
    public void addLast(E value) {
        if (last == null) {
            last = new Node<E>(value);
            first = last;
        }
        else {
            var node = last;
            last = new Node<E>(value, node, null);
            node.next = last;
        }
    }
 
    public void insert(Node<E> after, E value) {
        if (after == null)
            addFirst(value);
        else if (after == last)
            addLast(value);
        else {
            var next = after.next;
            var new = new Node<E>(value, after, next);
            after.next = new;
            if (next!= null) next.prev = new;
        }
    }
 
    public override string ToString() {
        return first.ToString();
    }
 
    public string firstToLast() {
        return first?.ToString()?? "";
    }
 
    public string lastToFirst() {
        if (last == null) return "";
        var sb = new StringBuilder(last.ToString());
        var node = last.prev;
        while (node!= null) {
            sb.Append(" -> ", node.data.ToString());
            node = node.prev;
        }
        return sb.ToString();
    }
}
 
class Program {
    static void Main(string[] args) {
        var ll = new LinkedList<int>();
        ll.addFirst(1);
