        Console.WriteLine("Last to first : {0}", ll.lastToFirst());
    }
}

using System;
using System.Collections.Generic;
 
namespace Rextester
{
    public class Program
    {
        public static List<bool> prime_sieve(ulong limit)
        {
            List<bool> sieve = new List<bool>();
            for (ulong i = 0; i < limit; i++)
            {
                sieve.Add(true);
            }
            if (limit > 0)
                sieve[0] = false;
            if (limit > 1)
                sieve[1] = false;
            for (ulong i = 4; i < limit; i += 2)
                sieve[(int)i] = false;
            for (ulong p = 3; ; p += 2)
            {
                ulong q = p * p;
                if (q >= limit)
                    break;
                if (sieve[(int)p])
                {
                    ulong inc = 2 * p;
                    for (; q < limit; q += inc)
                        sieve[(int)q] = false;
                }
            }
            return sieve;
        }
 
        public static ulong modpow(ulong base1, ulong exp, ulong mod)
        {
            if (mod == 1)
                return 0;
            ulong result = 1;
            base1 %= mod;
            for (; exp > 0; exp >>= 1)
            {
                if ((exp & 1) == 1)
                    result = (result * base1) % mod;
                base1 = (base1 * base1) % mod;
            }
            return result;
        }
 
        public static List<ulong> wieferich_primes(ulong limit)
        {
            List<ulong> result = new List<ulong>();
            List<bool> sieve = prime_sieve(limit);
            for (ulong p = 2; p < limit; ++p)
                if (sieve[(int)p] && modpow(2, p - 1, p * p) == 1)
                    result.Add(p);
            return result;
        }
 
        public static void Main(string[] args)
        {
            ulong limit = 5000;
            Console.WriteLine("Wieferich primes less than " + limit + ":");
            foreach (ulong p in wieferich_primes(limit))
                Console.WriteLine(p);
        }
    }
}

