namespace R2CF
{
    class Program
    {
        static IEnumerable<int> r2cf(Tuple<int, int> frac)
        {
            int num = frac.Item1;
            int den = frac.Item2;
            while (Math.Abs(den)!= 0)
            {
                int div = num / den;
                int rem = num % den;
                num = den;
                den = rem;
                yield return div;
            }
        }
 
        static void iterate(IEnumerable<int> seq)
        {
            foreach (int i in seq)
                Console.Write("{0} ", i);
            Console.WriteLine();
        }
 
        static void Main(string[] args)
        {
            Tuple<int, int>[] fracs = new Tuple<int, int>[] {
                new Tuple<int, int>(1, 2),
                new Tuple<int, int>(3, 1),
                new Tuple<int, int>(23, 8),
                new Tuple<int, int>(13, 11),
                new Tuple<int, int>(22, 7),
                new Tuple<int, int>(-151, 77)
            };
            foreach (Tuple<int, int> frac in fracs)
            {
                Console.Write("{0,4} / {1,2} = ", frac.Item1, frac.Item2);
                iterate(r2cf(frac));
            }
            Tuple<int, int>[] root2 = new Tuple<int, int>[] {
                new Tuple<int, int>(14142, 10000),
                new Tuple<int, int>(141421, 100000),
                new Tuple<int, int>(1414214, 1000000),
                new Tuple<int, int>(14142136, 10000000)
            };
            Console.WriteLine("\nSqrt(2) ->");
            foreach (Tuple<int, int> frac in root2)
            {
                Console.Write("{0,8} / {1,8} = ", frac.Item1, frac.Item2);
                iterate(r2cf(frac));
            }
            Tuple<int, int>[] pi = new Tuple<int, int>[] {
                new Tuple<int, int>(31, 10),
                new Tuple<int, int>(314, 100),
                new Tuple<int, int>(3142, 1000),
                new Tuple<int, int>(31428, 10000),
                new Tuple<int, int>(314285, 100000),
                new Tuple<int, int>(3142857, 1000000),
                new Tuple<int, int>(31428571, 10000000),
                new Tuple<int, int>(314285714, 100000000)
            };
            Console.WriteLine("\nPi ->");
            foreach (Tuple<int, int> frac in pi)
            {
                Console.Write("{0,9} / {1,9} = ", frac.Item1, frac.Item2);
                iterate(r2cf(frac));
            }
        }
    }
}

