namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] files = new string[] { "temp1.dat", "temp2.dat", "temp3.dat" };
            foreach (string fname in files)
            {
                string data = File.ReadAllText(fname).Replace("\n", " ");
                Console.WriteLine(fname + ": " + data);
            }
            stream_merge(files);
        }
 
        static void stream_merge(string[] files)
        {
            List<Tuple<StreamReader, string>> fdata = new List<Tuple<StreamReader, string>>();
            foreach (string fname in files)
            {
                StreamReader io = new StreamReader(fname);
                fdata.Add(new Tuple<StreamReader, string>(io, io.ReadLine()));
            }
            merge(fdata);
        }
 
        static void merge(List<Tuple<StreamReader, string>> fdata)
        {
            while (fdata.Count > 0)
            {
                Tuple<StreamReader, string> min = fdata.Min(x => x.Item2);
                Console.WriteLine(min.Item2);
                StreamReader io = min.Item1;
                string next_data = io.ReadLine();
                if (next_data == null)
                {
                    io.Close();
                    fdata.Remove(min);
                }
                else
                {
                    int i = fdata.FindIndex(x => x.Item1 == io);
                    fdata[i] = new Tuple<StreamReader, string>(io, next_data);
                }
            }
        }
    }
}

