namespace Vampire_Numbers
{
    class Program
    {
        static void Main(string[] args)
        {
            int i = 0;
            int vamps = 0;
            while (vamps < 25)
            {
                i++;
                var vf = vampire_factors(i);
                if (vf.Count > 0)
                {
                    Console.WriteLine("{0}:\t{1}", i, string.Join(", ", vf));
                    vamps++;
                }
            }
            Console.WriteLine();
            foreach (var n in new int[] { 16758243290880, 24959017348650, 14593825548650 })
            {
                var vf = vampire_factors(n);
                if (vf.Count == 0)
                {
                    Console.WriteLine("{0} is not a vampire number!", n);
                }
                else
                {
                    Console.WriteLine("{0}:\t{1}", n, string.Join(", ", vf));
                }
            }
            Console.ReadLine();
        }
        static List<Tuple<int, int>> factor_pairs(int n)
        {
            int first = n / (int)Math.Pow(10, n.ToString().Length / 2) - 1;
            return Enumerable.Range(first, n).Select(i => new Tuple<int, int>(i, n / i)).Where(t => n % t.Item1 == 0).ToList();
        }
        static List<Tuple<int, int>> vampire_factors(int n)
        {
            if (n.ToString().Length % 2 == 1) return new List<Tuple<int, int>>();
            int half = n.ToString().Length / 2;
            return factor_pairs(n).Where(t => t.Item1.ToString().Length == half && t.Item2.ToString().Length == half && t.Item1 % 10!= 0 && t.Item2 % 10!= 0 && t.Item1.ToString().OrderBy(c => c).SequenceEqual(n.ToString().OrderBy(c => c)) && t.Item2.ToString().OrderBy(c => c).SequenceEqual(n.ToString().OrderBy(c => c))).ToList();
        }
    }
}

