var text = 
    "In olden times when wishing still helped one, there lived a king " +
    "whose daughters were all beautiful, but the youngest was so beautiful " +
    "that the sun itself, which has seen so much, was astonished whenever " +
    "it shone in her face.  Close by the king's castle lay a great dark " +
    "forest, and under an old lime tree in the forest was a well, and when " +
    "the day was very warm, the king's child went out into the forest and " +
    "sat down by the side of the cool fountain, and when she was bored she " +
    "took a golden ball, and threw it up on high and caught it, and this " +
    "ball was her favorite plaything.";
 
string greedyWordwrap(string text, int lineWidth)
{
    var words = text.Split(' ');
    var sb = new StringBuilder(words[0]);
    var spaceLeft = lineWidth - words[0].Length;
    foreach (var word in words.Skip(1))
    {
        var len = word.Length;
        if (len + 1 > spaceLeft)
        {
            sb.Append("\n").Append(word);
            spaceLeft = lineWidth - len;
        }
        else
        {
            sb.Append(" ").Append(word);
            spaceLeft -= (len + 1);
        }
    }
    return sb.ToString();
}
 
void Main(string[] args)
{
    Console.WriteLine("Greedy algorithm - wrapped at 72:");
    Console.WriteLine(greedyWordwrap(text, 72));
    Console.WriteLine("\nGreedy algorithm - wrapped at 80:");
    Console.WriteLine(greedyWordwrap(text, 80));
}

using System;
