namespace BullsAndCows
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = args.Length > 0? int.Parse(args[0]) : 4;
 
            char[] secret = new char[10];
            char[] answer = new char[10];
            Random rand = new Random();
 
            Console.WriteLine("--------+--------------------");
            Console.WriteLine("Secret  | {0}", GetDigits(n, secret));
            Console.WriteLine("--------+--------------------");
 
            Game(secret, answer);
        }
 
        static int irand(int n)
        {
            int r, rand_max = int.MaxValue - (int.MaxValue % n);
            do { r = new Random().Next(); } while (r >= rand_max);
            return r / (rand_max / n);
        }
 
        static char[] GetDigits(int n, char[] ret)
        {
            int i, j;
            char[] d = "123456789".ToCharArray();
 
            for (i = 0; i < n; i++)
            {
                j = irand(9 - i);
                ret[i] = d[i + j];
                if (j!= 0)
                {
                    d[i + j] = d[i];
                    d[i] = ret[i];
                }
            }
            return ret;
        }
 
        static int Score(char[] digits, char[] guess, out int cow)
        {
            int i, bits = 0, bull = 0;
 
            for (i = 0; guess[i]!= '\0'; i++)
            {
                if (guess[i]!= digits[i])
                {
                    bits |= (1 << (digits[i] - '1'));
                }
                else
                {
                    bull++;
                }
            }
 
            cow = 0;
            while (i-- > 0)
            {
                cow += ((bits & (1 << (guess[i] - '1')))!= 0)? 1 : 0;
            }
 
            return bull;
        }
 
        static void Pick(int n, int got, int marker, char[] buf)
        {
            int i, bits = 1;
            if (got >= n)
            {
                //strcpy(list + (n + 1) * len++, buf);
            }
            else
            {
                for (i = 0; i < 9; i++, bits *= 2)
                {
                    if ((marker & bits)!= 0)
                    {
                        continue;
                    }
                    buf[got] = (char)(i + '1');
                    Pick(n, got + 1, marker | bits, buf);
                }
            }
        }
 
        static void Filter(char[] buf, int n, int bull, int cow)
        {
            int i = 0, c;
            char[] ptr = new char[10];
 
            while (i < 10)
            {
                if (Score(ptr, buf, out c)!= bull || c!= cow)
                {
                    //strcpy(ptr, list + --len * (n + 1));
                }
                else
                {
                    //ptr += n + 1, i++;
                }
            }
        }
 
        static void Game(char[] tgt, char[] buf)
        {
            int i, p, bull, cow, n = tgt.Length;
 
            for (i = 0, p = 1; i < n && (p *= 9 - i); i++) ;
            //list = malloc(p * (n + 1));
 
            Pick(n, 0, 0, buf);
            for (p = 1, bull = 0; n - bull > 0; p++)
            {
                //strcpy(buf, list + (n + 1) * irand(len));
                bull = Score(tgt, buf, out cow);
 
                Console.WriteLine("Guess {0}| {1}    (from: {2})", p, buf, 10);
                Console.WriteLine("Score   | {0} bull, {1} cow", bull, cow);
                Console.WriteLine("--------+--------------------");
 
                Filter(buf, n, bull, cow);
            }
        }
    }
}

