        static char[] possibilities = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ".ToCharArray();
        static int C = 100; //number of spawn per generation
        static double minMutateRate = 0.09;
        static int perfectFitness = target.Length;
        private static string parent;
        static Random rand = new Random();

        private static int fitness(string trial)
        {
            int retVal = 0;
            for (int i = 0; i < trial.Length; i++)
            {
                if (trial[i] == target[i]) retVal++;
            }
            return retVal;
        }

        private static double newMutateRate()
        {
            return (((double)perfectFitness - fitness(parent)) / perfectFitness * (1 - minMutateRate));
        }

        private static string mutate(string parent, double rate)
        {
            string retVal = "";
            for (int i = 0; i < parent.Length; i++)
            {
                retVal += (rand.NextDouble() <= rate)?
                    possibilities[rand.Next(possibilities.Length)] :
                    parent[i];
            }
            return retVal;
        }

        static void Main(string[] args)
        {
            parent = mutate(target, 1);
            int iter = 0;
            while (!target.Equals(parent))
            {
                double rate = newMutateRate();
                iter++;
                if (iter % 100 == 0)
                {
                    Console.WriteLine(iter + ": " + parent + ", fitness: " + fitness(parent) + ", rate: " + rate);
                }
                string bestSpawn = null;
                int bestFit = 0;
                for (int i = 0; i < C; i++)
                {
                    string spawn = mutate(parent, rate);
                    int fitness = fitness(spawn);
                    if (fitness > bestFit)
                    {
                        bestSpawn = spawn;
                        bestFit = fitness;
                    }
                }
                parent = bestFit > fitness(parent)? bestSpawn : parent;
            }
            Console.WriteLine(parent + ", " + iter);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CubanPrimes
{
    class CubanPrimes
    {
        private static int MAX = 1_400_000;
        private static bool[] primes = new bool[MAX];

        static void Main(string[] args)
        {
            preCompute();
            cubanPrime(200, true);
            for (int i = 1; i <= 5; i++)
            {
                int max = (int)Math.Pow(10, i);
                Console.WriteLine("{0}-th cuban prime = {1}", max, cubanPrime(max, false));
            }
        }

        private static long cubanPrime(int n, bool display)
        {
            int count = 0;
            long result = 0;
            for (long i = 0; count < n; i++)
            {
                long test = 1l + 3 * i * (i + 1);
                if (isPrime(test))
                {
                    count++;
                    result = test;
                    if (display)
                    {
                        Console.Write("{0}{1}", String.Format("{0,10}", test), count % 10 == 0? "\n" : "");
                    }
                }
            }
            return result;
        }

        private static bool isPrime(long n)
        {
            if (n < MAX)
            {
                return primes[(int)n];
            }
            int max = (int)Math.Sqrt(n);
            for (int i = 3; i <= max; i++)
            {
                if (primes[i] && n % i == 0)
                {
                    return false;
                }
            }
            return true;
        }

        private static void preCompute()
        {
            //  primes
            for (int i = 2; i < MAX; i++)
            {
                primes[i] = true;
            }
            for (int i = 2; i < MAX; i++)
            {
                if (primes[i])
                {
                    for (int j = 2 * i; j < MAX; j += i)
                    {
                        primes[j] = false;
                    }
                }
            }
        }
    }
}

