using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace RPS
{
    class Program
    {
        public enum Item
        {
            ROCK, PAPER, SCISSORS, /*LIZARD, SPOCK*/
        }

        public static void Main(string[] args)
        {
            RPS rps = new RPS();
            rps.run();
        }

        public void run()
        {
            Console.Write("Make your choice: ");
            while (Console.ReadLine()!= null)
            {
                Item aiChoice = getAIChoice();
                string input = Console.ReadLine();
                Item choice;
                try
                {
                    choice = (Item)Enum.Parse(typeof(Item), input.ToUpper());
                }
                catch (ArgumentException ex)
                {
                    Console.WriteLine("Invalid choice");
                    continue;
                }
                counts.put(choice, counts.get(choice) + 1);
                totalThrows++;
                Console.WriteLine("Computer chose: " + aiChoice);
                if (aiChoice == choice)
                {
                    Console.WriteLine("Tie!");
                }
                else if (aiChoice.losesTo(choice))
                {
                    Console.WriteLine("You chose...wisely. You win!");
                }
                else
                {
                    Console.WriteLine("You chose...poorly. You lose!");
                }
                Console.Write("Make your choice: ");
            }
        }

        private static readonly Random rng = new Random();
        private Item getAIChoice()
        {
            int rand = rng.Next(totalThrows);
            foreach (Map.Entry<Item, int> entry in counts.entrySet())
            {
                Item item = entry.getKey();
                int count = entry.getValue();
                if (rand < count)
                {
                    List<Item> losesTo = item.losesToList;
                    return losesTo.get(rng.Next(losesTo.size()));
                }
                rand -= count;
            }
            return null;
        }

        //EnumMap uses a simple array under the hood
        public final Map<Item, int> counts = new EnumMap<Item, int>(Item.class)
        {
            for (Item item : Item.values())
                put(item, 1);
        };

        private int totalThrows = Item.values().length;
    }
}

using System;
 
class Program
{
    static int enc(int b)
    {
        return b ^ b >> 1;
    }
 
    static int dec(int g)
    {
        int b = 0;
        for (; g!= 0; g >>= 1)
        {
            b ^= g;
        }
        return b;
    }
 
    static void Main(string[] args)
    {
        Console.WriteLine("decimal  binary   gray    decoded");
        for (int b = 0; b < 32; b++)
        {
            int g = enc(b);
            int d = dec(g);
            Console.WriteLine("  {0,2}     {1,05}   {2,05}   {3,05}  {4,2}", b, Convert.ToString(b, 2), Convert.ToString(g, 2), Convert.ToString(d, 2), d);
        }
    }
}

