using System;
using System.Collections.Generic;
using System.Linq;
 
namespace Matrix
{
    public class Matrix
    {
        private readonly double[][] _matrix;
        private readonly int _rows;
        private readonly int _cols;
        public Matrix(int rows, int cols)
        {
            _rows = rows;
            _cols = cols;
            _matrix = new double[rows][];
            for (var i = 0; i < rows; i++)
            {
                _matrix[i] = new double[cols];
            }
        }
        public Matrix(double[][] matrix)
        {
            _rows = matrix.Length;
            _cols = matrix[0].Length;
            _matrix = new double[_rows][];
            for (var i = 0; i < _rows; i++)
            {
                _matrix[i] = new double[_cols];
                for (var j = 0; j < _cols; j++)
                {
                    _matrix[i][j] = matrix[i][j];
                }
            }
        }
        public double this[int row, int col]
        {
            get => _matrix[row][col];
            set => _matrix[row][col] = value;
        }
        public static Matrix operator *(Matrix m1, Matrix m2)
        {
            var rows1 = m1._rows;
            var cols1 = m1._cols;
            var rows2 = m2._rows;
            var cols2 = m2._cols;
            if (cols1!= rows2) throw new Exception("Matrix dimensions do not match");
            var result = new Matrix(rows1, cols2);
            for (var i = 0; i < rows1; i++)
            {
                for (var j = 0; j < cols2; j++)
                {
                    for (var k = 0; k < rows2; k++)
                    {
                        result[i, j] += m1[i, k] * m2[k, j];
                    }
                }
            }
            return result;
        }
        public static Matrix operator ^(Matrix m, int n)
        {
            if (n < 0 || m._rows!= m._cols) throw new Exception("Matrix dimensions do not match");
            if (n == 0) return IdentityMatrix(m._rows);
            if (n == 1) return m;
            var pow = IdentityMatrix(m._rows);
            var baseMatrix = m;
            var e = n;
            while (e > 0)
            {
                if ((e & 1) == 1) pow *= baseMatrix;
                e = e >> 1;
                baseMatrix *= baseMatrix;
            }
            return pow;
        }
        public static Matrix IdentityMatrix(int n)
        {
            if (n < 1) throw new Exception("Matrix dimensions do not match");
            var ident = new Matrix(n, n);
            for (var i = 0; i < n; i++) ident[i, i] = 1.0;
            return ident;
        }
        public void PrintMatrix(int n)
        {
            Console.WriteLine($"** Power of {n} **");
            for (var i = 0; i < _rows; i++)
            {
                Console.WriteLine(string.Join(" ", _matrix[i].Select(x => x.ToString("0.00"))));
            }
            Console.WriteLine();
        }
    }
    class Program
    {
        static void Main(string[] args)
        {
            var m = new Matrix(new double[][]
            {
                new double[] {3.0, 2.0},
                new double[] {2.0, 1.0}
            });
            for (var i = 0; i <= 10; i++) m.PrintMatrix(i);
        }
    }
}

