namespace HappyNumbers
{
    class Program
    {
        static void Main(string[] args)
        {
            int CACHE = 256;
            int h_unknown = 0;
            int h_yes = 1;
            int h_no = 2;
            int[] buf = new int[CACHE];
            buf[0] = h_unknown;
            buf[1] = h_yes;
            buf[2] = h_unknown;
            int happy(int n)
            {
                int sum = 0;
                int x;
                int nn;
                if (n < CACHE)
                {
                    if (buf[n]!= 0)
                    {
                        return 2 - buf[n];
                    }
                    buf[n] = h_no;
                }
                for (nn = n; nn!= 0; nn /= 10)
                {
                    x = nn % 10;
                    sum += x * x;
                }
                x = happy(sum);
                if (n < CACHE)
                {
                    buf[n] = 2 - x;
                }
                return x;
            }
            int i;
            int cnt = 8;
            for (i = 1; cnt!= 0 ||!Console.WriteLine("\n"); i++)
            {
                if (happy(i) == 1)
                {
                    cnt--;
                    Console.Write("{0} ", i);
                }
            }
            Console.WriteLine("The {0}th happy number: ", cnt = 1000000);
            for (i = 1; cnt!= 0; i++)
            {
                if (happy(i) == 1)
                {
                    cnt--;
                    Console.WriteLine("{0}", i);
                }
            }
            Console.ReadKey();
        }
    }
}

using System;
