namespace Palindrome
{
    class Program
    {
        static void Main(string[] args)
        {
            Debug.Assert(IsPalindrome("racecar"));
            Debug.Assert(IsPalindrome("alice"));
        }
 
        static bool IsPalindrome(string str)
        {
            int i = 0;
            int j = str.Length - 1;
 
            while (i < j)
            {
                if (str[i]!= str[j])
                {
                    return false;
                }
 
                i++;
                j--;
            }
 
            return true;
        }
    }
}

using System;
 
namespace DiceGame
{
    class Program
    {
        static void Main(string[] args)
        {
            var players = new[] {
                new { name = "", score = 0 },
                new { name = "", score = 0 }
            };
            var curPlayer = 1;
            var gameOver = false;
 
            players[0].name = Prompt("Your name, player #1:").ToUpper();
            players[1].name = Prompt("Your name, player #2:").ToUpper();
 
            while (!gameOver)
            {
                if (curPlayer == 0) curPlayer = 1; else curPlayer = 0;
                Round(players[curPlayer]);
                if (gameOver)
                    Console.WriteLine(
                        $"{players[curPlayer].name} wins ({players[curPlayer].score}).");
            }
        }
 
        static void Round(dynamic player)
        {
            var curSum = 0;
            var quit = false;
            var dice = 0;
            Console.WriteLine($"It's {player.name}'s turn ({player.score}).");
            while (!quit)
            {
                dice = Roll();
                if (dice == 1)
                {
                    Console.WriteLine("You roll a 1. What a pity!");
                    quit = true;
                }
                else
                {
                    curSum += dice;
                    quit =!Prompt(
                        $"You roll a {dice} (sum: {curSum}).\nRoll again?");
                    if (quit)
                    {
                        player.score += curSum;
                        if (player.score >= 100) gameOver = true;
                    }
                }
            }
        }
 
        static int Roll() => 1 + new Random().Next(6);
 
        static string Prompt(string message)
        {
            Console.Write(message);
            return Console.ReadLine();
        }
    }
}

using System;

public class MC
{
	public static void Main(string[] args)
	{
		Console.WriteLine(getPi(10000));
		Console.WriteLine(getPi(100000));
		Console.WriteLine(getPi(1000000));
		Console.WriteLine(getPi(10000000));
		Console.WriteLine(getPi(100000000));
	}

	public static double getPi(int numThrows)
	{
		int inCircle = 0;
		for (int i = 0; i < numThrows; i++)
		{
			//a square with a side of length 2 centered at 0 has 
			//x and y range of -1 to 1
			double randX = (Math.random() * 2) - 1;//range -1 to 1
			double randY = (Math.random() * 2) - 1;//range -1 to 1
			//distance from (0,0) = sqrt((x-0)^2+(y-0)^2)
			double dist = Math.sqrt(randX * randX + randY * randY);
			//^ or in Java 1.5+: double dist= Math.hypot(randX, randY);
			if (dist < 1)
			{//circle with diameter of 2 has radius of 1
				inCircle++;
			}
		}
		return 4.0 * inCircle / numThrows;
	}
}

