namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            Dictionary<string, double> probabilities = new Dictionary<string, double>();
            probabilities.Add("aleph", 1.0 / 5.0);
            probabilities.Add("beth", 1.0 / 6.0);
            probabilities.Add("gimel", 1.0 / 7.0);
            probabilities.Add("daleth", 1.0 / 8.0);
            probabilities.Add("he", 1.0 / 9.0);
            probabilities.Add("waw", 1.0 / 10.0);
            probabilities.Add("zayin", 1.0 / 11.0);
            probabilities.Add("heth", 1.0 - probabilities.Values.Sum());
            List<string> ordered_keys = probabilities.Keys.ToList();
            double sum = 0.0;
            Dictionary<string, double> sums = new Dictionary<string, double>();
            foreach (string key in ordered_keys)
            {
                sum += probabilities[key];
                sums.Add(key, sum);
            }
            Dictionary<string, int> actual = new Dictionary<string, int>();
            foreach (string key in ordered_keys)
            {
                actual.Add(key, 0);
            }
            int samples = 1000000;
            Random rand = new Random();
            for (int i = 0; i < samples; i++)
            {
                double r = rand.NextDouble();
                foreach (string k in ordered_keys)
                {
                    if (r < sums[k])
                    {
                        actual[k]++;
                        break;
                    }
                }
            }
            Console.WriteLine("key     expected    actual        diff");
            foreach (string k in ordered_keys)
            {
                double act = (double)actual[k] / samples;
                double val = probabilities[k];
                Console.WriteLine("{0,-8}{1,8:F8}  {2,8:F8}  {3,6:F3}%", k, val, act, 100 * (act - val) / val);
            }
            Console.ReadLine();
        }
    }
}

