namespace ProjectEuler
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = 2200;
            int[] r = new int[N + 1];
            for (int a = 1; a <= N; a++)
            {
                for (int b = a; b <= N; b++)
                {
                    int aabb;
                    if ((a & 1)!= 0 && (b & 1)!= 0) continue;
                    aabb = a * a + b * b;
                    for (int c = b; c <= N; c++)
                    {
                        int aabbcc = aabb + c * c;
                        int d = (int)Math.Sqrt((float)aabbcc);
                        if (aabbcc == d * d && d <= N) r[d] = 1;
                    }
                }
            }
            for (int a = 1; a <= N; a++)
                if (r[a] == 0) Console.Write(a + " ");
            Console.WriteLine();
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace ConsoleApplication1
{
    class Program
    {
        static List<int> primes = new List<int>() { 2, 3, 5, 7, 11, 13, 17 };
        static Dictionary<int, List<int>> cache = new Dictionary<int, List<int>>();
        static List<int> pfactor(int n)
        {
            if (n == 1)
                return new List<int>() { 1 };
            int n2 = n / 2 + 1;
            foreach (int p in primes)
            {
                if (p <= n2)
                {
                    int d = n / p;
                    int m = n % p;
                    if (m == 0)
                    {
                        if (d > 1)
                            return new List<int>() { p }.Concat(pfactor(d)).ToList();
                        else
                            return new List<int>() { p };
                    }
                }
                else
                {
                    if (n > primes.Last())
                        primes.Add(n);
                    return new List<int>() { n };
                }
            }
            return new List<int>() { n };
        }
        static void Main(string[] args)
        {
            int mx = 5000;
            for (int n = 1; n <= mx; n++)
            {
                List<int> factors = pfactor(n);
                if (n <= 10 || n >= mx - 20)
                    Console.WriteLine("{0,4} {1,5} {2}", n, factors!= new List<int>() { n } || n == 1? "" : "prime", string.Join("x", factors));
                if (n == 11)
                    Console.WriteLine("...");
            }
            Console.WriteLine("\nNumber of primes gathered up to {0} is {1}", mx, primes.Count);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace LongPrimes
{
    class Program
    {
        static void Main(string[] args)
        {
            long_primes(500, 8192000);
        }
 
        static void long_primes(long limit1, long limit2)
        {
            var sieve = new PrimeSieve(limit2);
            long count = 0;
            long limit = limit1;
            long prime = 3;
            while (prime < limit2)
            {
                if (is_long_prime(sieve, prime))
                {
                    if (prime < limit1)
                    {
                        Console.Write("{0} ", prime);
                    }
                    if (prime > limit)
                    {
                        Console.WriteLine("\nNumber of long primes up to {0}: {1}", limit, count);
                        limit *= 2;
                    }
                    count++;
                }
                prime += 2;
            }
            Console.WriteLine("\nNumber of long primes up to {0}: {1}", limit, count);
        }
 
        static bool is_long_prime(PrimeSieve sieve, long prime)
        {
            if (!sieve.is_prime(prime))
            {
                return false;
            }
            if (10 % prime == 0)
            {
                return false;
            }
            long n = prime - 1;
            long m = n;
            long p = 2;
            while (p * p <= n)
            {
                if (sieve.is_prime(p) && m % p == 0)
                {
                    if (modpow(10, n / p, prime) == 1)
                    {
                        return false;
                    }
                    while (m % p == 0)
                    {
                        m /= p;
                    }
                }
                p += 1;
            }
            if (m == 1)
            {
                return true;
            }
            return modpow(10, n / m, prime)!= 1;
        }
 
        static long modpow(long base, long exp, long n)
        {
            if (n == 1)
            {
                return 0;
            }
            long result = 1;
            base %= n;
            while (exp > 0)
            {
                if ((exp & 1) == 1)
                {
                    result = (result * base) % n;
                }
                base = (base * base) % n;
                exp >>= 1;
            }
            return result;
        }
    }
 
    class PrimeSieve
    {
        private BitArray _sieve;
 
        public PrimeSieve(long limit)
        {
            _sieve = new BitArray((int)limit + 1);
            _sieve.SetAll(true);
            _sieve[0] = false;
            _sieve[1] = false;
            for (long i = 2; i <= limit; i++)
            {
                if (_sieve[(int)i])
                {
                    for (long j = i * i; j <= limit; j += i)
                    {
                        _sieve[(int)j] = false;
                    }
                }
            }
        }
 
        public bool is_prime(long n)
        {
            return _sieve[(int)n];
        }
    }
}

