        static extern void _exit(int status);
 
        static void talk(string s)
        {
            int pid = fork();
            if (pid < 0)
            {
                perror("fork");
                Environment.Exit(1);
            }
            if (pid == 0)
            {
                execlp("espeak", "espeak", s, IntPtr.Zero);
                perror("espeak");
                _exit(1);
            }
            int status;
            waitpid(pid, out status, 0);
            if (status > 0) Console.WriteLine("Exit status was {0}", status);
        }
 
        static void Main(string[] args)
        {
            talk("This is an example of speech synthesis.");
        }
    }
}

