namespace CompoundTime
{
    class Program
    {
        static void Main(string[] args)
        {
            var ct = new CompoundTime(0, 3, 182, 345, 2412);
            Console.WriteLine("Before: {0}", ct);
            ct.Balance();
            Console.WriteLine("After: {0}", ct);
        }
    }
 
    class CompoundTime
    {
        public int W { get; set; }
        public int D { get; set; }
        public int H { get; set; }
        public int M { get; set; }
        public int S { get; set; }
 
        public CompoundTime(int w, int d, int h, int m, int s)
        {
            W = w;
            D = d;
            H = h;
            M = m;
            S = s;
        }
 
        public void Balance()
        {
            Reduce(S, M, 60);
            Reduce(M, H, 60);
            Reduce(H, D, 24);
            Reduce(D, W, 7);
        }
 
        private void Reduce(int from, int to, int factor)
        {
            to += from / factor;
            from %= factor;
        }
 
        public override string ToString()
        {
            return string.Format("{0}w {1}d {2}h {3}m {4}s", W, D, H, M, S);
        }
    }
}

