        {
            double lat, slat, lng, ref1;
            int h;
 
            Console.WriteLine("Enter latitude");
            lat = Convert.ToDouble(Console.ReadLine());
            Console.WriteLine("Enter longitude");
            lng = Convert.ToDouble(Console.ReadLine());
            Console.WriteLine("Enter legal meridian");
            ref1 = Convert.ToDouble(Console.ReadLine());
            Console.WriteLine();
 
            slat = Math.Sin(DR(lat));
            Console.WriteLine("sine of latitude: {0:0.000}", slat);
            Console.WriteLine("diff longitude: {0:0.000}", lng - ref1);
            Console.WriteLine();
 
            Console.WriteLine("Hour, sun hour angle, dial hour line angle from 6am to 6pm");
 
            for (h = -6; h <= 6; h++)
            {
                double hla, hra;
                hra = 15.0 * h;
                hra = hra - lng + ref1;
                hla = RD(Math.Atan(slat * Math.Tan(DR(hra))));
                Console.WriteLine("HR= {0:000};  \t  HRA={1:000.000};  \t  HLA= {2:000.000}", h, hra, hla);
            }
 
            Console.ReadLine();
        }
 
        static double DR(double x)
        {
            return (x * Math.PI / 180.0);
        }
 
        static double RD(double x)
        {
            return (x * 180.0 / Math.PI);
        }
    }
