    class Program
    {
        static void Main(string[] args)
        {
            List<double> coeffs = new List<double>();
            coeffs.Add(-19.0);
            coeffs.Add(7.0);
            coeffs.Add(-4.0);
            coeffs.Add(6.0);
            Console.WriteLine(polyEval(coeffs, 3));
        }
 
        public static double polyEval(List<double> coefficients, double x)
        {
            coefficients.Reverse();
            double accumulator = coefficients.ElementAt(0);
            for (int i = 1; i < coefficients.Count; i++)
            {
                accumulator = (accumulator * x) + coefficients.ElementAt(i);
            }
            return accumulator;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace EgyptianFractions
{
    class Program
    {
        public struct Pair
        {
            public long md;
            public int tc;
        }
 
        public static long mod(long x, long y)
        {
            return ((x % y) + y) % y;
        }
 
        public static long gcd(long a, long b)
        {
            if (0 == a) return b;
            if (0 == b) return a;
            if (a == b) return a;
            if (a > b) return gcd(a - b, b);
            return gcd(a, b - a);
        }
 
        public static void write0(bool show, string str)
        {
            if (show)
            {
                Console.Write(str);
            }
        }
 
        public static void write1(bool show, string format, long a)
        {
            if (show)
            {
                Console.Write(format, a);
            }
        }
 
        public static void write2(bool show, string format, long a, long b)
        {
            if (show)
            {
                Console.Write(format, a, b);
            }
        }
 
        public static Pair egyptian(long x, long y, bool show)
        {
            Pair ret;
            long acc = 0;
            bool first = true;
 
            ret.tc = 0;
            ret.md = 0;
 
            write2(show, "Egyptian fraction for {0}/{1}: ", x, y);
            while (x > 0)
            {
                long z = (y + x - 1) / x;
                if (z == 1)
                {
                    acc++;
                }
                else
                {
                    if (acc > 0)
                    {
                        write1(show, "{0} + ", acc);
                        first = false;
                        acc = 0;
                        ret.tc++;
                    }
                    else if (first)
                    {
                        first = false;
                    }
                    else
                    {
                        write0(show, " + ");
                    }
                    if (z > ret.md)
                    {
                        ret.md = z;
                    }
                    write1(show, "1/{0}", z);
                    ret.tc++;
                }
                x = mod(-y, x);
                y = y * z;
            }
            if (acc > 0)
            {
                write1(show, "{0}", acc);
                ret.tc++;
            }
            write0(show, "\n");
 
            return ret;
        }
 
        static void Main(string[] args)
        {
            Pair p;
            long nm = 0, dm = 0, dmn = 0, dmd = 0, den = 0;
            int tm, i, j;
 
            egyptian(43, 48, true);
            egyptian(5, 121, true); // final term cannot be represented correctly
            egyptian(2014, 59, true);
 
            tm = 0;
            for (i = 1; i < 100; i++)
            {
                for (j = 1; j < 100; j++)
                {
                    p = egyptian(i, j, false);
                    if (p.tc > tm)
                    {
                        tm = p.tc;
                        nm = i;
                        dm = j;
                    }
                    if (p.md > den)
                    {
                        den = p.md;
                        dmn = i;
                        dmd = j;
                    }
                }
            }
            Console.WriteLine("Term max is {0}/{1} with {2} terms.", nm, dm, tm); // term max is correct
            Console.WriteLine("Denominator max is {0}/{1}", dmn, dmd);           // denominator max is not correct
            egyptian(dmn, dmd, true);                                           // enough digits cannot be represented without bigint
 
            Console.ReadKey();
        }
    }
}

