    class OIDListSorting
    {
        static void Main(string[] args)
        {
            var dot = "\\.";
 
            var oids_comparator = new Func<string, string, int>((o1, o2) =>
            {
                var o1Numbers = o1.Split(dot);
                var o2Numbers = o2.Split(dot);
                for (int i = 0; ; i++)
                {
                    if (i == o1Numbers.Length && i == o2Numbers.Length)
                        return 0;
                    if (i == o1Numbers.Length)
                        return -1;
                    if (i == o2Numbers.Length)
                        return 1;
                    var nextO1Number = int.Parse(o1Numbers[i]);
                    var nextO2Number = int.Parse(o2Numbers[i]);
                    var result = nextO1Number.CompareTo(nextO2Number);
                    if (result!= 0)
                        return result;
                }
            });
 
            new List<string> { "1.3.6.1.4.1.11.2.17.19.3.4.0.10", "1.3.6.1.4.1.11.2.17.5.2.0.79", "1.3.6.1.4.1.11.2.17.19.3.4.0.4",
                  "1.3.6.1.4.1.11150.3.4.0.1", "1.3.6.1.4.1.11.2.17.19.3.4.0.1", "1.3.6.1.4.1.11150.3.4.0" }
               .Sort(oids_comparator);
 
            foreach (var oid in new List<string> { "1.3.6.1.4.1.11.2.17.19.3.4.0.10", "1.3.6.1.4.1.11.2.17.5.2.0.79", "1.3.6.1.4.1.11.2.17.19.3.4.0.4",
                  "1.3.6.1.4.1.11150.3.4.0.1", "1.3.6.1.4.1.11.2.17.19.3.4.0.1", "1.3.6.1.4.1.11150.3.4.0" })
            {
                Console.WriteLine(oid);
            }
        }
    }
