using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
 
namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            Filter<int, PowersGenerator<int, 2>, PowersGenerator<int, 3>> gen = new Filter<int, PowersGenerator<int, 2>, PowersGenerator<int, 3>>();
 
            for (int i = 0; i < 20; ++i)
                gen();
 
            for (int i = 20; i < 30; ++i)
                Console.WriteLine(i + ": " + gen());
 
            Console.ReadKey();
        }
    }
 
    public class Generator<T>
    {
        public virtual T operator()() { return default(T); }
    }
 
    public class PowersGenerator<T, P> : Generator<T> { }
 
    public class PowersGenerator<T> : Generator<T>
    {
        public int i;
        public PowersGenerator() { i = 1; }
        public override T operator()()
        {
            T o = default(T);
            for (int j = 0; j < 2; ++j) o = (dynamic)o * i;
            ++i;
            return o;
        }
    }
 
    public class Filter<T, G, F> : Generator<T>
    {
        public G gen;
        public F filter;
        public T lastG, lastF;
 
        public Filter() { lastG = gen(); lastF = filter(); }
 
        public override T operator()()
        {
            while (lastG >= lastF)
            {
                if (lastG == lastF)
                    lastG = gen();
                lastF = filter();
            }
 
            T out1 = lastG;
            lastG = gen();
            return out1;
        }
    }
}

