class Scanner
{
    private StreamReader _sr;
    private string _line;
    private int _pos;
    private int _length;
    private char _separator ='';
    private Queue<string> _buffer = new Queue<string>();
    public Scanner(StreamReader sr)
    {
        _sr = sr;
        _line = sr.ReadLine();
        _pos = 0;
        _length = _line.Length;
    }
    public bool hasNext()
    {
        if (_buffer.Count > 0) return true;
        if (_pos < _length) return true;
        _line = _sr.ReadLine();
        if (_line == null) return false;
        _pos = 0;
        _length = _line.Length;
        return _length > 0;
    }
    public bool hasNext(char separator)
    {
        _separator = separator;
        return hasNext();
    }
    public string next()
    {
        if (_buffer.Count > 0) return _buffer.Dequeue();
        if (_pos < _length)
        {
            var end = _line.IndexOf(_separator, _pos);
            if (end == -1) end = _length;
            var result = _line.Substring(_pos, end - _pos);
            _pos = end + 1;
            return result;
        }
        _line = _sr.ReadLine();
        if (_line == null) throw new Exception("No more values");
        _pos = 0;
        _length = _line.Length;
        return next();
    }
    public string next(char separator)
    {
        _separator = separator;
        return next();
    }
    public string nextLine()
    {
        var result = _line.Substring(_pos);
        _line = _sr.ReadLine();
        if (_line == null) return result;
        _pos = 0;
        _length = _line.Length;
        return result;
    }
    public int nextInt()
    {
        return int.Parse(next());
    }
    public int nextInt(char separator)
    {
        return int.Parse(next(separator));
    }
    public long nextLong()
    {
        return long.Parse(next());
    }
    public long nextLong(char separator)
    {
        return long.Parse(next(separator));
    }
    public double nextDouble()
    {
        return double.Parse(next());
    }
    public double nextDouble(char separator)
    {
        return double.Parse(next(separator));
    }
    public void close()
    {
        _sr.Close();
    }
}

