using System;
using System.Collections.Generic;
using System.Linq;
 
namespace ConvexHull
{
    class Program
    {
        static void Main(string[] args)
        {
            var points = new List<Point>
            {
                new Point(16,3),
                new Point(12,17),
                new Point(0,6),
                new Point(-4,-6),
                new Point(16,6),
                new Point(16,-7),
                new Point(16,-3),
                new Point(17,-4),
                new Point(5,19),
                new Point(19,-8),
                new Point(3,16),
                new Point(12,13),
                new Point(3,-4),
                new Point(17,5),
                new Point(-3,15),
                new Point(-3,-9),
                new Point(0,11),
                new Point(-9,-3),
                new Point(-4,-2),
                new Point(12,10)
            };
 
            var hull = CalculateConvexHull(points);
 
            hull.ForEach(pt => Console.WriteLine(pt));
        }
 
        static List<Point> CalculateConvexHull(List<Point> points)
        {
            //There must be at least 3 points
            if (points.Count < 3) return points;
 
            var hull = new List<Point>();
 
            //Find the left most point in the polygon
            var leftMostIdx = points.Select((pt, idx) => new { pt, idx })
               .OrderBy(x => x.pt.X)
               .First().idx;
 
            var p = leftMostIdx;
            var q = 0;
 
            while (true)
            {
                //The left most point must be part of the hull
                hull.Add(points[p]);
 
                q = (p + 1) % points.Count;
 
                for (var i = 0; i < points.Count; i++)
                {
                    if (Orientation(points[p], points[i], points[q]) == 2)
                    {
                        q = i;
                    }
                }
 
                p = q;
 
                //Break from loop once we reach the first point again
                if (p == leftMostIdx) break;
            }
 
            return hull;
        }
 
        //Calculate orientation for 3 points
        //0 -> Straight line
        //1 -> Clockwise
        //2 -> Counterclockwise
        static int Orientation(Point p, Point q, Point r)
        {
            var val = (q.Y - p.Y) * (r.X - q.X) -
                (q.X - p.X) * (r.Y - q.Y);
 
            if (val == 0) return 0;
            if (val > 0) return 1;
            return 2;
        }
    }
 
    class Point
    {
        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }
 
        public int X { get; }
        public int Y { get; }
 
        public override string ToString()
        {
            return $"({X}, {Y})";
        }
    }
}

