using System;
 
public class Euler0069
{
    public static int gcd(int n, int k)
    {
        if (n < k || k < 1)
        {
            throw new ArgumentException("Need n >= k and k >= 1");
        }
 
        int s = 1;
        while (n % 2 == 0 && k % 2 == 0)
        {
            n >>= 1;
            k >>= 1;
            s <<= 1;
        }
 
        int t = n;
        if (n % 2!= 0)
        {
            t = -k;
        }
        while (t!= 0)
        {
            while (t % 2 == 0)
            {
                t >>= 1;
            }
            if (t > 0)
            {
                n = t;
            }
            else
            {
                k = -t;
            }
            t = n - k;
        }
        return n * s;
    }
 
    public static int totient(int n)
    {
        int tot = 0;
        for (int k = 1; k <= n; k++)
        {
            if (gcd(n, k) == 1)
            {
                tot++;
            }
        }
        return tot;
    }
 
    public static void Main(string[] args)
    {
        Console.WriteLine(" n  phi   prime");
        Console.WriteLine("---------------");
        int count = 0;
        for (int n = 1; n <= 25; n++)
        {
            int tot = totient(n);
            bool isPrime = n - 1 == tot;
            if (isPrime)
            {
                count++;
            }
            Console.WriteLine("{0,2}   {1,2}   {2}", n, tot, isPrime);
        }
        Console.WriteLine("\nNumber of primes up to 25     = {0}", count);
        for (int n = 26; n <= 100000; n++)
        {
            int tot = totient(n);
            if (tot == n - 1)
            {
                count++;
            }
            if (n == 100 || n == 1000 || n % 10000 == 0)
            {
                Console.WriteLine("\nNumber of primes up to {0,-6} = {1}", n, count);
            }
        }
    }
}

