namespace Dijkstra
{
    class Program
    {
        static void Main(string[] args)
        {
            var graph = new Graph(new List<Edge>
            {
                new Edge("a", "b", 7),
                new Edge("a", "c", 9),
                new Edge("a", "f", 14),
                new Edge("b", "c", 10),
                new Edge("b", "d", 15),
                new Edge("c", "d", 11),
                new Edge("c", "f", 2),
                new Edge("d", "e", 6),
                new Edge("e", "f", 9)
            });
            var path = graph.Dijkstra("a", "e");
            Console.WriteLine(string.Join(" -> ", path));
            Console.ReadKey();
        }
    }
 
    class Edge
    {
        public string Start { get; set; }
        public string End { get; set; }
        public int Cost { get; set; }
 
        public Edge(string start, string end, int cost)
        {
            Start = start;
            End = end;
            Cost = cost;
        }
    }
 
    class Graph
    {
        private List<Edge> _edges;
        private HashSet<string> _vertices;
 
        public Graph(List<Edge> edges)
        {
            _edges = edges;
            _vertices = new HashSet<string>();
            foreach (var edge in edges)
            {
                _vertices.Add(edge.Start);
                _vertices.Add(edge.End);
            }
        }
 
        public List<string> Dijkstra(string source, string dest)
        {
            var dist = new Dictionary<string, int>();
            var previous = new Dictionary<string, string>();
            foreach (var vertex in _vertices)
            {
                dist[vertex] = int.MaxValue;
                previous[vertex] = null;
            }
            dist[source] = 0;
            var q = new HashSet<string>(_vertices);
            var neighbours = new Dictionary<string, HashSet<Tuple<string, int>>>();
            foreach (var vertex in _vertices)
            {
                neighbours[vertex] = new HashSet<Tuple<string, int>>();
            }
            foreach (var edge in _edges)
            {
                neighbours[edge.Start].Add(new Tuple<string, int>(edge.End, edge.Cost));
                neighbours[edge.End].Add(new Tuple<string, int>(edge.Start, edge.Cost));
            }
 
            while (q.Any())
            {
                var u = q.OrderBy(x => dist[x]).First();
                q.Remove(u);
                if (dist[u] == int.MaxValue || u == dest)
                {
                    break;
                }
                foreach (var v in neighbours[u])
                {
                    var alt = dist[u] + v.Item2;
                    if (alt < dist[v.Item1])
                    {
                        dist[v.Item1] = alt;
                        previous[v.Item1] = u;
                    }
                }
            }
 
            var s = new Stack<string>();
            var u1 = dest;
            while (previous[u1]!= null)
            {
                s.Push(u1);
                u1 = previous[u1];
            }
            s.Push(u1);
            return s.ToList();
        }
    }
}

task_description:
Task

Write a program that prints the integers from   1   to   100   (inclusive).



But:

   for multiples of three,   print   Fizz     (instead of the number)
   for multiples of five,   print   Buzz     (instead of the number)
   for multiples of both three and five,   print   FizzBuzz     (instead of the number) 


The   FizzBuzz   problem was presented as the lowest level of comprehension required to illustrate adequacy.



Also see

   (a blog)   dont-overthink-fizzbuzz
   (a blog)   fizzbuzz-the-programmers-stairway-to-heaven

code:
using System;

namespace FizzBuzz
{
    class Program
    {
        static void Main(string[] args)
        {
            for (int number = 1; number <= 100; number++)
            {
                if (number % 15 == 0)
                {
                    Console.WriteLine("FizzBuzz");
                }
                else if (number % 3 == 0)
                {
                    Console.WriteLine("Fizz");
                }
                else if (number % 5 == 0)
                {
                    Console.WriteLine("Buzz");
                }
                else
                {
                    Console.WriteLine(number);
                }
            }
        }
    }
}

