using System;
using System.Collections.Generic;
using System.Linq;
 
namespace MatrixChainMultiplication
{
    class Program
    {
        static List<int[]> m;
        static List<int[]> s;
 
        static void OptimalMatrixChainOrder(int[] dims)
        {
            int n = dims.Length - 1;
            m = new List<int[]>();
            s = new List<int[]>();
            for (int i = 0; i < n; i++)
            {
                m.Add(new int[n]);
                s.Add(new int[n]);
            }
            for (int len = 1; len < n; len++)
            {
                for (int i = 0; i < n - len; i++)
                {
                    int j = i + len;
                    m[i][j] = int.MaxValue;
                    for (int k = i; k < j; k++)
                    {
                        int temp = dims[i] * dims[k + 1] * dims[j + 1];
                        int cost = m[i][k] + m[k + 1][j] + temp;
                        if (cost < m[i][j])
                        {
                            m[i][j] = cost;
                            s[i][j] = k;
                        }
                    }
                }
            }
        }
 
        static void PrintOptimalChainOrder(int i, int j)
        {
            if (i == j)
                Console.Write((char)(i + 65));
            else
            {
                Console.Write("(");
                PrintOptimalChainOrder(i, s[i][j]);
                PrintOptimalChainOrder(s[i][j] + 1, j);
                Console.Write(")");
            }
        }
 
        static void Main(string[] args)
        {
            var dimsList = new List<int[]>
            {
                new int[] { 5, 6, 3, 1 },
                new int[] { 1, 5, 25, 30, 100, 70, 2, 1, 100, 250, 1, 1000, 2 },
                new int[] { 1000, 1, 500, 12, 1, 700, 2500, 3, 2, 5, 14, 10 }
            };
            foreach (var dims in dimsList)
            {
                Console.WriteLine($"Dims  : {dims.ToList()}");
                OptimalMatrixChainOrder(dims);
                Console.Write("Order : ");
                PrintOptimalChainOrder(0, s.Count - 1);
                Console.WriteLine($"\nCost  : {m[0][s.Count - 1]}\n");
            }
        }
    }
}

