             * Tic-tac-toe game player.
             * Input the index of where you wish to place your mark at your turn.
             */
            List<char> board = new List<char> { '1', '2', '3', '4', '5', '6', '7', '8', '9' };
            List<List<int>> wins = new List<List<int>> { new List<int> { 0, 1, 2 }, new List<int> { 3, 4, 5 }, new List<int> { 6, 7, 8 }, new List<int> { 0, 3, 6 }, new List<int> { 1, 4, 7 }, new List<int> { 2, 5, 8 }, new List<int> { 0, 4, 8 }, new List<int> { 2, 4, 6 } };
            Random random = new Random();
            bool finished = false;
            char xo = 'X';
            while (!finished)
            {
                Tuple<char, List<int>> s = me(board, wins, random, xo);
                if (s.Item1!= null)
                {
                    printboard(board);
                    Console.WriteLine("\n{0} wins across {1}", s.Item1, s.Item2);
                    break;
                }
                if (!finished)
                {
                    s = you(board, wins, random, xo);
                    if (s.Item1!= null)
                    {
                        printboard(board);
                        Console.WriteLine("\n{0} wins across {1}", s.Item1, s.Item2);
                        break;
                    }
                }
            }
            Console.ReadLine();
        }
        static void printboard(List<char> board)
        {
            Console.WriteLine(string.Join(" ", board.GetRange(0, 3)));
            Console.WriteLine(string.Join(" ", board.GetRange(3, 3)));
            Console.WriteLine(string.Join(" ", board.GetRange(6, 3)));
        }
        static Tuple<char, List<int>> score(List<char> board, List<List<int>> wins)
        {
            foreach (List<int> w in wins)
            {
                char b = board[w[0]];
                if (b!='' && w.All(i => board[i] == b))
                {
                    return new Tuple<char, List<int>>(b, w.Select(i => i + 1).ToList());
                }
            }
            return new Tuple<char, List<int>>(null, null);
        }
        static bool finished(List<char> board)
        {
            return board.All(b => b!='');
        }
        static List<int> space(List<char> board)
        {
            return board.Select((b, i) => new { b, i }).Where(x => x.b!= 'X' && x.b!= 'O').Select(x => x.i).ToList();
        }
        static int my_turn(List<char> board, List<List<int>> wins, Random random, char xo)
        {
            List<int> options = space(board);
            int choice = options[random.Next(options.Count)];
            board[choice - 1] = xo;
            return choice;
        }
        static int your_turn(List<char> board, List<List<int>> wins, Random random, char xo)
        {
            List<int> options = space(board);
            int choice = 0;
            while (true)
            {
                Console.WriteLine("Put your {0} in any of these positions: {1}", xo, string.Join("", options));
                string input = Console.ReadLine();
                if (int.TryParse(input, out choice) && options.Contains(choice))
                {
                    break;
                }
                Console.WriteLine("Whoops I don't understand the input");
            }
            board[choice - 1] = xo;
            return choice;
        }
        static Tuple<char, List<int>> me(List<char> board, List<List<int>> wins, Random random, char xo)
        {
            printboard(board);
            Console.WriteLine("I go at {0}", my_turn(board, wins, random, xo));
            return score(board, wins);
        }
        static Tuple<char, List<int>> you(List<char> board, List<List<int>> wins, Random random, char xo)
        {
            printboard(board);
            // Call my_turn(xo) below for it to play itself
            Console.WriteLine("You went at {0}", your_turn(board, wins, random, xo));
            return score(board, wins);
        }
    }
}

