    public class Point : DynamicObject
    {
        public int x { get; set; }
        public int y { get; set; }
 
        public Point(int x, int y)
        {
            this.x = x;
            this.y = y;
        }
 
        public override bool TryGetMember(GetMemberBinder binder, out object result)
        {
            result = this.GetType().GetProperty(binder.Name).GetValue(this);
            return true;
        }
 
        public override bool TrySetMember(SetMemberBinder binder, object value)
        {
            this.GetType().GetProperty(binder.Name).SetValue(this, value);
            return true;
        }
 
        public override bool TryGetIndex(GetIndexBinder binder, object[] indexes, out object result)
        {
            result = this.GetType().GetProperty((string)indexes[0]).GetValue(this);
            return true;
        }
 
        public override bool TrySetIndex(SetIndexBinder binder, object[] indexes, object value)
        {
            this.GetType().GetProperty((string)indexes[0]).SetValue(this, value);
            return true;
        }
 
        public override IEnumerable<string> GetDynamicMemberNames()
        {
            return this.GetType().GetProperties().Select(p => p.Name);
        }
 
        public override string ToString()
        {
            return string.Format("x : {0}, y : {1}", this.x, this.y);
        }
    }
}

using System;
using System.Runtime.InteropServices;
 
namespace StringCopy
{
    class Program
    {
        static void Main(string[] args)
        {
            int len;
            string src = "Hello";
            string dst1 = new string(' ', 80);
            string dst2 = new string(' ', 80);
            string dst3;
            string ref1;
 
            /*
             * Option 1. Use strcpy() from <string.h>.
             *
             * DANGER! strcpy() can overflow the destination buffer.
             * strcpy() is only safe if the source string is shorter than
             * the destination buffer. We know that "Hello" (6 characters
             * with the final '\0') easily fits in dst1 (80 characters).
             */
            strcpy(dst1, src);
 
            /*
             * Option 2. Use strlen() and memcpy() from <string.h>, to copy
             * strlen(src) + 1 bytes including the final '\0'.
             */
            len = strlen(src);
            if (len >= dst2.Length)
            {
                Console.WriteLine("The buffer is too small!");
                Environment.Exit(1);
            }
            memcpy(dst2, src, len + 1);
 
            /*
             * Option 3. Use strdup() from <string.h>, to allocate a copy.
             */
            dst3 = strdup(src);
            if (dst3 == null)
            {
                /* Failed to allocate memory! */
                Console.WriteLine("Failed to allocate memory!");
                Environment.Exit(1);
            }
 
            /* Create another reference to the source string. */
            ref1 = src;
 
            /* Modify the source string, not its copies. */
            memset(src, '-', 5);
 
            Console.WriteLine(" src: {0}", src);   /*  src: ----- */
            Console.WriteLine("dst1: {0}", dst1);  /* dst1: Hello */
            Console.WriteLine("dst2: {0}", dst2);  /* dst2: Hello */
            Console.WriteLine("dst3: {0}", dst3);  /* dst3: Hello */
            Console.WriteLine(" ref: {0}", ref1);   /*  ref: ----- */
 
            /* Free memory from strdup(). */
            free(dst3);
        }
 
        [DllImport("msvcrt.dll", EntryPoint = "memcpy", CallingConvention = CallingConvention.Cdecl)]
        public static extern IntPtr memcpy(IntPtr dest, string src, int count);
 
        [DllImport("msvcrt.dll", EntryPoint = "memset", CallingConvention = CallingConvention.Cdecl)]
        public static extern IntPtr memset(string dest, int c, int count);
 
        [DllImport("msvcrt.dll", EntryPoint = "strcpy", CallingConvention = CallingConvention.Cdecl)]
        public static extern IntPtr strcpy(string dest, string src);
 
        [DllImport("msvcrt.dll", EntryPoint = "strdup", CallingConvention = CallingConvention.Cdecl)]
        public static extern string strdup(string str);
 
        [DllImport("msvcrt.dll", EntryPoint = "strlen", CallingConvention = CallingConvention.Cdecl)]
        public static extern int strlen(string str);
 
        [DllImport("msvcrt.dll", EntryPoint = "free", CallingConvention = CallingConvention.Cdecl)]
        public static extern void free(string str);
    }
}

