using System;
using System.Collections.Generic;
using System.Linq;
using static System.Math;
using static System.Console;
 
namespace PythagoreanTriples
{
    class Program
    {
        static void Main(string[] args)
        {
            var result = new List<dynamic>
            {
                new { maxPerimeter = 10, triples = 4, primitives = 0 },
                new { maxPerimeter = 100, triples = 16, primitives = 8 },
                new { maxPerimeter = 1000, triples = 168, primitives = 84 }
            };
 
            WriteLine(string.Join(Environment.NewLine, result));
        }
 
        // pythTripleCount :: ((Int, Int, Int) -> Bool) -> Int -> Int
        static int pythTripleCount(Func<int, int, int, bool> p, int maxPerim)
        {
            var xs = enumFromTo(1, (int)Floor(maxPerim / 2));
 
            return xs.SelectMany(x => xs.Skip(x).SelectMany(y => xs.Skip(y).Select(z =>
                (x + y + z <= maxPerim) && ((x * x) + (y * y) == z * z) && p(x, y, z)?
                new[] { new[] { x, y, z } } : new int[0]
            ))).Count();
        }
 
        // enumFromTo :: Int -> Int -> [Int]
        static IEnumerable<int> enumFromTo(int m, int n) =>
            Enumerable.Range(m, 1 + n - m);
    }
}

using System;
using System.Text;
 
namespace StringTest
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Starts with Test ( Hello,Hell ) : {0}", startsWith("Hello", "Hell"));
            Console.WriteLine("Ends with Test ( Code,ode ) : {0}", endsWith("Code", "ode"));
            Console.WriteLine("Contains Test ( Google,msn ) : {0}", doesContain("Google", "msn"));
        }
 
        static bool startsWith(string container, string target)
        {
            int clen = container.Length, tlen = target.Length;
            if (clen < tlen)
                return false;
            return container.Substring(0, tlen) == target;
        }
 
        static bool endsWith(string container, string target)
        {
            int clen = container.Length, tlen = target.Length;
            if (clen < tlen)
                return false;
            return container.Substring(clen - tlen, tlen) == target;
        }
 
        static bool doesContain(string container, string target)
        {
            return container.IndexOf(target)!= -1;
        }
    }
}

