        {
            for (int m = 1; m <= 10; m++)
            {
                List<int> list = new List<int>();
                for (int n = 1; n <= 10; n++)
                {
                    list.Add(mfac(n, m));
                }
                Console.WriteLine("{0}: {1}", m, string.Join(", ", list));
            }
            Console.ReadLine();
        }

        static int mfac(int n, int m)
        {
            return Enumerable.Range(n, 10 - n).Where(x => x % m == 0).Aggregate(1, (a, b) => a * b);
        }
    }
