using System;
 
public class Program
{
    public static void Main()
    {
        string[] candidates = new string[] {
            "037833100",
            "17275R102",
            "38259P508",
            "594918104",
            "68389X106",
            "68389X105",
        };
 
        foreach (string candidate in candidates)
        {
            string b;
            if (isCusip(candidate))
            {
                b = "correct";
            }
            else
            {
                b = "incorrect";
            }
            Console.WriteLine("{0} -> {1}", candidate, b);
        }
    }
 
    public static bool isCusip(string s)
    {
        if (s.Length!= 9) return false;
        int sum = 0;
        for (int i = 0; i < 8; i++)
        {
            char c = s[i];
            int v;
            switch (c)
            {
                case '0':
                case '1':
                case '2':
                case '3':
                case '4':
                case '5':
                case '6':
                case '7':
                case '8':
                case '9':
                    v = c - 48;
                    break;
                case 'A':
                case 'B':
                case 'C':
                case 'D':
                case 'E':
                case 'F':
                case 'G':
                case 'H':
                case 'I':
                case 'J':
                case 'K':
                case 'L':
                case 'M':
                case 'N':
                case 'O':
                case 'P':
                case 'Q':
                case 'R':
                case 'S':
                case 'T':
                case 'U':
                case 'V':
                case 'W':
                case 'X':
                case 'Y':
                case 'Z':
                    v = c - 55;
                    break;
                case '*':
                    v = 36;
                    break;
                case '@':
                    v = 37;
                    break;
                case '#':
                    v = 38;
                    break;
                default:
                    return false;
            }
            if (i % 2 == 1) v *= 2;  // check if odd as using 0-based indexing
            sum += v / 10 + v % 10;
        }
        return s[8] - 48 == (10 - (sum % 10)) % 10;
    }
}

