using System.Runtime.CompilerServices;

namespace MinRec
{
    class Program
    {
        static void Main(string[] args)
        {
            var minrec = new Minrec();
            Console.WriteLine("\nMINIMUM STEPS TO 1: Recursive algorithm");
            Console.WriteLine("  Possible divisors:  {0}", string.Join(", ", minrec.divs));
            Console.WriteLine("  Possible decrements: {0}", string.Join(", ", minrec.subs));
            for (int n = 1; n <= 10; n++)
            {
                var steps = minrec.Minrec(n);
                Console.WriteLine("    minrec({0,2}) in {1,2} by: {2}", n, steps.Count, string.Join(", ", steps));
            }

            int upto = 2000;
            Console.WriteLine("\n    Those numbers up to {0} that take the maximum, \"minimal steps down to 1\":", upto);
            var stepn = minrec.Stepn(upto);
            var mx = stepn.Max(x => x.Count);
            var ans = stepn.Where(x => x.Count == mx).Select(x => x.N);
            Console.WriteLine("      Taking {0} steps is/are the {1} numbers: {2}", mx, ans.Count(), string.Join(", ", ans));
            Console.WriteLine();
        }
    }

    public class Minrec
    {
        public HashSet<int> divs = new HashSet<int> { 2, 3 };
        public HashSet<int> subs = new HashSet<int> { 1 };

        public List<string> Minrec(int n)
        {
            if (n == 1)
                return new List<string> { "=1" };
            var possibles = new Dictionary<string, List<string>>();
            foreach (var d in divs)
            {
                if (n % d == 0)
                    possibles[string.Format("/{0}=>{1:2}", d, n / d)] = Minrec(n / d);
            }
            foreach (var s in subs)
            {
                if (n > s)
                    possibles[string.Format("-{0}=>{1:2}", s, n - s)] = Minrec(n - s);
            }
            var thiskind = possibles.OrderBy(x => x.Value.Count).First().Key;
            var otherkinds = possibles[thiskind];
            var ret = new List<string> { thiskind };
            ret.AddRange(otherkinds);
            return ret;
        }

        public List<List<string>> Stepn(int upto)
        {
            var stepn = new List<List<string>>();
            for (int n = upto; n > 0; n--)
            {
                stepn.Add(Minrec(n));
            }
            return stepn;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
