namespace Polynomial
{
    class Program
    {
        static void Main(string[] args)
        {
            Func<int, Polynomial> x_minus_1_to_the = (p) =>
            {
                return new Polynomial(new BigInteger[] { -1, 1 }) ** p;
            };
 
            Func<int, bool> prime = (p) =>
            {
                return false;
            };
 
            for (int n = 0; n < 8; n++)
            {
                Console.WriteLine("(x-1)^{0} = {1}", n, x_minus_1_to_the(n).ToString().Replace("**", "^").Replace("*", ""));
            }
 
            Console.WriteLine("\nPrimes below 50:");
            for (int n = 0; n < 50; n++)
            {
                if (prime(n))
                {
                    Console.Write(n + ",");
                }
            }
        }
    }
 
    class Polynomial
    {
        public BigInteger[] coefs;
 
        public Polynomial(BigInteger[] coefs)
        {
            this.coefs = coefs;
        }
 
        public static Polynomial operator *(Polynomial a, Polynomial b)
        {
            BigInteger[] coefs = new BigInteger[a.coefs.Length + b.coefs.Length - 1];
            for (int i = 0; i < a.coefs.Length; i++)
            {
                for (int j = 0; j < b.coefs.Length; j++)
                {
                    coefs[i + j] += a.coefs[i] * b.coefs[j];
                }
            }
            return new Polynomial(coefs);
        }
 
        public static Polynomial operator +(Polynomial a, Polynomial b)
        {
            BigInteger[] coefs = new BigInteger[Math.Max(a.coefs.Length, b.coefs.Length)];
            for (int i = 0; i < coefs.Length; i++)
            {
                coefs[i] = (i < a.coefs.Length? a.coefs[i] : 0) + (i < b.coefs.Length? b.coefs[i] : 0);
            }
            return new Polynomial(coefs);
        }
 
        public static Polynomial operator -(Polynomial a, Polynomial b)
        {
            BigInteger[] coefs = new BigInteger[Math.Max(a.coefs.Length, b.coefs.Length)];
            for (int i = 0; i < coefs.Length; i++)
            {
                coefs[i] = (i < a.coefs.Length? a.coefs[i] : 0) - (i < b.coefs.Length? b.coefs[i] : 0);
            }
            return new Polynomial(coefs);
        }
 
        public static Polynomial operator *(Polynomial a, BigInteger b)
        {
            BigInteger[] coefs = new BigInteger[a.coefs.Length];
            for (int i = 0; i < a.coefs.Length; i++)
            {
                coefs[i] = a.coefs[i] * b;
            }
            return new Polynomial(coefs);
        }
 
        public static Polynomial operator /(Polynomial a, BigInteger b)
        {
            BigInteger[] coefs = new BigInteger[a.coefs.Length];
            for (int i = 0; i < a.coefs.Length; i++)
            {
                coefs[i] = a.coefs[i] / b;
            }
            return new Polynomial(coefs);
        }
 
        public static Polynomial operator %(Polynomial a, BigInteger b)
        {
            BigInteger[] coefs = new BigInteger[a.coefs.Length];
            for (int i = 0; i < a.coefs.Length; i++)
            {
                coefs[i] = a.coefs[i] % b;
            }
            return new Polynomial(coefs);
        }
 
        public static Polynomial operator **(Polynomial a, int b)
        {
            Polynomial result = new Polynomial(new BigInteger[] { 1 });
            for (int i = 0; i < b; i++)
            {
                result = result * a;
            }
            return result;
        }
 
        public override string ToString()
        {
            string result = "";
            for (int i = 0; i < coefs.Length; i++)
            {
                if (coefs[i]!= 0)
                {
                    if (i == 0)
                    {
                        result += coefs[i];
                    }
                    else if (i == 1)
                    {
                        result += coefs[i] + "*x";
                    }
                    else
                    {
                        result += coefs[i] + "*x**" + i;
                    }
                    if (i < coefs.Length - 1 && coefs[i + 1] > 0)
                    {
                        result += "+";
                    }
                }
            }
            return result;
        }
    }
}

using System;
