namespace WindowsFormsApplication1
{
    public partial class Form1 : Form
    {
        public Form1()
        {
            InitializeComponent();
            this.Paint += new PaintEventHandler(Form1_Paint);
        }
 
        void Form1_Paint(object sender, PaintEventArgs e)
        {
            int width = 640;
            int height = 400;
            int columnCount = 8;    // number of columns 
            int rowCount = 4;    // number of rows
            int direction = 1;    // 1 = from left to right, 0 = from right to left
            int blackLeft = 1;    // black is left: 1 = true, 0 = false
            for (int j = 0; j < rowCount; j++)
            {
                for (int i = 0; i < columnCount; i++)
                {
                    e.Graphics.FillRectangle(
                        new SolidBrush(Color.FromArgb(0, 0, 0, (byte)((blackLeft - (1 / (columnCount - 1) * i)) * direction))),
                        (width / columnCount) * i, (height / rowCount) * j,
                        (width / columnCount), (height / rowCount)
                        );
                }
                columnCount *= 2;
                direction *= -1;
                blackLeft = blackLeft == 0? 1 : 0;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace Hopido
{
    class Program
    {
        static string[] board = {
            ".00.00.",
            "0000000",
            "0000000",
            ".00000.",
            "..000..",
            "...0..."};

        static int[][] moves = {
            new int[] {-3, 0},
            new int[] {0, 3},
            new int[] {3, 0},
            new int[] {0, -3},
            new int[] {2, 2},
            new int[] {2, -2},
            new int[] {-2, 2},
            new int[] {-2, -2}};

        static int[][] grid;
        static int totalToFill;

        static void Main(string[] args)
        {
            int nRows = board.Length + 6;
            int nCols = board[0].Length + 6;

            grid = new int[nRows][];
            for (int r = 0; r < nRows; r++)
            {
                grid[r] = new int[nCols];
                for (int c = 0; c < nCols; c++)
                    grid[r][c] = -1;
            }

            for (int r = 0; r < nRows; r++)
            {
                for (int c = 3; c < nCols - 3; c++)
                    if (r >= 3 && r < nRows - 3)
                    {
                        if (board[r - 3][c - 3] == '0')
                        {
                            grid[r][c] = 0;
                            totalToFill++;
                        }
                    }
            }

            int pos = -1, r, c;
            do
            {
                do
                {
                    pos++;
                    r = pos / nCols;
                    c = pos % nCols;
                } while (grid[r][c] == -1);

                grid[r][c] = 1;
                if (Solve(r, c, 2))
                    break;
                grid[r][c] = 0;

            } while (pos < nRows * nCols);

            PrintResult();
        }

        static bool Solve(int r, int c, int count)
        {
            if (count > totalToFill)
                return true;

            List<int[]> nbrs = Neighbors(r, c);

            if (nbrs.Count == 0 && count!= totalToFill)
                return false;

            nbrs = nbrs.OrderBy(a => a[2]).ToList();

            foreach (int[] nb in nbrs)
            {
                r = nb[0];
                c = nb[1];
                grid[r][c] = count;
                if (Solve(r, c, count + 1))
                    return true;
                grid[r][c] = 0;
            }

            return false;
        }

        static List<int[]> Neighbors(int r, int c)
        {
            List<int[]> nbrs = new List<int[]>();

            foreach (int[] m in moves)
            {
                int x = m[0];
                int y = m[1];
                if (grid[r + y][c + x] == 0)
                {
                    int num = CountNeighbors(r + y, c + x) - 1;
                    nbrs.Add(new int[] { r + y, c + x, num });
                }
            }
            return nbrs;
        }

        static int CountNeighbors(int r, int c)
        {
            int num = 0;
            foreach (int[] m in moves)
                if (grid[r + m[1]][c + m[0]] == 0)
                    num++;
            return num;
        }

        static void PrintResult()
        {
            for (int r = 0; r < grid.Length; r++)
            {
                for (int c = 0; c < grid[r].Length; c++)
                {
                    if (grid[r][c] == -1)
                        Console.Write("  ");
                    else
                        Console.Write("{0,2}", grid[r][c]);
                }
                Console.WriteLine();
            }
        }
    }
}

