using System;
 
namespace PolyLongDiv
{
    public class IAE : Exception
    {
        public IAE(string message) : base(message) { }
    }
 
    public class Solution
    {
        public double[] quotient;
        public double[] remainder;
 
        public Solution(double[] quotient, double[] remainder)
        {
            this.quotient = quotient;
            this.remainder = remainder;
        }
    }
 
    public class PolyLongDiv
    {
        public static int polyDegree(double[] p)
        {
            for (int i = p.Length - 1; i >= 0; i--)
            {
                if (p[i]!= 0.0) return i;
            }
            return Int32.MinValue;
        }
 
        public static double[] polyShiftRight(double[] p, int places)
        {
            if (places <= 0) return p;
            int pd = polyDegree(p);
            if (pd + places >= p.Length)
            {
                throw new IAE("The number of places to be shifted is too large");
            }
            double[] d = new double[p.Length];
            for (int i = pd; i >= 0; i--)
            {
                d[i + places] = p[i];
                d[i] = 0.0;
            }
            return d;
        }
 
        public static void polyMultiply(double[] p, double m)
        {
            for (int i = 0; i < p.Length; i++) p[i] *= m;
        }
 
        public static void polySubtract(double[] p, double[] s)
        {
            for (int i = 0; i < p.Length; i++) p[i] -= s[i];
        }
 
        public static Solution polyLongDiv(double[] n, double[] d)
        {
            if (n.Length!= d.Length)
            {
                throw new IAE("Numerator and denominator vectors must have the same size");
            }
            int nd = polyDegree(n);
            int dd = polyDegree(d);
            if (dd < 0)
            {
                throw new IAE("Divisor must have at least one one-zero coefficient");
            }
            if (nd < dd)
            {
                throw new IAE("The degree of the divisor cannot exceed that of the numerator");
            }
            double[] n2 = new double[n.Length];
            Array.Copy(n, n2, n.Length);
            double[] q = new double[n.Length];  // all elements zero by default
            while (nd >= dd)
            {
                double[] d2 = polyShiftRight(d, nd - dd);
                q[nd - dd] = n2[nd] / d2[nd];
                polyMultiply(d2, q[nd - dd]);
                polySubtract(n2, d2);
                nd = polyDegree(n2);
            }
            return new Solution(q, n2);
        }
 
        public static void polyShow(double[] p)
        {
            int pd = polyDegree(p);
            for (int i = pd; i >= 0; i--)
            {
                double coeff = p[i];
                if (coeff == 0.0) continue;
                Console.Write(coeff switch
                {
                    1.0  => (i < pd)? " + " : "",
                    -1.0 => (i < pd)? " - " : "-",
                    < 0  => (i < pd)? " - " + (-coeff) : $"{coeff}",
                    _    => (i < pd)? " + " + coeff : $"{coeff}",
                });
                if (i > 1) Console.Write($"x^{i}");
                else if (i == 1) Console.Write("x");
            }
            Console.WriteLine();
        }
 
        public static void Main(string[] args)
        {
            double[] n = new double[] { -42.0, 0.0, -12.0, 1.0 };
            double[] d = new double[] { -3.0, 1.0, 0.0, 0.0 };
            Console.Write("Numerator   : ");
            polyShow(n);
            Console.Write("Denominator : ");
            polyShow(d);
            Console.WriteLine("-------------------------------------");
            Solution s = polyLongDiv(n, d);
            Console.Write("Quotient    : ");
            polyShow(s.quotient);
            Console.Write("Remainder   : ");
            polyShow(s.remainder);
        }
    }
}

using System;
