namespace Factorial
{
    class Program
    {
        static ulong FactorialRecursive(ulong n)
        {
            return n == 0? 1 : n * FactorialRecursive(n - 1);
        }
 
        static ulong FactorialIterative(ulong n)
        {
            return Enumerable.Range(1, (int)n).Aggregate((x, y) => x * y);
        }
 
        static void Main(string[] args)
        {
            for (ulong i = 1; i < 10; i++)
            {
                Console.WriteLine(FactorialRecursive(i));
            }
            for (ulong i = 1; i < 10; i++)
            {
                Console.WriteLine(FactorialIterative(i));
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
 
namespace CherylBirthday
{
    class Program
    {
        enum Month
        {
            May,
            June,
            July,
            August
        }
 
        class Birthday
        {
            public Month Month { get; set; }
            public int Day { get; set; }
 
            public bool MonthUniqueIn(List<Birthday> birthdays)
            {
                return birthdays.Count(birthday => birthday.Month == this.Month) == 1;
            }
 
            public bool DayUniqueIn(List<Birthday> birthdays)
            {
                return birthdays.Count(birthday => birthday.Day == this.Day) == 1;
            }
 
            public bool MonthWithUniqueDayIn(List<Birthday> birthdays)
            {
                return birthdays.Any(birthday => this.Month == birthday.Month && birthday.DayUniqueIn(birthdays));
            }
        }
 
        static Birthday Solution()
        {
            var choices = new List<Birthday>
            {
                new Birthday { Month = Month.May, Day = 15 },
                new Birthday { Month = Month.May, Day = 16 },
                new Birthday { Month = Month.May, Day = 19 },
                new Birthday { Month = Month.June, Day = 17 },
                new Birthday { Month = Month.June, Day = 18 },
                new Birthday { Month = Month.July, Day = 14 },
                new Birthday { Month = Month.July, Day = 16 },
                new Birthday { Month = Month.August, Day = 14 },
                new Birthday { Month = Month.August, Day = 15 },
                new Birthday { Month = Month.August, Day = 17 }
            };
 
            // Albert knows the month but doesn't know the day.
            // So the month can't be unique within the choices.
            var choicesCopy = new List<Birthday>(choices);
            choices.RemoveAll(birthday => birthday.MonthUniqueIn(choicesCopy));
 
            // Albert also knows that Bernard doesn't know the answer.
            // So the month can't have a unique day.
            choicesCopy = new List<Birthday>(choices);
            choices.RemoveAll(birthday => birthday.MonthWithUniqueDayIn(choicesCopy));
 
            // Bernard now knows the answer.
            // So the day must be unique within the remaining choices.
            choicesCopy = new List<Birthday>(choices);
            choices.RemoveAll(birthday =>!birthday.DayUniqueIn(choicesCopy));
 
            // Albert now knows the answer too.
            // So the month must be unique within the remaining choices.
            choicesCopy = new List<Birthday>(choices);
            choices.RemoveAll(birthday =>!birthday.MonthUniqueIn(choicesCopy));
 
            if (choices.Count == 1)
            {
                return choices[0];
            }
 
            return null;
        }
 
        static void Main(string[] args)
        {
            var solution = Solution();
            if (solution!= null)
            {
                Console.WriteLine("Cheryl's birthday is {0} {1}", solution.Month, solution.Day);
            }
            else
            {
                Console.WriteLine("Didn't work!");
            }
        }
    }
}

