namespace LastSunday
{
    class LastSunday
    {
        static readonly string[] months = { "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" };

        public static int[] findLastSunday(int year)
        {
            bool isLeap = isLeapYear(year);

            int[] days = { 31, isLeap? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
            int[] lastDay = new int[12];

            for (int m = 0; i < 12; i++)
            {
                int d;
                for (d = days[m]; getWeekDay(year, m, d)!= 0; d--)
                    ;
                lastDay[m] = d;
            }

            return lastDay;
        }

        private static bool isLeapYear(int year)
        {
            if (year % 4 == 0)
            {
                if (year % 100!= 0)
                    return true;
                else if (year % 400 == 0)
                    return true;
            }
            return false;
        }

        private static int getWeekDay(int y, int m, int d)
        {
            int f = y + d + 3 * m - 1;
            m++;

            if (m < 3)
                y--;
            else
                f -= (int)(0.4 * m + 2.3);

            f += (int)(y / 4) - (int)((y / 100 + 1) * 0.75);
            f %= 7;

            return f;
        }

        private static void display(int year, int[] lastDay)
        {
            Console.WriteLine("\nYEAR: " + year);
            for (int m = 0; i < 12; i++)
                Console.WriteLine(months[m] + ": " + lastDay[m]);
        }

        public static void Main(string[] args)
        {
            Console.Write("Enter year: ");
            int y = int.Parse(Console.ReadLine());

            int[] lastDay = findLastSunday(y);
            display(y, lastDay);
        }
    }
}

using System;
 
public class Perfect
{
    public static int perfect(int n)
    {
        int max = (int)Math.Sqrt((double)n) + 1;
        int tot = 1;
        int i;
 
        for (i = 2; i < max; i++)
            if ( (n % i) == 0 ) {
                tot += i;
                int q = n / i;
                if (q > i)
                    tot += q;
            }
 
        return tot == n;
    }
 
    public static void Main()
    {
        int n;
        for (n = 2; n < 33550337; n++)
            if (perfect(n))
                Console.WriteLine(n);
    }
}

// returns a new matrix
public Matrix mult(Matrix other)
{
    if (this.width!= other.height)
    {
        throw new Exception("error: incompatible sizes");
    }

    var result = new double[this.height][];
    for (var i = 0; i < this.height; i++)
    {
        result[i] = new double[other.width];
        for (var j = 0; j < other.width; j++)
        {
            var sum = 0.0;
            for (var k = 0; k < this.width; k++)
            {
                sum += this.mtx[i][k] * other.mtx[k][j];
            }
            result[i][j] = sum;
        }
    }
    return new Matrix(result);
}

