using System;
using System.Collections.Generic;
using System.Linq;
 
public class Program
{
    public static void Main()
    {
        var a = new[] { 7, 1, 1, 6, 2, 4, 2, 4, 2, 1, 5 };
        Console.WriteLine("[" + string.Join(", ", a) + "]");
        ModeOf(a);
        Console.WriteLine();
        var b = new[] { true, false, true, false, true, true };
        Console.WriteLine("[" + string.Join(", ", b) + "]");
        ModeOf(b);
    }
 
    public static void ModeOf<T>(T[] a)
    {
        var sortedByFreq = a.GroupBy(x => x).OrderByDescending(x => x.Count());
        var maxFreq = sortedByFreq.First().Count();
        var modes = sortedByFreq.TakeWhile(x => x.Count() == maxFreq);
        if (modes.Count() == 1)
            Console.WriteLine("The mode of the collection is {0} which has a frequency of {1}", modes.First().Key, maxFreq);
        else
        {
            Console.Write("There are {0} modes with a frequency of {1}, namely : ", modes.Count(), maxFreq);
            Console.WriteLine(string.Join(", ", modes.Select(x => x.Key)));
        }
    }
}

